WD_ALIGN_PARAGRAPH = WD_TABLE_ALIGNMENT = WD_ALIGN_VERTICAL = WD_ORIENT = None
parse_xml = nsdecls = None
HAS_DOCX: bool | None = None

Workbook = None
Alignment = Border = Font = PatternFill = Side = None
