_DB_PATH_CACHE: dict[int | None, Path] = {}
_ACTIVE_YEAR_CACHE: dict[int | None, dict] = {}
_CACHED_ICON = None


def get_app_icon():
	global _CACHED_ICON
	if _CACHED_ICON is None:
		if APP_ICON_PATH.exists():
			try:
				from PIL import Image as _PILImg
				with _PILImg.open(APP_ICON_PATH) as _im:
					_CACHED_ICON = _im.copy()
			except Exception:
				_CACHED_ICON = "✚"
		else:
			_CACHED_ICON = "✚"
	return _CACHED_ICON


@contextmanager
def connect_master_db() -> Iterator[sqlite3.Connection]:
	connection = sqlite3.connect(DB_PATH, timeout=15)
	connection.row_factory = sqlite3.Row
	connection.execute("PRAGMA foreign_keys = ON")
	connection.execute("PRAGMA journal_mode = WAL")
	connection.execute("PRAGMA synchronous = NORMAL")
	try:
		yield connection
		connection.commit()
	except Exception:
		connection.rollback()
		raise
	finally:
		connection.close()


def get_current_db_path() -> Path:
	try:
		sel_id = ui.session_state.get("active_academic_year_id")
	except Exception:
		sel_id = None
	if sel_id in _DB_PATH_CACHE:
		return _DB_PATH_CACHE[sel_id]
	try:
		ay = get_active_academic_year()
		folder = ay.get("folder_name", "")
		if folder:
			year_dir = APP_DIR / folder
			year_dir.mkdir(parents=True, exist_ok=True)
			year_db = year_dir / "revir_defteri.db"
			if year_db.exists():
				_DB_PATH_CACHE[sel_id] = year_db
				return year_db
			if DB_PATH.exists():
				import shutil
				shutil.copy2(DB_PATH, year_db)
				_DB_PATH_CACHE[sel_id] = year_db
				return year_db
			_DB_PATH_CACHE[sel_id] = year_db
			return year_db
	except Exception:
		pass
	_DB_PATH_CACHE[sel_id] = DB_PATH
	return DB_PATH


@contextmanager
def connect_db() -> Iterator[sqlite3.Connection]:
	connection = sqlite3.connect(get_current_db_path(), timeout=15)
	connection.row_factory = sqlite3.Row
	connection.execute("PRAGMA foreign_keys = ON")
	connection.execute("PRAGMA journal_mode = WAL")
	connection.execute("PRAGMA synchronous = NORMAL")
	try:
		yield connection
		connection.commit()
	except Exception:
		connection.rollback()
		raise
	finally:
		connection.close()


