		fac = rec.get("facility") if (rec and rec.get("facility")) else ""
		notes = rec.get("notes") if (rec and rec.get("notes")) else ""

		if is_done:
			st_badge = "<span style='color:#15803d;font-weight:bold;'>✔ YAPILDI</span>"
