def _sync_guardian_bidirectional_conn(connection: sqlite3.Connection, student_id: int) -> None:
	"""students ve health_profiles tablolarındaki eksik veli ad/telefon alanlarını karşılıklı tamamlar."""
	pid = int(student_id)
	stu_row = connection.execute(
		"SELECT guardian_name, guardian_phone FROM students WHERE id=?",
		(pid,),
	).fetchone()
	hp_row = connection.execute(
		"SELECT guardian_name, guardian_phone FROM health_profiles WHERE student_id=?",
		(pid,),
	).fetchone()
	if not stu_row or not hp_row:
		return

	s_name = (stu_row["guardian_name"] or "").strip() or None
	s_phone = (stu_row["guardian_phone"] or "").strip() or None
	h_name = (hp_row["guardian_name"] or "").strip() or None
	h_phone = (hp_row["guardian_phone"] or "").strip() or None

	merged_name = s_name or h_name
	merged_phone = s_phone or h_phone

	if merged_name != s_name or merged_phone != s_phone:
		connection.execute(
			"UPDATE students SET guardian_name=?, guardian_phone=? WHERE id=?",
			(merged_name, merged_phone, pid),
		)
	if merged_name != h_name or merged_phone != h_phone:
		connection.execute(
			"UPDATE health_profiles SET guardian_name=?, guardian_phone=? WHERE student_id=?",
			(merged_name, merged_phone, pid),
		)


def _upsert_health_profile_fields(person_id: int, fields: dict[str, Any]) -> None:
	"""Kişinin health_profiles kaydını (yoksa oluşturarak) verilen alanlarla atomik olarak günceller."""
	pid = int(person_id)
	clean_map = {col: val for col, val in fields.items() if col in _HEALTH_PROFILE_UPDATABLE_COLS}
	if not clean_map:
		return
	now_iso = datetime.now().isoformat(timespec="minutes")
	with connect_db() as connection:
		stu_g = connection.execute(
			"SELECT guardian_name, guardian_phone FROM students WHERE id=?",
			(pid,),
		).fetchone()
		explicit_g_name = "guardian_name" in clean_map
		explicit_g_phone = "guardian_phone" in clean_map
		g_name = clean_map.pop("guardian_name") if explicit_g_name else (stu_g["guardian_name"] if stu_g else None)
		g_phone = clean_map.pop("guardian_phone") if explicit_g_phone else (stu_g["guardian_phone"] if stu_g else None)

		cols = list(clean_map.keys())
		vals = [clean_map[c] for c in cols]
		col_list = ", ".join(["student_id", "guardian_name", "guardian_phone", "updated_at", *cols])
		placeholders = ", ".join(["?"] * (4 + len(cols)))
		update_parts = [
			"guardian_name=excluded.guardian_name" if explicit_g_name else "guardian_name=COALESCE(health_profiles.guardian_name, excluded.guardian_name)",
			"guardian_phone=excluded.guardian_phone" if explicit_g_phone else "guardian_phone=COALESCE(health_profiles.guardian_phone, excluded.guardian_phone)",
			"updated_at=excluded.updated_at",
			*[f"{col}=excluded.{col}" for col in cols],
		]
		update_clause = ", ".join(update_parts)
		connection.execute(
			f"""INSERT INTO health_profiles({col_list})
			    VALUES ({placeholders})
			    ON CONFLICT(student_id) DO UPDATE SET {update_clause}""",
			(pid, g_name, g_phone, now_iso, *vals),
		)
		# Veli ad/telefon açıkça güncellendiyse students tablosunu da anında güncelle
		if explicit_g_name and str(g_name or "").strip():
			connection.execute("UPDATE students SET guardian_name=? WHERE id=?", (str(g_name).strip(), pid))
		if explicit_g_phone and str(g_phone or "").strip():
			connection.execute("UPDATE students SET guardian_phone=? WHERE id=?", (str(g_phone).strip(), pid))
		_sync_guardian_bidirectional_conn(connection, pid)
	sync_after_person_mutation(pid)


@ui.cache_data(ttl=60, show_spinner=False)
def get_students_enriched(class_name: str | None = None, person_type: str | None = None) -> pd.DataFrame:
	query = """
		SELECT s.id,
			   s.person_type AS kayit_turu,
			   c.name AS sinif,
			   s.student_no AS okul_no,
			   s.full_name AS ad_soyad,
			   s.sex AS cinsiyet,
			   s.birth_date AS dogum_tarihi,
			   s.notes AS notlar,
			   s.country AS ulke,
			   s.province AS il,
			   s.district AS ilce,
			   s.village AS koy,
			   COALESCE(h.guardian_name, s.guardian_name) AS veli,
			   COALESCE(h.guardian_phone, s.guardian_phone) AS veli_telefon,
			   h.blood_group AS kan_grubu,
			   h.allergies AS alerjiler,
			   h.chronic_conditions AS kronik,
			   h.medical_history AS saglik_gecmisi,
			   h.medications AS ilaclar,
			   (SELECT COUNT(*) FROM visits v WHERE v.student_id = s.id) AS basvuru_sayisi,
			   COALESCE(
				   m.measured_on,
				   (SELECT m3.measured_on FROM measurements m3 WHERE m3.student_id = s.id ORDER BY m3.measured_on DESC, m3.id DESC LIMIT 1)
			   ) AS son_olcum_tarihi,
			   COALESCE(
				   m.height_cm,
				   (SELECT m3.height_cm FROM measurements m3 WHERE m3.student_id = s.id AND m3.height_cm IS NOT NULL ORDER BY m3.measured_on DESC, m3.id DESC LIMIT 1)
			   ) AS boy_cm,
			   COALESCE(
				   m.weight_kg,
				   (SELECT m3.weight_kg FROM measurements m3 WHERE m3.student_id = s.id AND m3.weight_kg IS NOT NULL ORDER BY m3.measured_on DESC, m3.id DESC LIMIT 1)
			   ) AS kilo_kg,
			   COALESCE(
				   m.head_circ_cm,
				   (SELECT m3.head_circ_cm FROM measurements m3 WHERE m3.student_id = s.id AND m3.head_circ_cm IS NOT NULL ORDER BY m3.measured_on DESC, m3.id DESC LIMIT 1)
			   ) AS bas_cevresi_cm,
			   m.age_months AS olcum_yas_ay,
			   m.bmi AS vki
		FROM students s
		JOIN classes c ON c.id = s.class_id
		LEFT JOIN health_profiles h ON h.student_id = s.id
		LEFT JOIN measurements m ON m.id = (
			SELECT m2.id FROM measurements m2
			WHERE m2.student_id = s.id
			ORDER BY m2.measured_on DESC, m2.id DESC LIMIT 1
		)
		WHERE 1=1
	"""
	params: list = []
	if class_name and class_name != "Tüm sınıflar":
		query += " AND c.name = ?"
		params.append(class_name)
	if person_type:
		norm_pt = clean_text(person_type).lower()
		if "sivil" in norm_pt or "diger" in norm_pt:
			query += " AND (c.name = 'Sivil / Diğer' OR s.person_type LIKE '%Sivil%' OR s.person_type LIKE '%diğer%')"
		else:
			query += " AND (c.name != 'Sivil / Diğer' AND s.person_type NOT LIKE '%Sivil%' AND s.person_type NOT LIKE '%diğer%')"
	query += " ORDER BY c.name, s.full_name, s.id"
	with connect_db() as connection:
		df = pd.read_sql_query(query, connection, params=tuple(params))
	if df.empty:
		return df

	_ensure_lms_cache()
	today = date.today()
	out_rows = []
	for r in df.to_dict("records"):
		sex = r["cinsiyet"] if pd.notna(r["cinsiyet"]) else None
		b_date = r["dogum_tarihi"] if pd.notna(r["dogum_tarihi"]) else None
		cur_age_mo = age_in_months(b_date, today) if b_date else None
		m_age_mo = int(r["olcum_yas_ay"]) if pd.notna(r["olcum_yas_ay"]) else None
		if m_age_mo is None and b_date and pd.notna(r["son_olcum_tarihi"]):
			try:
				m_age_mo = age_in_months(b_date, date.fromisoformat(str(r["son_olcum_tarihi"])[:10]))
			except Exception:
				m_age_mo = cur_age_mo

		h_val = round(float(r["boy_cm"]), 1) if pd.notna(r["boy_cm"]) else None
		w_val = round(float(r["kilo_kg"]), 1) if pd.notna(r["kilo_kg"]) else None
		hc_val = round(float(r["bas_cevresi_cm"]), 1) if (pd.notna(r["bas_cevresi_cm"]) and float(r["bas_cevresi_cm"]) > 0) else None
		b_val = round(float(r["vki"]), 1) if pd.notna(r["vki"]) else None
		if b_val is None and h_val and w_val and h_val > 0 and w_val > 0:
			b_val = round(w_val / ((h_val / 100.0) ** 2), 1)

		h_eval = evaluate_measurement(h_val, "height", sex, m_age_mo) if (sex and m_age_mo is not None and h_val) else None
		w_eval = evaluate_measurement(w_val, "weight", sex, m_age_mo) if (sex and m_age_mo is not None and w_val) else None
		b_eval = evaluate_measurement(b_val, "bmi", sex, m_age_mo) if (sex and m_age_mo is not None and b_val) else None
		hc_eval = evaluate_measurement(hc_val, "head_circ", sex, m_age_mo) if (sex and m_age_mo is not None and hc_val) else None

		if h_val is None and w_val is None and hc_val is None:
			growth_status = "—"
		elif sex and m_age_mo is not None:
			remarks = []
			if b_eval and "Normal" not in b_eval["status"]:
				remarks.append(b_eval["status"].replace(" aralığı", ""))
			if h_eval and "Normal" not in h_eval["status"]:
				remarks.append(h_eval["status"].replace(" aralığı", ""))
			if hc_eval and "Normal" not in hc_eval["status"]:
				remarks.append(hc_eval["status"].replace(" sınırı", ""))
			growth_status = ", ".join(remarks) if remarks else "🟢 Normal"
		else:
			growth_status = "⚪ Doğum/Cinsiyet Eksik"

		alert_parts = [clean_text(r["alerjiler"]), clean_text(r["kronik"]), clean_text(r["saglik_gecmisi"]), clean_text(r["ilaclar"])]
		alert_summary = " · ".join([p for p in alert_parts if p]) or "—"

		loc_parts = [clean_text(r.get("il")), clean_text(r.get("ilce")), clean_text(r.get("koy"))]
		loc_summary = " / ".join([p for p in loc_parts if p]) or "—"

		out_rows.append({
			"id": int(r["id"]),
			"Kayıt Türü": clean_text(r["kayit_turu"]) or "Öğrenci",
			"Sınıf": clean_text(r["sinif"]) or "—",
			"Görev / Statü": clean_text(r["notlar"]) or "—",
			"Okul No": clean_text(r["okul_no"]) or "—",
			"Ad Soyad": clean_text(r["ad_soyad"]),
			"Cinsiyet": clean_text(sex) or "—",
			"Doğum Tarihi": clean_text(b_date) or "—",
			"Yaş (Ay)": cur_age_mo,
			"Boy (cm)": h_val,
			"Boy Z-Skor": h_eval["z"] if h_eval else None,
			"Boy %": h_eval["percentile"] if h_eval else None,
			"Kilo (kg)": w_val,
			"Kilo Z-Skor": w_eval["z"] if w_eval else None,
			"Kilo %": w_eval["percentile"] if w_eval else None,
			"Baş Çevresi (cm)": hc_val,
			"VKİ (BMI)": b_val,
			"VKİ Z-Skor": b_eval["z"] if b_eval else None,
			"VKİ %": b_eval["percentile"] if b_eval else None,
			"Gelişim Durumu": growth_status,
			"Kan Grubu": clean_text(r["kan_grubu"]) or "—",
			"Alerji / Kronik": alert_summary,
			"İl / İlçe / Köy": loc_summary,
			"Adres / Mahalle": clean_text(r["notlar"]) or "—",
			"Başvuru": int(r["basvuru_sayisi"]) if pd.notna(r["basvuru_sayisi"]) else 0,
			"Veli": clean_text(r["veli"]) or "—",
			"Telefon": clean_text(r["veli_telefon"]) or "—",
		})
	return pd.DataFrame(out_rows)


def is_kvkk_privacy_active() -> bool:
	try:
		return bool(ui.session_state.get("kvkk_privacy_mode", False))
	except Exception:
		return False


def mask_kvkk_value(val: object, field_type: str = "name") -> str:
	"""KVKK Gizlilik Modu açıkken ekrandaki ad, telefon ve tıbbi verileri maskeler."""
	try:
		is_masked = bool(ui.session_state.get("kvkk_privacy_mode", False))
	except Exception:
		is_masked = False

	if not is_masked:
		if val is None:
			return ""
		try:
			if pd.isna(val):
				return ""
		except (TypeError, ValueError):
			pass
		return str(val)

	txt = clean_text(val)
	ft = (field_type or "name").strip().lower()

	if ft == "medical":
		if not txt or txt == "—":
			return txt
		return "🔒 [Gizli Sağlık Verisi]"

	if not txt or txt == "—":
		return txt

	if ft == "phone":
		digits = re.sub(r"\D+", "", txt)
		if len(digits) >= 10:
			return f"{digits[:4]} *** ** {digits[-2:]}"
		if len(digits) >= 5:
			return f"{digits[:2]} *** {digits[-2:]}"
		if len(txt) >= 5:
			return f"{txt[:2]} *** {txt[-2:]}"
		return "***"

	# Default: field_type == "name" ("ALİ ASAF DOĞAN" -> "A** A*** D****")
	masked_parts = []
	for word in txt.split():
		if len(word) <= 1:
			masked_parts.append(word)
		else:
			masked_parts.append(word[0] + ("*" * (len(word) - 1)))
	return " ".join(masked_parts)


def apply_kvkk_mask_to_roster_df(df: pd.DataFrame) -> pd.DataFrame:
	"""Öğrenci/Yetişkin listeleme tabloları görüntülenirken KVKK Gizlilik Modu açıksa kimlik, telefon ve klinik sütunları maskeler."""
	if df is None or df.empty or not is_kvkk_privacy_active():
		return df
	out_df = df.copy()
	for col_name, ftype in (
		("Ad Soyad", "name"),
		("Öğrenci", "name"),
		("Veli", "name"),
		("Telefon", "phone"),
		("Alerji / Kronik", "medical"),
		("Gelişim Durumu", "medical"),
	):
		if col_name in out_df.columns:
			out_df[col_name] = out_df[col_name].apply(lambda x, t=ftype: mask_kvkk_value(x, t))
	return out_df


