def get_person_by_id(person_id: int | None) -> sqlite3.Row | None:
	if person_id is None:
		return None
	try:
		cached_map = ui.session_state.get("_cached_persons", {})
		if int(person_id) in cached_map:
			return cached_map[int(person_id)]
	except Exception:
		cached_map = {}
	with connect_db() as connection:
		row = connection.execute(
			"""SELECT s.id, s.person_type, s.full_name, c.name AS class_name, s.sex, s.birth_date,
					  s.student_no, s.guardian_name, s.guardian_phone, s.notes,
					  s.country, s.province, s.district, s.village,
					  COALESCE(s.has_disability, 0) AS has_disability
			   FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?""",
			(int(person_id),),
		).fetchone()
	if row:
		try:
			cached_map[int(person_id)] = row
			ui.session_state["_cached_persons"] = cached_map
		except Exception:
			pass
	return row


def set_active_person(person_id: int | None) -> None:
	ui.session_state["active_person_id"] = int(person_id) if person_id is not None else None


def select_shared_person(key_prefix: str, person_type: str | None = None, label: str = "Öğrenci / Kişi Seçin") -> sqlite3.Row | None:
	all_classes = get_classes()
	if person_type == "Öğrenci":
		classes = [c for c in all_classes if c != "Sivil / Diğer"]
	elif person_type == "Sivil":
		classes = ["Sivil / Diğer"] if "Sivil / Diğer" in all_classes else []
	else:
		classes = all_classes

	active_id = ui.session_state.get("active_person_id")
	active_person = get_person_by_id(active_id) if active_id is not None else None
	if active_id is not None and active_person is None:
		active_id = None
		set_active_person(None)

	widget_key = f"{key_prefix}_person_select"
	last_synced_key = f"{key_prefix}_last_synced_id"

	if person_type != "Sivil":
		class_opts = ["Tüm sınıflar", *classes]
		cls_widget_key = f"{key_prefix}_cls_filter"
		cls_sync_key = f"{key_prefix}_last_synced_cls"

		global_cls = ui.session_state.get("active_class_filter", "Tüm sınıflar")
		if global_cls not in class_opts:
			global_cls = "Tüm sınıflar"
			ui.session_state["active_class_filter"] = "Tüm sınıflar"

		person_changed_globally = (ui.session_state.get(last_synced_key) != active_id)
		cls_first_init = (cls_widget_key not in ui.session_state)
		cur_widget_cls = ui.session_state.get(cls_widget_key)
		last_seen_cls = ui.session_state.get(cls_sync_key)

		if cls_first_init or person_changed_globally:
			if active_person and global_cls != "Tüm sınıflar" and active_person["class_name"] != global_cls:
				if person_type is None or (person_type == "Öğrenci" and active_person["class_name"] != "Sivil / Diğer"):
					global_cls = "Tüm sınıflar"
					ui.session_state["active_class_filter"] = "Tüm sınıflar"
			ui.session_state[cls_widget_key] = global_cls
			ui.session_state[cls_sync_key] = global_cls
		elif cur_widget_cls != last_seen_cls:
			# User manually picked a different class in this page's filter widget
			if cur_widget_cls not in class_opts:
				ui.session_state[cls_widget_key] = "Tüm sınıflar"
		elif global_cls != last_seen_cls:
			# Another page updated active_class_filter
			ui.session_state[cls_widget_key] = global_cls
			ui.session_state[cls_sync_key] = global_cls

		if ui.session_state.get(cls_widget_key) not in class_opts:
			ui.session_state[cls_widget_key] = "Tüm sınıflar"

		col_f, col_s = ui.columns([1, 2.2])
		with col_f:
			chosen_class = ui.selectbox("Sınıf Filtresi", class_opts, key=cls_widget_key)
			ui.session_state["active_class_filter"] = chosen_class
			ui.session_state[cls_sync_key] = chosen_class
	else:
		chosen_class = "Sivil / Diğer"
		col_s = ui.container()

	all_people = student_options(None, person_type=person_type)
	if chosen_class == "Tüm sınıflar" or not chosen_class:
		people = all_people
	else:
		class_people = student_options(chosen_class, person_type=person_type)
		other_people = [p for p in all_people if p["id"] not in {cp["id"] for cp in class_people}]
		# Put class people first, then allow searching other people so no student is ever hidden
		people = class_people + other_people

	if not people:
		ui.info("Kayıtlı kişi bulunamadı. 'Öğrenciler' veya 'Yeni Kayıt' bölümünden kayıt ekleyebilirsiniz.")
		return None

	def _person_label(row: sqlite3.Row) -> str:
		c_name = row["class_name"] or "Sınıf Belirtilmedi"
		is_row_adult = (c_name == "Sivil / Diğer" or "Sivil" in str(row["person_type"] or ""))
		disp_fn = mask_kvkk_value(row["full_name"], "name")
		if is_row_adult:
			role_s = str(row["notes"] or "").strip()
			prefix = f"[👫 Yetişkin · {role_s}] " if role_s else "[👫 Yetişkin] "
			parts = [f"{prefix}{disp_fn}"]
		else:
			prefix = f"[🎒 {c_name}] " if chosen_class == "Tüm sınıflar" or (chosen_class != c_name) else ""
			parts = [f"{prefix}{disp_fn}"]
			if row["student_no"]:
				parts.append(f"No: {row['student_no']}")
		parts.append(f"#{row['id']}")
		return " · ".join(parts)

	lookup = {_person_label(r): r for r in people}
	labels = list(lookup.keys())
	id_to_label = {r["id"]: lbl for lbl, r in lookup.items()}
	expected_label = id_to_label.get(active_id)

	# Keep widget state synchronized with global active_person_id and label format before widget creation
	synced_id = ui.session_state.get(last_synced_key)
	cur_widget_val = ui.session_state.get(widget_key)
	was_synced_selected = (synced_id == active_id and active_id in id_to_label and widget_key in ui.session_state)

	if widget_key not in ui.session_state or synced_id != active_id:
		ui.session_state[widget_key] = expected_label
		ui.session_state[last_synced_key] = active_id
	elif cur_widget_val is not None and cur_widget_val not in lookup:
		# Label changed format (e.g. class filter changed or student renamed), restore active person's updated label
		ui.session_state[widget_key] = expected_label

	def _on_person_change() -> None:
		sel_lbl = ui.session_state.get(widget_key)
		if sel_lbl and sel_lbl in lookup:
			new_pid = int(lookup[sel_lbl]["id"])
			set_active_person(new_pid)
			ui.session_state[last_synced_key] = new_pid
		elif sel_lbl is None:
			set_active_person(None)
			ui.session_state[last_synced_key] = None

	with col_s:
		selected_label = ui.selectbox(
			label,
			labels,
			placeholder="İsim, sınıf veya okul numarası ile arayın...",
			key=widget_key,
			on_change=_on_person_change,
		)

	if not selected_label or selected_label not in lookup:
		if was_synced_selected and selected_label is None:
			set_active_person(None)
			ui.session_state[last_synced_key] = None
		return None

	chosen_person = lookup[selected_label]
	if chosen_person["id"] != active_id:
		set_active_person(chosen_person["id"])
	ui.session_state[last_synced_key] = chosen_person["id"]
	return chosen_person


def _upsert_measurement_conn(
	connection: sqlite3.Connection,
	student_id: int,
	measured_on: date,
	height_cm: float | None,
	weight_kg: float | None,
	birth_date: str | None = None,
	sex: str | None = None,
	head_circ_cm: float | None = None,
) -> tuple[int | None, str]:
	sid = int(student_id)
	m_date_obj = measured_on if isinstance(measured_on, date) else date.fromisoformat(str(measured_on)[:10])
	m_date_iso = m_date_obj.isoformat()

	is_adult_person = False
	stu_info = connection.execute("SELECT birth_date, sex, person_type FROM students WHERE id=?", (sid,)).fetchone()
	if stu_info:
		if not birth_date:
			birth_date = stu_info["birth_date"]
		if not sex:
			sex = stu_info["sex"]
		if stu_info["person_type"] and str(stu_info["person_type"]).strip() != "Öğrenci":
			is_adult_person = True

	norm_sex = normalize_sex(sex) or sex
	months = age_in_months(birth_date, m_date_obj) if birth_date else None

	h_val = normalize_height(height_cm)
	w_val = normalize_weight(weight_kg, is_adult=is_adult_person)
	hc_val = normalize_head_circ(head_circ_cm)

	if h_val is None and w_val is None and hc_val is None:
		return None, ""

	existing = connection.execute(
		"""SELECT id, height_cm, weight_kg, head_circ_cm, age_months, bmi
		   FROM measurements WHERE student_id=? AND measured_on=? ORDER BY id DESC LIMIT 1""",
		(sid, m_date_iso),
	).fetchone()

	if existing:
		final_h = h_val if h_val is not None else (float(existing["height_cm"]) if existing["height_cm"] is not None else None)
		final_w = w_val if w_val is not None else (float(existing["weight_kg"]) if existing["weight_kg"] is not None else None)
		final_hc = hc_val if hc_val is not None else (float(existing["head_circ_cm"]) if existing["head_circ_cm"] is not None else None)
		exclude_id = int(existing["id"])
	else:
		final_h = h_val
		final_w = w_val
		final_hc = hc_val
		exclude_id = -1

	# Complete missing height or weight from most recent prior valid measurement for BMI & percentile calculation
	completed_from_prev: set[str] = set()
	if (final_h is not None and final_h > 0) and (final_w is None or final_w <= 0):
		prev_w = connection.execute(
			"""SELECT weight_kg FROM measurements
			   WHERE student_id=? AND measured_on<=? AND id!=? AND weight_kg IS NOT NULL AND weight_kg > 0
			   ORDER BY measured_on DESC, id DESC LIMIT 1""",
			(sid, m_date_iso, exclude_id),
		).fetchone()
		if prev_w and prev_w["weight_kg"]:
			final_w = float(prev_w["weight_kg"])
			completed_from_prev.add("weight")
	elif (final_w is not None and final_w > 0) and (final_h is None or final_h <= 0):
		prev_h = connection.execute(
			"""SELECT height_cm FROM measurements
			   WHERE student_id=? AND measured_on<=? AND id!=? AND height_cm IS NOT NULL AND height_cm > 0
			   ORDER BY measured_on DESC, id DESC LIMIT 1""",
			(sid, m_date_iso, exclude_id),
		).fetchone()
		if prev_h and prev_h["height_cm"]:
			final_h = float(prev_h["height_cm"])
			completed_from_prev.add("height")

	final_bmi = (final_w / ((final_h / 100.0) ** 2)) if (final_h and final_w and final_h > 0 and final_w > 0) else None
	final_months = months if months is not None else (existing["age_months"] if existing else None)

	if existing:
		meas_id = int(existing["id"])
		connection.execute(
			"""UPDATE measurements
			   SET height_cm=?, weight_kg=?, head_circ_cm=?, age_months=?, bmi=?
			   WHERE id=?""",
			(final_h, final_w, final_hc, final_months, float(final_bmi) if final_bmi is not None else None, meas_id),
		)
	else:
		cur = connection.execute(
			"""INSERT INTO measurements(student_id, measured_on, height_cm, weight_kg, head_circ_cm, age_months, bmi)
			   VALUES (?, ?, ?, ?, ?, ?, ?)""",
			(sid, m_date_iso, final_h, final_w, final_hc, final_months, float(final_bmi) if final_bmi is not None else None),
		)
		meas_id = int(cur.lastrowid)

	parts = []
	if final_h is not None and (h_val is not None or "height" in completed_from_prev or existing):
		h_str = f"Boy: {final_h:.1f} cm" + (" (önceki ölçümden)" if "height" in completed_from_prev else "")
		if norm_sex and final_months is not None:
			h_ev = evaluate_measurement(final_h, "height", norm_sex, final_months)
			if h_ev:
				h_str += f" ({h_ev['z']:+.2f} SDS, %{h_ev['percentile']:.1f}p)"
		parts.append(h_str)
	if final_w is not None and (w_val is not None or "weight" in completed_from_prev or existing):
		w_str = f"Kilo: {final_w:.1f} kg" + (" (önceki ölçümden)" if "weight" in completed_from_prev else "")
		if norm_sex and final_months is not None:
			w_ev = evaluate_measurement(final_w, "weight", norm_sex, final_months)
			if w_ev:
				w_str += f" ({w_ev['z']:+.2f} SDS, %{w_ev['percentile']:.1f}p)"
		parts.append(w_str)
	if final_bmi is not None:
		b_str = f"VKİ: {final_bmi:.1f} kg/m²"
		if norm_sex and final_months is not None:
			b_ev = evaluate_measurement(final_bmi, "bmi", norm_sex, final_months)
			if b_ev:
				b_str += f" ({b_ev['z']:+.2f} SDS, %{b_ev['percentile']:.1f}p - {b_ev['status']})"
		parts.append(b_str)
	if hc_val is not None:
		hc_str = f"Baş Çevresi: {hc_val:.1f} cm"
		if norm_sex and final_months is not None:
			hc_ev = evaluate_measurement(hc_val, "head_circ", norm_sex, final_months)
			if hc_ev:
				hc_str += f" ({hc_ev['z']:+.2f} SDS, %{hc_ev['percentile']:.1f}p)"
		parts.append(hc_str)
	return meas_id, " | ".join(parts)


def record_linked_measurement(student_id: int, measured_on: date, height_cm: float | None, weight_kg: float | None,
							  birth_date: str | None = None, sex: str | None = None,
							  head_circ_cm: float | None = None) -> str:
	with connect_db() as connection:
		meas_id, summary_txt = _upsert_measurement_conn(
			connection,
			student_id,
			measured_on,
			height_cm,
			weight_kg,
			birth_date=birth_date,
			sex=sex,
			head_circ_cm=head_circ_cm,
		)
	if meas_id is not None:
		sync_after_person_mutation(int(student_id), active_measurement_id=meas_id)
	return summary_txt


def _upsert_vital_conn(
	connection: sqlite3.Connection,
	student_id: int,
	measured_at: str,
	systolic: float | None,
	diastolic: float | None,
	pulse: float | None,
	temperature: float | None,
	glucose: float | None,
	glucose_context: str | None = None,
	notes: str | None = None,
	spo2: float | None = None,
	upsert_same_slot: bool = True,
	upsert_screening_day: bool = False,
) -> tuple[int | None, str]:
	sid = int(student_id)
	raw_ts = str(measured_at or datetime.now().isoformat(timespec="minutes")).strip()
	norm_ts = raw_ts.replace(" ", "T")[:16]
	if len(norm_ts) == 10:
		norm_ts = f"{norm_ts}T09:30"
	day_prefix = norm_ts[:10]

	sys_i, dia_i = normalize_bp(systolic, diastolic)
	sys_v = float(sys_i) if sys_i is not None else None
	dia_v = float(dia_i) if dia_i is not None else None
	pls_i = normalize_pulse(pulse)
	pls_v = float(pls_i) if pls_i is not None else None
	tmp_v = normalize_temperature(temperature)
	spo_i = normalize_spo2(spo2)
	spo_v = float(spo_i) if spo_i is not None else None
	glu_v = normalize_glucose(glucose)

	if all(x is None for x in (sys_v, dia_v, pls_v, tmp_v, spo_v, glu_v)):
		return None, ""

	existing = None
	if upsert_screening_day or (notes and "Okul Taraması" in notes):
		existing = connection.execute(
			"""SELECT id, measured_at, systolic_mmhg, diastolic_mmhg, pulse_bpm, temperature_c,
			          spo2_pct, glucose_mg_dl, glucose_context, notes
			   FROM vital_readings
			   WHERE student_id=? AND (
			       substr(replace(measured_at, ' ', 'T'), 1, 16) = ?
			       OR (substr(measured_at, 1, 10) = ? AND COALESCE(notes, '') LIKE '%Okul Taraması%')
			   )
			   ORDER BY id DESC LIMIT 1""",
			(sid, norm_ts, day_prefix),
		).fetchone()
	elif upsert_same_slot:
		existing = connection.execute(
			"""SELECT id, measured_at, systolic_mmhg, diastolic_mmhg, pulse_bpm, temperature_c,
			          spo2_pct, glucose_mg_dl, glucose_context, notes
			   FROM vital_readings
			   WHERE student_id=? AND substr(replace(measured_at, ' ', 'T'), 1, 16) = ?
			   ORDER BY id DESC LIMIT 1""",
			(sid, norm_ts),
		).fetchone()

	if existing:
		vital_id = int(existing["id"])
		final_sys = sys_v if sys_v is not None else existing["systolic_mmhg"]
		final_dia = dia_v if dia_v is not None else existing["diastolic_mmhg"]
		final_pls = pls_v if pls_v is not None else existing["pulse_bpm"]
		final_tmp = tmp_v if tmp_v is not None else existing["temperature_c"]
		final_spo = spo_v if spo_v is not None else existing["spo2_pct"]
		final_glu = glu_v if glu_v is not None else existing["glucose_mg_dl"]
		final_gctx = glucose_context if glucose_context else existing["glucose_context"]
		final_notes = notes if notes else existing["notes"]
		connection.execute(
			"""UPDATE vital_readings
			   SET measured_at=?, systolic_mmhg=?, diastolic_mmhg=?, pulse_bpm=?, temperature_c=?,
			       spo2_pct=?, glucose_mg_dl=?, glucose_context=?, notes=?
			   WHERE id=?""",
			(norm_ts, final_sys, final_dia, final_pls, final_tmp, final_spo, final_glu, final_gctx, final_notes, vital_id),
		)
	else:
		cur = connection.execute(
			"""INSERT INTO vital_readings(student_id, measured_at, systolic_mmhg, diastolic_mmhg,
			   pulse_bpm, temperature_c, spo2_pct, glucose_mg_dl, glucose_context, notes)
			   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
			(sid, norm_ts, sys_v, dia_v, pls_v, tmp_v, spo_v, glu_v, glucose_context, notes),
		)
		vital_id = int(cur.lastrowid)

	v_parts = []
	if tmp_v is not None:
		v_parts.append(f"Ateş: {tmp_v:.1f} °C")
	if spo_v is not None:
		v_parts.append(f"SpO2 (Saturasyon): %{spo_v:.0f}")
	if sys_v is not None and dia_v is not None:
		v_parts.append(f"Tansiyon: {sys_v:.0f}/{dia_v:.0f} mmHg")
	if pls_v is not None:
		v_parts.append(f"Nabız: {pls_v:.0f} atım/dk")
	if glu_v is not None:
		ctx = f" ({glucose_context})" if glucose_context else ""
		v_parts.append(f"Kan Şekeri: {glu_v:.0f} mg/dL{ctx}")
	return vital_id, " | ".join(v_parts)


def record_linked_vital(student_id: int, measured_at: str, systolic: float | None, diastolic: float | None,
						pulse: float | None, temperature: float | None, glucose: float | None,
						glucose_context: str | None = None, notes: str | None = None,
						spo2: float | None = None) -> str:
	with connect_db() as connection:
		vital_id, v_summary = _upsert_vital_conn(
			connection,
			student_id,
			measured_at,
			systolic,
			diastolic,
			pulse,
			temperature,
			glucose,
			glucose_context=glucose_context,
			notes=notes,
			spo2=spo2,
			upsert_same_slot=True,
			upsert_screening_day=False,
		)
	if vital_id is not None:
		sync_after_person_mutation(int(student_id))
	return v_summary


def get_person_latest_measurements(person_id: int | None) -> dict:
	"""
	Tek ve Merkezi Antropometrik Veri Motoru (Single Source of Truth).
	Herhangi bir kişi (öğrenci/sivil) için en güncel boy, kilo, VKİ ve baş çevresi verilerini getirir.

	Önemli Prensipler:
	1. Tam İzolasyon: Veriler kesinlikle student_id=? ile sorgulanır. Farklı kişilerin verileri ASLA birbirine karışmaz.
	2. Boş Değer Önleme / Tarihsel Telafi: Son ölçümde baş çevresi (veya boy/kilo) girilmemiş olsa bile,
	   öğrencinin geçmişte kaydedilmiş geçerli bir baş çevresi ölçümü varsa bunu çeker ve tarihini belirtir.
	   Böylece "baş ölçümü sonucu boş değil" verileri sistemin her yerinde eksiksiz görüntülenir.
	3. Entegre WHO LMS Z-skor ve persantil hesaplaması: İlgili parametre için ölçüldüğü tarihteki yaşa göre doğru SDS/% üretir.
	"""
	empty_res = {
		"has_data": False,
		"person_id": person_id,
		"total_records": 0,
		"latest_measured_on": None,
		"height_cm": None, "height_date": None, "height_eval": None,
		"weight_kg": None, "weight_date": None, "weight_eval": None,
		"bmi": None, "bmi_date": None, "bmi_eval": None,
		"head_circ_cm": None, "head_circ_date": None, "head_circ_eval": None,
		"is_head_circ_from_earlier": False,
		"summary_items": [],
		"summary_html": "Henüz boy, kilo veya baş çevresi ölçümü girilmedi.",
	}
	if person_id is None:
		return empty_res

	with connect_db() as connection:
		person = connection.execute(
			"SELECT s.id, s.full_name, s.sex, s.birth_date, c.name AS class_name FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?",
			(int(person_id),)
		).fetchone()
		if not person:
			return empty_res

		rows = connection.execute(
			"""SELECT id, measured_on, height_cm, weight_kg, head_circ_cm, age_months, bmi
			   FROM measurements WHERE student_id=? ORDER BY measured_on ASC, id ASC""",
			(int(person_id),)
		).fetchall()

	if not rows:
		return empty_res

	sex = person["sex"]
	b_date = person["birth_date"]
	latest_row = rows[-1]
	latest_measured_on = str(latest_row["measured_on"])[:10]

	h_val, h_date, h_mo = None, None, None
	w_val, w_date, w_mo = None, None, None
	hc_val, hc_date, hc_mo = None, None, None
	b_val, b_date_str, b_mo = None, None, None

	for r in reversed(rows):
		d_str = str(r["measured_on"])[:10]
		mo = r["age_months"]
		if mo is None and b_date:
			try:
				mo = age_in_months(b_date, date.fromisoformat(d_str))
			except Exception:
				mo = None

		if h_val is None and r["height_cm"] is not None and float(r["height_cm"]) > 0:
			h_val = float(r["height_cm"])
			h_date = d_str
			h_mo = mo

		if w_val is None and r["weight_kg"] is not None and float(r["weight_kg"]) > 0:
			w_val = float(r["weight_kg"])
			w_date = d_str
			w_mo = mo

		if hc_val is None and r["head_circ_cm"] is not None and float(r["head_circ_cm"]) > 0:
			hc_val = float(r["head_circ_cm"])
			hc_date = d_str
			hc_mo = mo

		if b_val is None and r["bmi"] is not None and float(r["bmi"]) > 0:
			b_val = float(r["bmi"])
			b_date_str = d_str
			b_mo = mo

	# If height and weight exist, recalculate latest BMI
	if h_val and w_val:
		b_val = round(w_val / ((h_val / 100.0) ** 2), 2)
		b_date_str = max(h_date or "", w_date or "")
		b_mo = max(h_mo or 0, w_mo or 0) or None

	h_ev = evaluate_measurement(h_val, "height", sex, h_mo) if (sex and h_mo is not None and h_val) else None
	w_ev = evaluate_measurement(w_val, "weight", sex, w_mo) if (sex and w_mo is not None and w_val) else None
	b_ev = evaluate_measurement(b_val, "bmi", sex, b_mo) if (sex and b_mo is not None and b_val) else None
	hc_ev = evaluate_measurement(hc_val, "head_circ", sex, hc_mo) if (sex and hc_mo is not None and hc_val) else None

	ideal_info = calculate_ideal_weight(h_val, sex, b_mo or h_mo, current_weight_kg=w_val)
	is_hc_earlier = (hc_date != latest_measured_on) if (hc_val and hc_date) else False

	m_items = []
	if h_val is not None:
		m_items.append(f"📏 <b>Boy:</b> {h_val:.1f} cm" + (f" ({h_ev['z']:+.2f} SDS · <b>%{h_ev['percentile']:.1f}p</b>)" if h_ev else ""))
	if w_val is not None:
		m_items.append(f"⚖️ <b>Kilo:</b> {w_val:.1f} kg" + (f" ({w_ev['z']:+.2f} SDS · <b>%{w_ev['percentile']:.1f}p</b>)" if w_ev else ""))
	if b_val is not None:
		m_items.append(f"🧬 <b>VKİ:</b> {b_val:.1f}" + (f" ({b_ev['z']:+.2f} SDS · <b>%{b_ev['percentile']:.1f}p</b> — {html.escape(b_ev['status'])})" if b_ev else ""))
	if ideal_info is not None:
		status_badge = f" · <span style='font-size:12.5px;font-weight:600;'>{ideal_info['status_text']}</span>" if ideal_info.get("status_text") else ""
		m_items.append(f"🎯 <b>İdeal Kilo Aralığı:</b> {ideal_info['min_kg']:.1f} – {ideal_info['max_kg']:.1f} kg <small style='opacity:0.8;'>(İdeal En Az: <b>{ideal_info['min_kg']:.1f} kg</b> · İdeal En Çok: <b>{ideal_info['max_kg']:.1f} kg</b>)</small>{status_badge}")
	if hc_val is not None:
		hc_extra = f" <small style='opacity:0.8;'>({hc_date})</small>" if is_hc_earlier else ""
		m_items.append(f"🧠 <b>Baş Çevresi:</b> {hc_val:.1f} cm{hc_extra}" + (f" ({hc_ev['z']:+.2f} SDS · <b>%{hc_ev['percentile']:.1f}p</b>)" if hc_ev else ""))

	return {
		"has_data": bool(m_items),
		"person_id": person_id,
		"total_records": len(rows),
		"latest_measured_on": latest_measured_on,
		"height_cm": h_val, "height_date": h_date, "height_eval": h_ev,
		"weight_kg": w_val, "weight_date": w_date, "weight_eval": w_ev,
		"bmi": b_val, "bmi_date": b_date_str, "bmi_eval": b_ev,
		"ideal_weight_kg": ideal_info["ideal_kg"] if ideal_info else None,
		"ideal_weight_min_kg": ideal_info["min_kg"] if ideal_info else None,
		"ideal_weight_max_kg": ideal_info["max_kg"] if ideal_info else None,
		"ideal_weight_range_str": f"{ideal_info['min_kg']:.1f} – {ideal_info['max_kg']:.1f} kg" if ideal_info else None,
		"ideal_weight_info": ideal_info,
		"head_circ_cm": hc_val, "head_circ_date": hc_date, "head_circ_eval": hc_ev,
		"is_head_circ_from_earlier": is_hc_earlier,
		"summary_items": m_items,
		"summary_html": (" &nbsp;|&nbsp; ".join(m_items) + f" <span style='font-size:12px;opacity:0.75;'>({latest_measured_on})</span>") if m_items else "Henüz boy, kilo veya baş çevresi ölçümü girilmedi.",
	}


