def _resolve_rename_classes_pairs(export_spec: dict[str, Any]) -> list[tuple[str, str]]:
	"""`rename_classes` komutundaki replace_from/strip_prefix/renames kurallarını gerçek (eski_ad, yeni_ad) çiftlerine çözümler."""
	pairs: list[tuple[str, str]] = []
	seen_old: set[str] = set()
	protected_cls = {"Sivil / Diğer", "Sınıf Belirtilmedi"}

	for r_it in (export_spec.get("renames") or []):
		if not isinstance(r_it, dict):
			continue
		onm = str(r_it.get("old_name") or r_it.get("from") or "").strip()
		nnm = str(r_it.get("new_name") or r_it.get("to") or "").strip(" /-\t\r\n")
		if onm and nnm and onm != nnm and onm not in protected_cls and nnm not in protected_cls:
			if onm.lower() not in seen_old:
				pairs.append((onm, nnm))
				seen_old.add(onm.lower())

	rep_from = str(export_spec.get("replace_from") or export_spec.get("strip_prefix") or export_spec.get("remove_text") or "")
	rep_to = str(export_spec.get("replace_to") or "")
	if rep_from.strip():
		try:
			with connect_db() as conn:
				rows = conn.execute("SELECT name FROM classes ORDER BY name").fetchall()
		except Exception:
			rows = []
		pat = re.compile(re.escape(rep_from.strip()) + r"(?:\s*/\s*)?", flags=re.IGNORECASE)
		for row in rows:
			cname = str(row["name"] or "").strip()
			if not cname or cname in protected_cls or cname.lower() in seen_old:
				continue
			if pat.search(cname):
				new_c = pat.sub(rep_to, cname).strip(" /-\t\r\n")
				new_c = re.sub(r"\s{2,}", " ", new_c).strip()
				if new_c and new_c != cname and new_c not in protected_cls:
					pairs.append((cname, new_c))
					seen_old.add(cname.lower())
	return pairs


def _coerce_mutating_sql_export_spec(export_spec: dict[str, Any]) -> dict[str, Any]:
	"""Gemini yanlışlıkla sınıf güncelleme için sql_export (UPDATE classes SET name=REPLACE/...) gönderirse güvenli rename_classes aksiyonuna çevirir."""
	if not isinstance(export_spec, dict):
		return export_spec
	if str(export_spec.get("action") or "").strip().lower() != "sql_export":
		return export_spec
	sql_raw = str(export_spec.get("sql") or "").strip()
	if not sql_raw:
		return export_spec
	m_rep = re.search(
		r"UPDATE\s+classes\s+SET\s+name\s*=\s*(?:TRIM\s*\(\s*)?REPLACE\s*\(\s*name\s*,\s*'([^']+)'\s*,\s*'([^']*)'\s*\)",
		sql_raw,
		flags=re.IGNORECASE,
	)
	if m_rep:
		return {
			"action": "rename_classes",
			"replace_from": m_rep.group(1),
			"replace_to": m_rep.group(2),
		}
	return export_spec


def _build_export_write_proposal(export_spec: dict[str, Any]) -> dict[str, Any]:
	"""Veri yazma veya silme içeren Gemini komutları için kullanıcı onay kartı özeti üretir."""
	act = str(export_spec.get("action") or "").strip().lower()
	items: list[str] = []
	is_destructive = act in ("delete_records", "cafeteria_delete_records")
	title = "Veritabanına İşlenecek Değişiklikler (Onay Gerekli)"
	confirm_label = "✅ Onayla ve İşlemi Uygula"

	if act == "rename_classes":
		title = "Sınıf / Şube Adlarını Güncelleme (Onay Gerekli)"
		pairs = _resolve_rename_classes_pairs(export_spec)
		try:
			with connect_db() as conn:
				cnt_rows = conn.execute(
					"SELECT c.name, c.teacher_name, COUNT(s.id) AS stu_cnt FROM classes c LEFT JOIN students s ON s.class_id=c.id GROUP BY c.id"
				).fetchall()
				info_map = {str(r["name"]).lower(): (int(r["stu_cnt"] or 0), str(r["teacher_name"] or "").strip()) for r in cnt_rows}
		except Exception:
			info_map = {}
		for old_nm, new_nm in pairs[:20]:
			stu_cnt, tch = info_map.get(old_nm.lower(), (0, ""))
			merge_note = "birleştirilecek" if new_nm.lower() in info_map else "yeniden adlandırılacak"
			meta_parts = []
			if stu_cnt:
				meta_parts.append(f"{stu_cnt} öğrenci")
			if tch:
				meta_parts.append(f"Öğrt: {tch}")
			meta_s = f" ({', '.join(meta_parts)}, {merge_note})" if meta_parts else f" ({merge_note})"
			items.append(f"✏️ {old_nm} → {new_nm}{meta_s}")
		if len(pairs) > 20:
			items.append(f"...ve {len(pairs) - 20} sınıf daha (Toplam {len(pairs)} sınıf)")
		if pairs:
			items.append("🛡️ Hiçbir öğrenci ve sınıf öğretmeni silinmeden korunacaktır.")
	elif act in ("create_classes", "create_profiles"):
		title = "Sınıf, Öğretmen ve Öğrenci Profili İşlemleri (Onay Gerekli)"
		cls_list = export_spec.get("classes") if isinstance(export_spec.get("classes"), list) else []
		stu_list = export_spec.get("students") if isinstance(export_spec.get("students"), list) else []
		staff_list = export_spec.get("staff") if isinstance(export_spec.get("staff"), list) else (
			export_spec.get("teachers") if isinstance(export_spec.get("teachers"), list) else []
		)
		cls_names: list[str] = []
		tch_pairs: list[str] = []
		for c_it in cls_list[:120]:
			cn = str(c_it.get("name") if isinstance(c_it, dict) else c_it or "").strip()
			tn = str(c_it.get("teacher_name") or "").strip() if isinstance(c_it, dict) else ""
			if cn and cn != "Sivil / Diğer":
				cls_names.append(cn)
				if tn:
					tch_pairs.append(f"{cn} → {tn}")
		if cls_names:
			items.append(f"🏫 Oluşturulacak / kontrol edilecek şubeler ({len(cls_names)}): {', '.join(cls_names[:12])}{'...' if len(cls_names) > 12 else ''}")
		if tch_pairs:
			items.append(f"👩‍🏫 Atanacak sınıf öğretmenleri ({len(tch_pairs)}): {', '.join(tch_pairs[:8])}{'...' if len(tch_pairs) > 8 else ''}")
		stu_names = [str(s.get("full_name") or s.get("name") or "").strip() for s in stu_list if isinstance(s, dict) and str(s.get("full_name") or s.get("name") or "").strip()]
		if stu_names:
			items.append(f"🎓 Eklenecek öğrenci profilleri ({len(stu_names)}): {', '.join(stu_names[:10])}{'...' if len(stu_names) > 10 else ''}")
		stf_names = [str(s.get("full_name") or s.get("name") or "").strip() for s in staff_list if isinstance(s, dict) and str(s.get("full_name") or s.get("name") or "").strip()]
		if stf_names:
			items.append(f"👨‍🏫 Eklenecek öğretmen / personel profilleri ({len(stf_names)}): {', '.join(stf_names[:10])}{'...' if len(stf_names) > 10 else ''}")
		items.append("🛡️ Mevcut şubeler ve kayıtlı öğrenciler silinmeden korunur.")
	elif act == "add_calendar_events":
		title = "Takvime Eklenecek Etkinlikler (Onay Gerekli)"
		evs = [e for e in (export_spec.get("events") or []) if isinstance(e, dict) and str(e.get("title") or "").strip()]
		for e in evs[:12]:
			t_str = f" {e.get('start_time')}" if str(e.get("start_time") or "").strip() else ""
			items.append(f"📅 {str(e.get('event_date') or '')[:10]}{t_str} · {e.get('title')}")
		if len(evs) > 12:
			items.append(f"...ve {len(evs) - 12} etkinlik daha (Toplam {len(evs)})")
	elif act == "delete_records":
		title = "Kayıt Silme İşlemi (Dikkat — Onay Gerekli)"
		confirm_label = "🗑️ Onayla ve Seçili Kayıtları Sil"
		cls_names = [str(c).strip() for c in (export_spec.get("classes") or []) if str(c).strip()]
		del_empty_all = bool(export_spec.get("delete_empty_classes", False))
		stu_items = export_spec.get("students") if isinstance(export_spec.get("students"), list) else []
		cal_items = export_spec.get("calendar_events") if isinstance(export_spec.get("calendar_events"), list) else []
		if del_empty_all:
			items.append("⚠️ Öğrencisi bulunmayan tüm boş şubeler silinecek.")
		if cls_names:
			items.append(f"⚠️ Silinecek şubeler ({len(cls_names)}): {', '.join(cls_names[:15])} (varsa öğrencileri 'Sınıf Belirtilmedi' grubuna aktarılır)")
		if stu_items:
			s_lbls = [str(s.get("full_name") or s.get("name") or s) if isinstance(s, dict) else str(s) for s in stu_items[:12]]
			items.append(f"⚠️ Silinecek kişi profilleri ({len(stu_items)}): {', '.join(s_lbls)}")
		if cal_items:
			c_lbls = [str(c.get("title") or c) if isinstance(c, dict) else str(c) for c in cal_items[:12]]
			items.append(f"⚠️ Silinecek takvim kayıtları ({len(cal_items)}): {', '.join(c_lbls)}")
	elif act == "cafeteria_upsert_dishes":
		title = "Yemekhane Yemek & Malzeme İşlemleri (Onay Gerekli)"
		d_list = export_spec.get("dishes") if isinstance(export_spec.get("dishes"), list) else []
		for d_it in d_list[:10]:
			if isinstance(d_it, dict) and d_it.get("name"):
				ing_c = len(d_it.get("ingredients") or []) if isinstance(d_it.get("ingredients"), list) else 0
				items.append(f"🍲 {d_it['name']} ({d_it.get('category', 'Ana Yemek')}, {ing_c} malzeme)")
	elif act == "cafeteria_plan_menu":
		title = "Yemekhane Menü Planlama (Onay Gerekli)"
		p_list = export_spec.get("plans") if isinstance(export_spec.get("plans"), list) else []
		for p_it in p_list[:10]:
			if isinstance(p_it, dict) and p_it.get("plan_date"):
				d_nms = ", ".join(str(x.get("name") if isinstance(x, dict) else x) for x in (p_it.get("dishes") or [])[:4])
				items.append(f"🗓️ {str(p_it['plan_date'])[:10]} ({p_it.get('meal_slot', 'Öğle Yemeği')}): {d_nms}")
	elif act == "cafeteria_record_purchase":
		title = "Yemekhane Gelen Ürün & Fatura Kaydı (Onay Gerekli)"
		it_list = export_spec.get("items") if isinstance(export_spec.get("items"), list) else []
		items.append(f"🚚 Fatura: {str(export_spec.get('invoice_date') or '')[:10]} · {export_spec.get('supplier_name') or 'Tedarikçi'} ({len(it_list)} ürün kalemi)")
		for it in it_list[:8]:
			if isinstance(it, dict) and it.get("item_name"):
				items.append(f"📦 {it['item_name']}: {it.get('quantity', 1)} {it.get('unit_type', 'kg')} × {it.get('unit_price', 0)} ₺")
	elif act == "cafeteria_record_cash":
		title = "Yemekhane Kasa & Tahsilat İşlemleri (Onay Gerekli)"
		tx_list = export_spec.get("transactions") if isinstance(export_spec.get("transactions"), list) else []
		for tx in tx_list[:10]:
			if isinstance(tx, dict):
				kind_lbl = "Okula Teslim (-)" if tx.get("tx_type") == "OUT_SCHOOL_HANDOVER" else "Tahsilat (+)"
				who_lbl = f"Getiren: {tx.get('delivered_by_name')}" if tx.get("delivered_by_name") else f"Alan: {tx.get('received_by_name') or '—'}"
				items.append(f"💵 {kind_lbl}: {tx.get('for_person_name') or '—'} · {tx.get('amount', 0)} ₺ ({who_lbl})")
	elif act == "cafeteria_delete_records":
		title = "Yemekhane Kayıt Silme İşlemi (Dikkat — Onay Gerekli)"
		confirm_label = "🗑️ Onayla ve Yemekhane Kayıtlarını Sil"
		for d_nm in (export_spec.get("dish_names") or [])[:8]:
			items.append(f"⚠️ Silinecek yemek: {d_nm}")
		for mp in (export_spec.get("plan_dates") or [])[:8]:
			if isinstance(mp, dict):
				items.append(f"⚠️ Silinecek menü: {mp.get('plan_date')} ({mp.get('meal_slot') or 'Tüm öğünler'})")
		for p_id in (export_spec.get("purchase_ids") or [])[:8]:
			items.append(f"⚠️ Silinecek fatura ID: #{p_id}")
		for dr_nm in (export_spec.get("diner_names") or [])[:8]:
			items.append(f"⚠️ Çıkarılacak yemek abonesi: {dr_nm}")
		for tx_id in (export_spec.get("cash_tx_ids") or [])[:8]:
			items.append(f"⚠️ Silinecek kasa hareketi ID: #{tx_id}")

	if not items:
		items.append(f"⚙️ Uygulanacak komut: {act}")
	return {
		"mode": "batch_action",
		"is_destructive": is_destructive,
		"title": title,
		"confirm_label": confirm_label,
		"items": items,
	}


def _handle_floating_gemini_apply_write(payload: dict[str, Any]) -> dict[str, Any]:
	"""Yüzen sohbet balonundaki 1-tık onay kartından gelen veri yazma/silme işlemini SQLite'a uygular ve tüm ekranları eşitler."""
	tok = str(payload.get("token") or "").strip()
	pending = ui.pop_pending_chat_write(tok)
	if not pending:
		return {"ok": False, "error": "Onay isteği zaman aşımına uğradı veya zaten işlendi."}

	if pending.get("kind") == "export_mutation":
		exp_spec = pending.get("export_spec") or {}
		ctx_pid = pending.get("context_pid")
		fb_reply = str(pending.get("fallback_reply") or "")
		try:
			_dls, exp_note = _execute_gemini_chat_export(exp_spec, int(ctx_pid) if ctx_pid else None, fb_reply)
			clean_sum = re.sub(r"[*`]+", "", (exp_note or "").strip()).lstrip("✅🗑️📅ℹ️ ").strip() or "Onaylanan veritabanı işlemi uygulandı."
			return {
				"ok": True,
				"refresh_ui": True,
				"summary": clean_sum,
			}
		except Exception as exc:
			return {"ok": False, "error": f"İşlem hatası: {exc}"}

	try:
		target_pid = int(payload.get("student_id") or payload.get("person_id") or pending.get("default_student_id") or 0)
	except Exception:
		target_pid = 0
	person = get_person_by_id(target_pid) if target_pid else None
	if not person:
		return {"ok": False, "error": "Hedef öğrenci/kişi bulunamadı."}

	ws = _normalize_write_spec(pending.get("write_spec") or {})
	src_name = str(pending.get("source_filename") or "Gemini_Sohbet")
	src_bytes = pending.get("source_bytes")

	has_hp = any(str((ws.get("health_profile") or {}).get(k) or "").strip() for k in ("allergies", "chronic_conditions", "blood_group", "regular_medications", "emergency_notes"))
	has_labs = bool([x for x in (ws.get("lab_results") or []) if isinstance(x, dict) and str(x.get("test_name") or "").strip()])
	has_vt = any((ws.get("vitals") or {}).get(k) not in (None, "") for k in ("temperature_c", "pulse_bpm", "spo2_pct", "systolic_bp", "diastolic_bp", "glucose_mg_dl"))
	has_ms = any((ws.get("measurements") or {}).get(k) not in (None, "") for k in ("height_cm", "weight_kg", "head_circ_cm"))
	has_meds = bool([x for x in (ws.get("medications") or []) if isinstance(x, dict) and str(x.get("medication_name") or "").strip()])
	has_vac = bool([x for x in (ws.get("vaccinations") or []) if isinstance(x, dict) and (str(x.get("vaccine_code") or "").strip() or str(x.get("vaccine_name") or "").strip())])
	scr_obj = ws.get("school_screenings") or {}
	has_scr = isinstance(scr_obj, dict) and any(scr_obj.get(k) not in (None, "") for k in ("height_cm", "weight_kg", "wears_glasses", "vision_right", "vision_left", "hearing_right", "hearing_left", "hair_screening", "notes"))
	has_dis = bool((ws.get("disability") or {}).get("has_disability"))
	has_diab = bool((ws.get("diabetes") or {}).get("is_diabetic"))
	has_vis = bool(str(ws.get("visit_note_suggestion") or "").strip())

	try:
		logs = dstudio.apply_extracted_clinical_record(
			connect_db,
			target_pid,
			ws,
			apply_profile=has_hp,
			apply_labs=has_labs,
			apply_vitals=has_vt,
			apply_measurements=has_ms,
			apply_meds=has_meds,
			apply_disability=has_dis,
			apply_diabetes=has_diab,
			apply_visit_note=has_vis,
			apply_vaccinations=has_vac,
			apply_screenings=has_scr,
			source_filename=src_name,
			source_bytes=src_bytes,
			age_in_months_fn=age_in_months,
			moh_schedule=MOH_VACCINE_SCHEDULE,
			save_screening_fn=save_school_screening,
		)
		should_archive = bool(payload.get("archive_doc") or payload.get("archive_attachment"))
		if should_archive and src_bytes and src_name and src_name != "Gemini_Sohbet":
			EVRAKLAR_DIR.mkdir(parents=True, exist_ok=True)
			dst = dstudio._unique_target_path(EVRAKLAR_DIR, Path(src_name).stem, Path(src_name).suffix.lower() or ".pdf")
			dst.write_bytes(src_bytes)
			get_or_create_document_cover(dst, force=True)
			logs.append(f"📁 `{dst.name}` Evrak Deposuna arşivlendi")

		set_active_person(target_pid)
		sync_after_person_mutation(target_pid)
		disp_nm = mask_kvkk_value(person["full_name"], "name")
		return {
			"ok": True,
			"student_id": target_pid,
			"refresh_ui": True,
			"logs": logs,
			"summary": f"{disp_nm} ({person['class_name']}) dosyasına işlendi: " + (" · ".join(logs) if logs else "Güncellendi"),
		}
	except Exception as exc:
		return {"ok": False, "error": f"Kayıt hatası: {exc}"}


def _handle_floating_gemini_chat(payload: dict[str, Any], chat_history: list[dict[str, str]]) -> dict[str, Any]:
	is_on, api_key, model = _get_active_gemini_config()
	if not is_on:
		return {"ok": False, "error": "Gemini Yapay Zekâ kapalı veya API anahtarı tanımlı değil."}

	raw_msg = str(payload.get("message") or "")
	raw_atts = payload.get("attachments") if isinstance(payload.get("attachments"), list) else []

	# 1. Yerel KVKK Korumalı Kimlik Ön-Eşleştirme (Mesaj + Ekli Belge İçeriğinden Yerel Öğrenci Bulma)
	local_scan_blob = raw_msg
	first_att_bytes: bytes | None = None
	first_att_name: str = ""
	for att in raw_atts[:2]:
		fb64 = str(att.get("data_b64") or "")
		fname = str(att.get("name") or "")
		if fb64:
			try:
				fb = base64.b64decode(fb64)
				if first_att_bytes is None:
					first_att_bytes = fb
					first_att_name = fname
				if fname.lower().endswith(".pdf"):
					local_scan_blob += "\n" + extract_pdf_text(fb)[:4000]
				elif fname.lower().endswith((".txt", ".csv")):
					local_scan_blob += "\n" + fb.decode("utf-8", errors="replace")[:4000]
				elif fname.lower().endswith(".docx") and _ensure_docx_loaded() and docx is not None:
					_d_loc = docx.Document(BytesIO(fb))
					local_scan_blob += "\n" + "\n".join(p.text for p in _d_loc.paragraphs[:40])
			except Exception:
				pass

	pre_pid, pre_name = _detect_local_person_in_text(local_scan_blob)
	active_pid = ui.session_state.get("active_person_id")
	context_pid = pre_pid or (int(active_pid) if active_pid else None)

	anon_person_ctx = ""
	sensitive_names: list[str] = []
	if context_pid:
		try:
			anon_person_ctx, sensitive_names, _ = _build_person_anon_bundle(int(context_pid))
		except Exception:
			pass
	if pre_name and pre_name not in sensitive_names:
		sensitive_names.append(pre_name)

	school_ctx = ""
	all_cls: list[str] = []
	try:
		cfg = get_app_settings()
		cur_page = str(ui.session_state.get("main_menu_page") or "Genel Bakış")
		today_iso = date.today().isoformat()
		all_cls = [c for c in get_classes() if c != "Sivil / Diğer"]
		with connect_db() as conn:
			c_row = conn.execute(
				"""SELECT (SELECT COUNT(*) FROM students) total_stu,
						  (SELECT COUNT(*) FROM students WHERE COALESCE(has_disability,0)=1) dis_cnt,
						  (SELECT COUNT(*) FROM visits WHERE visit_date=?) today_vis,
						  (SELECT COUNT(*) FROM isolation_records WHERE status='Aktif İzolasyonda') active_iso""",
				(today_iso,),
			).fetchone()
		school_ctx = (
			f"Kurum: {cfg.get('school_name', 'Okul Reviri')} | Aktif Sayfa: {cur_page} | "
			f"Kayıtlı Kişi: {c_row['total_stu']} (Özel Gereksinim/Engelli: {c_row['dis_cnt']}) | "
			f"Bugünkü Başvuru: {c_row['today_vis']} | Aktif İzolasyon: {c_row['active_iso']}"
		)
		today_menu = idm.get_school_menu_for_date(connect_db, today_iso, "Öğle Yemeği")
		if today_menu and today_menu.get("items"):
			m_items_s = ", ".join(f"{it['name']} ({it.get('carbs_g', 0)}g)" for it in today_menu["items"][:8])
			school_ctx += f" | Bugünkü Okul Menüsü ({today_menu['meal_type']}, Toplam {today_menu['total_carbs_g']}g karb): {m_items_s}"
	except Exception:
		pass

	strict_pdf_mode = str(get_app_settings().get("gemini_strict_kvkk_pdf", "0")).strip() == "1"
	ok, reply_txt, used_m, transcribed, export_spec, write_spec = gai.chat_with_gemini_assistant(
		api_key=api_key,
		model=model,
		user_message=raw_msg,
		history=chat_history,
		attachments=raw_atts if raw_atts else None,
		voice_audio_b64=str(payload.get("voice_audio_b64") or ""),
		voice_audio_mime=str(payload.get("voice_audio_mime") or "audio/wav"),
		anon_person_context=anon_person_ctx,
		school_context=school_ctx,
		sensitive_names=sensitive_names,
		available_classes=all_cls,
		strict_kvkk_pdf=strict_pdf_mode,
	)
	if not ok:
		return {"ok": False, "error": reply_txt}

	downloads: list[dict[str, str]] = []
	refresh_ui = False
	write_proposal: dict[str, Any] | None = None
	if isinstance(export_spec, dict) and export_spec:
		export_spec = _coerce_mutating_sql_export_spec(export_spec)
		exp_act = str(export_spec.get("action") or "").strip().lower()
		if exp_act in _MUTATING_CHAT_EXPORT_ACTIONS:
			prop_meta = _build_export_write_proposal(export_spec)
			cw_token = ui.register_pending_chat_write({
				"kind": "export_mutation",
				"export_spec": export_spec,
				"context_pid": int(context_pid) if context_pid else None,
				"fallback_reply": reply_txt,
			})
			write_proposal = {
				"token": cw_token,
				"mode": prop_meta["mode"],
				"is_destructive": prop_meta["is_destructive"],
				"title": prop_meta["title"],
				"confirm_label": prop_meta["confirm_label"],
				"items": prop_meta["items"],
				"candidates": [],
				"default_student_id": None,
				"has_attachment": False,
			}
		else:
			downloads, exp_note = _execute_gemini_chat_export(export_spec, int(context_pid) if context_pid else None, reply_txt)
			if exp_note:
				reply_txt = (reply_txt + exp_note).strip()

	# 2. Yapılandırılmış Veri / Belge Yazma Önerisi (Onay Kartı Hazırla)
	if write_proposal is None and isinstance(write_spec, dict) and write_spec:
		ws_items = _summarize_write_spec_items(write_spec)
		if ws_items:
			# Ses çözümü veya write_spec ipuçlarından yerel adayları sırala
			hints = {
				"name_hint": str(write_spec.get("person_hint") or pre_name or "").strip(),
				"student_no_hint": str(write_spec.get("student_no_hint") or "").strip(),
				"class_hint": str(write_spec.get("class_hint") or "").strip(),
			}
			if not hints["name_hint"] and transcribed:
				tr_pid, tr_nm = _detect_local_person_in_text(transcribed)
				if tr_nm:
					hints["name_hint"] = tr_nm
				if tr_pid and not pre_pid:
					pre_pid = tr_pid
			ranked = dstudio.rank_matching_people(connect_db, hints, limit=25)
			cand_list: list[dict[str, Any]] = []
			seen_ids: set[int] = set()
			default_sid: int | None = None

			if pre_pid:
				p_pre = get_person_by_id(pre_pid)
				if p_pre:
					default_sid = int(p_pre["id"])
					seen_ids.add(default_sid)
					cand_list.append({
						"id": default_sid,
						"label": f"🎯 {mask_kvkk_value(p_pre['full_name'], 'name')} · {p_pre['class_name']}",
					})
			for rp in ranked:
				rid = int(rp["id"])
				if rid in seen_ids:
					continue
				seen_ids.add(rid)
				tag = "🎯 " if rp.get("_match_score", 0) >= 0.45 else ""
				cand_list.append({
					"id": rid,
					"label": f"{tag}{mask_kvkk_value(rp['full_name'], 'name')} · {rp['class_name']}",
				})
				if default_sid is None and rp.get("_match_score", 0) >= 0.45:
					default_sid = rid
			if active_pid and int(active_pid) not in seen_ids:
				p_act = get_person_by_id(int(active_pid))
				if p_act:
					cand_list.insert(0, {
						"id": int(p_act["id"]),
						"label": f"📌 {mask_kvkk_value(p_act['full_name'], 'name')} · {p_act['class_name']} (Aktif)",
					})
			if default_sid is None:
				default_sid = int(active_pid) if active_pid else (cand_list[0]["id"] if cand_list else None)

			if cand_list and default_sid is not None:
				cw_token = ui.register_pending_chat_write({
					"write_spec": write_spec,
					"default_student_id": default_sid,
					"source_filename": first_att_name or "Gemini_Sohbet",
					"source_bytes": first_att_bytes,
				})
				write_proposal = {
					"token": cw_token,
					"title": f"Kişi Dosyasına İşlenecek Veriler ({write_spec.get('document_type') or 'Klinik Kayıt'})",
					"default_student_id": default_sid,
					"candidates": cand_list[:20],
					"items": ws_items,
					"has_attachment": bool(first_att_bytes and first_att_name),
				}

	return {
		"ok": True,
		"reply_text": reply_txt,
		"model": used_m,
		"transcribed": transcribed,
		"downloads": downloads,
		"write_proposal": write_proposal,
		"refresh_ui": refresh_ui,
	}


