def make_screening_import_template() -> bytes:
	if not _ensure_openpyxl_loaded() or Workbook is None:
		raise RuntimeError("Excel oluşturucu (openpyxl) yüklü değil.")
	wb = Workbook()
	ws = wb.active
	ws.title = "Sağlık Taraması"

	headers = ["Sınıf", "Ad Soyad", "Cinsiyet", "Doğum Tarihi", "Boy (cm)", "Kilo (kg)"]
	header_font = Font(name="Segoe UI", size=11, bold=True, color="FFFFFF")
	header_fill = PatternFill(start_color="0D9488", end_color="0D9488", fill_type="solid")
	center_align = Alignment(horizontal="center", vertical="center")
	left_align = Alignment(horizontal="left", vertical="center")
	right_align = Alignment(horizontal="right", vertical="center")
	thin_border = Border(
		left=Side(style='thin', color='CBD5E1'),
		right=Side(style='thin', color='CBD5E1'),
		top=Side(style='thin', color='CBD5E1'),
		bottom=Side(style='thin', color='CBD5E1')
	)

	ws.append(headers)
	for col_idx in range(1, len(headers) + 1):
		cell = ws.cell(row=1, column=col_idx)
		cell.font = header_font
		cell.fill = header_fill
		cell.alignment = center_align
		cell.border = thin_border
	ws.row_dimensions[1].height = 26

	sample_rows = [
		("A Şubesi", "ALİ ASAF DOĞAN", "E", "2021-09-10", 115.0, 24.0),
		("A Şubesi", "GÖKTUĞ GÖZEL", "E", "2022-08-03", None, None),
		("A Şubesi", "SEYCAN AY", "K", "2022-06-09", 121.0, 28.3),
		("A Şubesi", "ZEYNEP BAL", "K", "2021-05-31", 115.0, 23.0),
		("A Şubesi", "ZEYNEP TAŞDEMİR", "K", "2021-07-15", 117.0, 23.5),
		("B Şubesi", "NİSA ÖNLER", "K", "2022-07-16", 104.0, 16.25),
		("B Şubesi", "YAĞIZ HAN ALADAĞ", "E", "2021-02-23", 105.0, 14.25),
	]

	row_font = Font(name="Segoe UI", size=10)
	for r_idx, r_data in enumerate(sample_rows, start=2):
		ws.append(r_data)
		ws.row_dimensions[r_idx].height = 20
		for col_idx in range(1, len(r_data) + 1):
			cell = ws.cell(row=r_idx, column=col_idx)
			cell.font = row_font
			cell.border = thin_border
			if col_idx in [1, 3, 4]:
				cell.alignment = center_align
			elif col_idx in [5, 6]:
				cell.alignment = right_align
				if col_idx == 5 and cell.value is not None:
					cell.number_format = "0.0"
				elif col_idx == 6 and cell.value is not None:
					cell.number_format = "0.00"
			else:
				cell.alignment = left_align

	col_widths = {1: 18, 2: 30, 3: 12, 4: 16, 5: 14, 6: 14}
	for col_idx, width in col_widths.items():
		ws.column_dimensions[get_column_letter(col_idx)].width = width

	buf = io.BytesIO()
	wb.save(buf)
	return buf.getvalue()


def parse_screening_image_ocr(image_bytes: bytes) -> list[dict[str, Any]]:
	from PIL import Image
	import numpy as np
	reader = get_ocr_reader()
	img = Image.open(io.BytesIO(image_bytes)).convert("RGB")
	np_img = np.asarray(img)
	results = reader.readtext(np_img, detail=1)

	items = []
	for bbox, text, prob in results:
		t = str(text).strip()
		if not t:
			continue
		ys = [p[1] for p in bbox]
		xs = [p[0] for p in bbox]
		h = max(ys) - min(ys)
		y_center = sum(ys) / len(ys)
		items.append({
			"text": t,
			"y": y_center,
			"h": h,
			"min_x": min(xs),
			"prob": prob
		})
	if not items:
		return []

	items.sort(key=lambda it: it["y"])
	med_h = sorted(it["h"] for it in items)[len(items)//2]
	row_thresh = max(12.0, med_h * 0.6)

	rows = []
	curr_row = [items[0]]
	for it in items[1:]:
		if abs(it["y"] - curr_row[0]["y"]) <= row_thresh:
			curr_row.append(it)
		else:
			curr_row.sort(key=lambda x: x["min_x"])
			rows.append(curr_row)
			curr_row = [it]
	if curr_row:
		curr_row.sort(key=lambda x: x["min_x"])
		rows.append(curr_row)

	records = []
	for r in rows:
		texts = [it["text"] for it in r]
		line_str = " ".join(texts).lower()
		if any(h in line_str for h in ["ad soyad", "cinsiyet", "dogum", "boy", "kilo"]):
			continue

		cls_val = None
		dob_val = None
		sex_val = None
		nums = []
		name_parts = []

		for it in r:
			t = it["text"].strip()
			m_date = re.search(r"(\d{4}[-./]\d{1,2}[-./]\d{1,2}|\d{1,2}[-./]\d{1,2}[-./]\d{4})", t)
			if m_date and not dob_val:
				raw_d = m_date.group(1).replace("/", "-").replace(".", "-")
				parts = raw_d.split("-")
				if len(parts[0]) == 4:
					dob_val = f"{parts[0]}-{parts[1].zfill(2)}-{parts[2].zfill(2)}"
				else:
					dob_val = f"{parts[2]}-{parts[1].zfill(2)}-{parts[0].zfill(2)}"
				continue
			if ("şube" in t.lower() or "sube" in t.lower()) and not cls_val:
				cls_val = t
				continue
			if t.upper() in ["E", "K", "ERKEK", "KIZ", "M", "F"] and not sex_val:
				sex_val = "Erkek" if t.upper() in ["E", "ERKEK", "M"] else "Kız"
				continue
			num_clean = t.replace(",", ".")
			m_num = re.match(r"^(\d{1,5}(?:\.\d{1,2})?)$", num_clean)
			if m_num:
				nums.append(float(m_num.group(1)))
				continue
			name_parts.append(t)

		height_val = None
		weight_val = None
		if len(nums) == 1:
			if nums[0] >= 60:
				height_val = normalize_height(nums[0])
			else:
				weight_val = normalize_weight(nums[0], is_adult=False)
		elif len(nums) >= 2:
			if nums[0] > nums[1]:
				height_val = normalize_height(nums[0])
				weight_val = normalize_weight(nums[1], is_adult=False)
			else:
				height_val = normalize_height(nums[1])
				weight_val = normalize_weight(nums[0], is_adult=False)

		full_name = " ".join(name_parts).strip()
		if full_name:
			records.append({
				"class_name": cls_val or "",
				"full_name": full_name,
				"sex": sex_val,
				"birth_date": dob_val,
				"height_cm": height_val,
				"weight_kg": weight_val
			})
	return records


def _extract_docx_screening_tables_and_lines(file_bytes: bytes) -> tuple[list[tuple[str, pd.DataFrame]], list[str]]:
	"""Word (.docx) belgesindeki tüm tabloları (varsa üst başlık sınıf ipucuyla) ve paragraf satırlarını çıkarır."""
	if not _ensure_docx_loaded() or docx is None:
		raise RuntimeError("Word (.docx) okuma kütüphanesi (python-docx) yüklenemedi.")
	doc_obj = docx.Document(io.BytesIO(file_bytes))
	tables_out: list[tuple[str, pd.DataFrame]] = []
	last_cls_hint = ""
	tbl_map = {t._element: t for t in doc_obj.tables}
	para_map = {p._element: p for p in doc_obj.paragraphs}
	hdr_words = ("ad", "isim", "soyad", "sınıf", "sinif", "şube", "sube", "boy", "kilo", "cinsiyet", "doğum", "dogum")

	def _detect_cls_heading(txt: str) -> str:
		clean = re.sub(r"\s+", " ", txt or "").strip()
		if not clean or len(clean) > 80:
			return ""
		if re.search(r"(\d+\s*[-/ ]?\s*[A-ZÇĞİÖŞÜ]|anasınıfı|ana\s*sınıfı|şube|sube)", clean, flags=re.IGNORECASE):
			if not any(w in clean.lower() for w in ("boy (cm)", "kilo (kg)", "ad soyad")):
				return clean
		return ""

	for child in doc_obj.element.body:
		if child in para_map:
			ptxt = (para_map[child].text or "").strip()
			h_cls = _detect_cls_heading(ptxt)
			if h_cls:
				last_cls_hint = h_cls
		elif child in tbl_map:
			tbl = tbl_map[child]
			raw_rows: list[list[str]] = []
			for r in tbl.rows:
				row_vals = [re.sub(r"\s+", " ", (c.text or "").strip()) for c in r.cells]
				if any(row_vals):
					raw_rows.append(row_vals)
			if not raw_rows:
				continue
			first_low = " ".join(raw_rows[0]).lower()
			if any(k in first_low for k in hdr_words) and len(raw_rows) >= 2:
				cols = [c or f"Sutun_{i+1}" for i, c in enumerate(raw_rows[0])]
				df_t = pd.DataFrame(raw_rows[1:], columns=cols)
			else:
				cols = [f"Sutun_{i+1}" for i in range(len(raw_rows[0]))]
				df_t = pd.DataFrame(raw_rows, columns=cols)
			tables_out.append((last_cls_hint, df_t))

	para_lines = [re.sub(r"\s+", " ", (p.text or "").strip()) for p in doc_obj.paragraphs if (p.text or "").strip()]
	return tables_out, para_lines


def parse_screening_file_or_image(file_bytes: bytes, file_name: str) -> list[dict[str, Any]]:
	lower_fn = file_name.lower()
	if lower_fn.endswith((".png", ".jpg", ".jpeg", ".bmp", ".webp")):
		return parse_screening_image_ocr(file_bytes)

	def clean_val(v):
		if v is None or pd.isna(v):
			return None
		s = str(v).strip()
		return s if s else None

	def parse_date_str(v):
		if v is None or pd.isna(v):
			return None
		if isinstance(v, (datetime, date, pd.Timestamp)):
			return v.strftime("%Y-%m-%d")
		s = str(v).strip().replace("/", "-").replace(".", "-")
		m = re.search(r"(\d{4}-\d{1,2}-\d{1,2}|\d{1,2}-\d{1,2}-\d{4})", s)
		if m:
			parts = m.group(1).split("-")
			if len(parts[0]) == 4:
				return f"{parts[0]}-{parts[1].zfill(2)}-{parts[2].zfill(2)}"
			return f"{parts[2]}-{parts[1].zfill(2)}-{parts[0].zfill(2)}"
		return None

	def parse_sex_str(v):
		if not v or pd.isna(v):
			return None
		s = str(v).strip().upper()
		if s in ["E", "ERKEK", "M", "MALE", "BOY"]:
			return "Erkek"
		if s in ["K", "KIZ", "KADIN", "F", "FEMALE", "GIRL"]:
			return "Kız"
		return None

	def normalize_col(c):
		s = str(c).lower().strip()
		trans = str.maketrans("ıüğşöç", "iugsoc")
		s = s.translate(trans)
		return re.sub(r"[^a-z0-9]", "", s)

	def _extract_records_from_df(df_in: pd.DataFrame, fallback_class: str = "") -> list[dict[str, Any]]:
		if df_in is None or df_in.empty:
			return []
		col_map = {}
		for col in df_in.columns:
			norm = normalize_col(col)
			if "sinif" in norm or "sube" in norm or norm in ["class", "grade"]:
				col_map["class_name"] = col
			elif any(k in norm for k in ["adsoyad", "adisoyadi", "isim", "ogrenciadi", "fullname", "name"]):
				col_map["full_name"] = col
			elif "cinsiyet" in norm or norm in ["sex", "gender"]:
				col_map["sex"] = col
			elif any(k in norm for k in ["dogumtarihi", "dogum", "dogumgunu", "bdate", "birthdate", "dob"]):
				col_map["birth_date"] = col
			elif "boy" in norm or "height" in norm:
				col_map["height_cm"] = col
			elif "kilo" in norm or "agirlik" in norm or "weight" in norm:
				col_map["weight_kg"] = col

		if "full_name" not in col_map and len(df_in.columns) >= 2:
			cols = list(df_in.columns)
			# İlk sütun sıra numarası (1, 2, 3...) veya tarih/ad olabilir; tipik şablon düzeni:
			if "class_name" not in col_map and len(cols) >= 6:
				col_map["class_name"] = cols[0]
				col_map["full_name"] = cols[1]
				col_map["sex"] = cols[2]
				col_map["birth_date"] = cols[3]
				col_map["height_cm"] = cols[4]
				col_map["weight_kg"] = cols[5]
			elif len(cols) >= 5 and fallback_class:
				col_map["full_name"] = cols[0]
				col_map["sex"] = cols[1]
				col_map["birth_date"] = cols[2]
				col_map["height_cm"] = cols[3]
				col_map["weight_kg"] = cols[4]
			else:
				col_map["class_name"] = cols[0]
				col_map["full_name"] = cols[1]
				if len(cols) >= 3:
					col_map["sex"] = cols[2]
				if len(cols) >= 4:
					col_map["birth_date"] = cols[3]
				if len(cols) >= 5:
					col_map["height_cm"] = cols[4]
				if len(cols) >= 6:
					col_map["weight_kg"] = cols[5]

		out_recs = []
		for _, row in df_in.iterrows():
			fn = clean_val(row.get(col_map.get("full_name")))
			if not fn or str(fn).lower() in ["nan", "none", "ad soyad", "adı soyadı", "isim"]:
				continue
			cls = clean_val(row.get(col_map.get("class_name"))) or fallback_class or ""
			sx = parse_sex_str(row.get(col_map.get("sex")))
			dob = parse_birth_date(row.get(col_map.get("birth_date"))) or parse_date_str(row.get(col_map.get("birth_date")))
			h = normalize_height(row.get(col_map.get("height_cm")))
			w = normalize_weight(row.get(col_map.get("weight_kg")), is_adult=False)

			out_recs.append({
				"class_name": cls,
				"full_name": fn,
				"sex": sx,
				"birth_date": dob,
				"height_cm": h,
				"weight_kg": w,
			})
		return out_recs

	if lower_fn.endswith(".docx"):
		tables_found, para_lines = _extract_docx_screening_tables_and_lines(file_bytes)
		all_recs: list[dict[str, Any]] = []
		for cls_hint, df_t in tables_found:
			all_recs.extend(_extract_records_from_df(df_t, fallback_class=cls_hint))
		if not all_recs and para_lines:
			delim_lines = [ln for ln in para_lines if any(sep in ln for sep in (";", "|", "\t", ","))]
			if delim_lines:
				sep_use = next((s for s in ("|", "\t", ";", ",") if s in delim_lines[0]), ",")
				try:
					df_p = pd.read_csv(io.StringIO("\n".join(delim_lines)), sep=sep_use, dtype=object)
					all_recs.extend(_extract_records_from_df(df_p))
				except Exception:
					pass
		return all_recs

	if lower_fn.endswith(".doc"):
		raise ValueError("Eski .doc formatı doğrudan okunamıyor. Lütfen belgeyi Word'de '.docx' olarak kaydedip yükleyin.")

	if lower_fn.endswith((".xlsx", ".xls")):
		df = pd.read_excel(io.BytesIO(file_bytes), dtype=object)
	elif lower_fn.endswith((".csv", ".txt")):
		try:
			df = pd.read_csv(io.BytesIO(file_bytes), sep=None, engine="python", dtype=object)
		except Exception:
			df = pd.read_csv(io.BytesIO(file_bytes), dtype=object)
	else:
		raise ValueError(f"Desteklenmeyen dosya formatı: {file_name}")

	return _extract_records_from_df(df)


def commit_screening_import(
	parsed_rows: list[dict[str, Any]],
	screening_date: str | None = None,
	nurse_name: str | None = None,
	default_class: str | None = None,
) -> tuple[int, int, int]:
	scr_date = str(screening_date or date.today().isoformat())[:10]
	now_iso = datetime.now().isoformat(timespec="seconds")
	app_cfg = get_app_settings()
	scr_by = (nurse_name or app_cfg.get("nurse_name", "")).strip() or "Okul Revir Sorumlusu"

	updated_cnt = 0
	screened_cnt = 0
	added_cnt = 0

	with connect_db() as connection:
		classes_rows = connection.execute("SELECT id, name FROM classes").fetchall()
		class_map = {r["name"]: r["id"] for r in classes_rows}

		db_students = connection.execute(
			"SELECT id, full_name, class_id, sex, birth_date, student_no FROM students"
		).fetchall()
		student_map = {_normalize_name_for_match(s["full_name"]): s for s in db_students}

		for r in parsed_rows:
			raw_fn = str(r.get("full_name") or "").strip()
			if not raw_fn:
				continue
			k = _normalize_name_for_match(raw_fn)
			stu = student_map.get(k)

			cls_in = str(r.get("class_name") or default_class or "").strip()
			matched_cid = None
			if cls_in:
				for cname, cid in class_map.items():
					if cls_in == cname or cname.endswith(f"/ {cls_in}"):
						matched_cid = cid
						break
				if not matched_cid:
					m_sube = re.search(r"([A-ZĞÜŞİÖÇIİ])\s*Şubesi?", cls_in, re.IGNORECASE)
					if m_sube:
						letter = m_sube.group(1).upper()
						for cname, cid in class_map.items():
							if f"/ {letter} Şubesi" in cname or f" {letter} Şubesi" in cname:
								matched_cid = cid
								break
				if not matched_cid:
					for cname, cid in class_map.items():
						if cls_in in cname or _normalize_name_for_match(cls_in) in _normalize_name_for_match(cname):
							matched_cid = cid
							break
				if not matched_cid:
					full_cname = f"Özel Eğitim Ana Sınıfı / {cls_in}" if (not cls_in.startswith("Özel") and "Şubesi" in cls_in) else cls_in
					connection.execute("INSERT INTO classes(name) VALUES (?)", (full_cname,))
					matched_cid = connection.execute("SELECT last_insert_rowid()").fetchone()[0]
					class_map[full_cname] = matched_cid

			sex_in = normalize_sex(r.get("sex"))
			dob_in = r.get("birth_date")
			h_val = float(r["height_cm"]) if (r.get("height_cm") is not None and float(r["height_cm"]) > 0) else None
			w_val = float(r["weight_kg"]) if (r.get("weight_kg") is not None and float(r["weight_kg"]) > 0) else None

			if stu:
				stu_id = int(stu["id"])
				sex_final = sex_in or normalize_sex(stu["sex"]) or "E"
				dob_final = dob_in or stu["birth_date"]
				cid_final = matched_cid or stu["class_id"]

				connection.execute(
					"UPDATE students SET sex=?, birth_date=?, class_id=? WHERE id=?",
					(sex_final, dob_final, cid_final, stu_id)
				)
				updated_cnt += 1
			else:
				sex_final = sex_in or "E"
				dob_final = dob_in
				cid_final = matched_cid or (list(class_map.values())[0] if class_map else 1)

				cursor = connection.execute(
					"""INSERT INTO students(class_id, full_name, sex, birth_date, person_type)
					   VALUES (?, ?, ?, ?, 'Öğrenci')""",
					(cid_final, raw_fn, sex_final, dob_final)
				)
				stu_id = int(cursor.lastrowid)
				added_cnt += 1

			if h_val is not None or w_val is not None:
				# 1. School screenings
				connection.execute(
					"""INSERT INTO school_screenings(
						student_id, screening_date, height_cm, weight_kg,
						notes, screened_by, created_at
					) VALUES (?, ?, ?, ?, ?, ?, ?)""",
					(stu_id, scr_date, h_val, w_val, "Toplu içe aktarım (Excel/OCR)", scr_by, now_iso)
				)

				# 2. Health profile
				connection.execute(
					"""INSERT INTO health_profiles(student_id, last_screened_at, updated_at, reviewed_by)
					   VALUES (?, ?, ?, ?)
					   ON CONFLICT(student_id) DO UPDATE SET
						   last_screened_at = excluded.last_screened_at,
						   updated_at = excluded.updated_at,
						   reviewed_by = COALESCE(health_profiles.reviewed_by, excluded.reviewed_by)""",
					(stu_id, scr_date, now_iso, scr_by)
				)

				# 3. Measurements (upsert same-date + compute BMI / age_months)
				_upsert_measurement_conn(
					connection,
					stu_id,
					date.fromisoformat(scr_date),
					h_val,
					w_val,
					birth_date=dob_final,
					sex=sex_final,
				)
				screened_cnt += 1

	sync_all_person_data_files()
	sync_after_person_mutation(None)
	return updated_cnt, screened_cnt, added_cnt


def render_screening_import_section(target_class: str | None = None) -> None:
	ui.markdown("### 📥 Toplu Tarama Verisi İçe Aktar (Excel / Word / CSV / Resim-OCR)")
	ui.caption("Öğrencilerin sınıf, boy, kilo, cinsiyet ve doğum tarihi tarama verilerini Excel (.xlsx, .xls), Word (.docx), CSV (.csv) veya liste fotoğrafları (.png, .jpg) üzerinden topluca sisteme aktarın.")

	card_key = f"scr_imp_{target_class or 'all'}"
	col_up, col_info = ui.columns([2.2, 1.3])

	with col_up:
		uploaded_file = ui.file_uploader(
			"Tarama Listesi Dosyasını (.xlsx, .xls, .docx, .csv) veya Fotoğrafını (.png, .jpg) Seçin",
			type=["xlsx", "xls", "docx", "csv", "png", "jpg", "jpeg"],
			key=f"uploader_{card_key}"
		)

		c_date, c_nurse = ui.columns(2)
		app_cfg = get_app_settings()
		def_nurse = app_cfg.get("nurse_name", "Okul Revir Sorumlusu")
		scr_date_val = c_date.date_input("🗓️ Tarama Tarihi", value=date.today(), key=f"date_{card_key}")
		scr_nurse_val = c_nurse.text_input("👩‍⚕️ Taramayı Yapan Yetkili", value=def_nurse, key=f"nurse_{card_key}")

	with col_info:
		ui.markdown("##### 📄 Format & Örnek Excel")
		ui.caption("Beklenen sütun başlıkları ve sırası:")
		ui.code("Sınıf, Ad Soyad, Cinsiyet, Doğum Tarihi, Boy (cm), Kilo (kg)", language="text")
		ui.caption("💡 Belge veya liste fotoğrafı yüklendiğinde optik karakter tanıma (OCR) motoru görseldeki tabloyu okur.")
		tpl_bytes = make_screening_import_template()
		ui.download_button(
			"📥 Örnek Tarama Excel Şablonunu İndir (.xlsx)",
			data=tpl_bytes,
			file_name="ornek_tarama_listesi.xlsx",
			mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
			key=f"btn_dl_tpl_{card_key}",
			use_container_width=True,
		)

	if uploaded_file is not None:
		try:
			f_bytes_up = uploaded_file.getvalue()
			f_name_up = uploaded_file.name
			f_sig = f"{f_name_up}:{len(f_bytes_up)}"
			ai_cache_k = f"ai_scr_mapped_{card_key}"
			is_gai_imp, gai_imp_key, gai_imp_model = _get_active_gemini_config()
			strict_imp_pdf = str(get_app_settings().get("gemini_strict_kvkk_pdf", "0")).strip() == "1"

			with ui.spinner("Dosya / Görsel işleniyor ve tarama verileri çözümleniyor..."):
				parsed_rows = parse_screening_file_or_image(f_bytes_up, f_name_up)

			cached_ai = ui.session_state.get(ai_cache_k)
			use_ai_rows = isinstance(cached_ai, dict) and cached_ai.get("sig") == f_sig and bool(cached_ai.get("rows"))
			if use_ai_rows:
				parsed_rows = cached_ai["rows"]
				ui.info(f"🤖 **AI Karmaşık Tablo Eşleme Etkin:** {cached_ai.get('note', '')}")

			if is_gai_imp:
				ai_btn_lbl = (
					"🤖 Sütunları / Birimleri Gemini AI ile Eşle & Normalleştir"
					if parsed_rows
					else "🤖 Karmaşık Dosyayı Gemini AI ile Çözümle & Sütunları Eşle"
				)
				ab1, ab2 = ui.columns([2.2, 1.0])
				with ab1:
					if ui.button(ai_btn_lbl, type="secondary" if parsed_rows else "primary", use_container_width=True, key=f"btn_ai_scr_map_{card_key}"):
						with ui.spinner("Gemini AI tablo sütunlarını, birimlerini ve satırları akıllı eşliyor..."):
							ok_am, am_rows, am_note = parse_screening_file_with_ai_fallback(
								f_bytes_up, f_name_up, gai_imp_key, gai_imp_model, strict_kvkk_pdf=strict_imp_pdf
							)
						if ok_am and am_rows:
							ui.session_state[ai_cache_k] = {"sig": f_sig, "rows": am_rows, "note": am_note}
							ui.rerun()
						else:
							ui.error(f"AI tarama eşleme başarısız: {am_note}")
				with ab2:
					if use_ai_rows and ui.button("↩️ Standart Okumaya Dön", use_container_width=True, key=f"btn_ai_scr_reset_{card_key}"):
						ui.session_state.pop(ai_cache_k, None)
						ui.rerun()

			if not parsed_rows:
				ui.warning("⚠️ Yüklenen dosyadan veya görselden geçerli öğrenci tarama satırı tespit edilemedi. Yukarıdaki Gemini AI eşleme butonunu deneyebilir veya sütun başlıklarını kontrol edebilirsiniz.")
				return

			with connect_db() as connection:
				db_stus = connection.execute("SELECT id, full_name, sex, birth_date FROM students").fetchall()
				db_map = {_normalize_name_for_match(s["full_name"]): s for s in db_stus}

			preview_list = []
			meas_cnt = 0
			matched_cnt = 0
			new_cnt = 0

			for r in parsed_rows:
				fn = r.get("full_name") or ""
				k = _normalize_name_for_match(fn)
				stu = db_map.get(k)
				is_matched = stu is not None
				if is_matched:
					matched_cnt += 1
				else:
					new_cnt += 1

				h = r.get("height_cm")
				w = r.get("weight_kg")
				if h or w:
					meas_cnt += 1

				bmi_calc = (w / ((h / 100.0) ** 2)) if (h and w and h > 0 and w > 0) else None

				status_badge = "🟢 Kayıtlı Öğrenci" if is_matched else "➕ Yeni Eklenecek"
				if h or w:
					action_txt = "📏 Tarama & Ölçüm Kaydedilecek"
				else:
					action_txt = "ℹ️ Yalnızca Kimlik Güncellenecek"

				preview_list.append({
					"Sınıf": r.get("class_name") or (target_class or "—"),
					"Ad Soyad": fn,
					"Cinsiyet": r.get("sex") or (stu["sex"] if is_matched else "—"),
					"Doğum Tarihi": r.get("birth_date") or (stu["birth_date"] if is_matched else "—"),
					"Boy (cm)": f"{h:.1f}" if h else "—",
					"Kilo (kg)": f"{w:.2f}" if w else "—",
					"VKİ": f"{bmi_calc:.1f}" if bmi_calc else "—",
					"Sistem Durumu": status_badge,
					"İşlem": action_txt,
				})

			ui.markdown("---")
			ui.markdown("##### 🔍 Önizleme ve Veri Özeti")
			m1, m2, m3, m4 = ui.columns(4)
			m1.metric("Toplam Satır", len(parsed_rows))
			m2.metric("Ölçüm İçeren (Boy/Kilo)", meas_cnt)
			m3.metric("Sistemde Kayıtlı", matched_cnt)
			m4.metric("Yeni Öğrenci", new_cnt)

			ui.dataframe(pd.DataFrame(preview_list), hide_index=True, use_container_width=True)

			btn_txt = f"🚀 {len(parsed_rows)} Öğrencinin Tarama ve Ölçüm Bilgilerini Sisteme Aktar"
			if ui.button(btn_txt, type="primary", use_container_width=True, key=f"btn_commit_{card_key}"):
				with ui.spinner("Öğrenci profilleri, boy-kilo ölçümleri ve sağlık taramaları kaydediliyor..."):
					upd, scr, add = commit_screening_import(
						parsed_rows,
						screening_date=scr_date_val.isoformat(),
						nurse_name=scr_nurse_val,
						default_class=target_class,
					)
				ui.balloons()
				ui.success(f"🎉 **Aktarım Başarıyla Tamamlandı!** {scr} öğrencinin boy-kilo ölçümü ve sağlık taraması kaydedildi. {upd} öğrenci bilgisi güncellendi, {add} yeni öğrenci sisteme eklendi.")
				ui.rerun()

		except Exception as ex:
			ui.error(f"Dosya / Görsel işleme sırasında hata oluştu: {ex}")


