def _is_bulk_cell_blank(val: object) -> bool:
	if val is None:
		return True
	if isinstance(val, float) and math.isnan(val):
		return True
	try:
		if pd.isna(val):
			return True
	except (TypeError, ValueError):
		pass
	if isinstance(val, str):
		s = val.strip()
		return (not s) or s.lower() in {"nan", "none", "<na>"}
	return False


def _clean_bulk_str(val: object) -> str | None:
	if _is_bulk_cell_blank(val):
		return None
	s = clean_text(val)
	return s or None


def _coerce_bulk_float(val: object) -> float | None:
	if _is_bulk_cell_blank(val):
		return None
	num = numeric_value(val)
	if num is None or (isinstance(num, float) and math.isnan(num)):
		return None
	return float(num)


def _normalize_bulk_row_payload(row_dict: dict[str, Any]) -> dict[str, Any]:
	"""Extract and smart-normalize all editable fields for one bulk screening row."""
	h_val = None if _is_bulk_cell_blank(row_dict.get("Boy (cm)")) else parse_smart_clinical_value("height", row_dict.get("Boy (cm)"), is_adult=False)
	w_val = None if _is_bulk_cell_blank(row_dict.get("Kilo (kg)")) else parse_smart_clinical_value("weight", row_dict.get("Kilo (kg)"), is_adult=False)
	hc_val = None if _is_bulk_cell_blank(row_dict.get("Baş Çevresi (cm)")) else parse_smart_clinical_value("head_circ", row_dict.get("Baş Çevresi (cm)"), is_adult=False)
	t_val = None if _is_bulk_cell_blank(row_dict.get("Ateş (°C)")) else parse_smart_clinical_value("temperature", row_dict.get("Ateş (°C)"), is_adult=False)
	p_raw = None if _is_bulk_cell_blank(row_dict.get("Nabız (/dk)")) else parse_smart_clinical_value("pulse", row_dict.get("Nabız (/dk)"), is_adult=False)
	s_raw = None if _is_bulk_cell_blank(row_dict.get("SpO2 (%)")) else parse_smart_clinical_value("spo2", row_dict.get("SpO2 (%)"), is_adult=False)
	return {
		"height_cm": float(h_val) if h_val is not None else None,
		"weight_kg": float(w_val) if w_val is not None else None,
		"head_circ_cm": float(hc_val) if hc_val is not None else None,
		"temperature_c": float(t_val) if t_val is not None else None,
		"pulse_bpm": float(p_raw) if p_raw is not None else None,
		"spo2_pct": float(s_raw) if s_raw is not None else None,
		"wears_glasses": _clean_bulk_str(row_dict.get("Gözlük")),
		"vision_right": _clean_bulk_str(row_dict.get("Sağ Göz")),
		"vision_left": _clean_bulk_str(row_dict.get("Sol Göz")),
		"hair_screening": _clean_bulk_str(row_dict.get("Saç / Hijyen")),
		"hearing_right": _clean_bulk_str(row_dict.get("Sağ Kulak")),
		"hearing_left": _clean_bulk_str(row_dict.get("Sol Kulak")),
		"health_behavior": _clean_bulk_str(row_dict.get("Sağlık Davranışı")),
		"psychosocial_status": _clean_bulk_str(row_dict.get("Psikososyal Durum")),
		"notes": _clean_bulk_str(row_dict.get("Tarama Notu")),
	}


def _pick_recent_metric(
	exact_scr: dict[str, Any] | None,
	latest_scr: dict[str, Any] | None,
	exact_rec: dict[str, Any] | None,
	latest_rec: dict[str, Any] | None,
	scr_col: str,
	rec_col: str,
	scr_date_key: str = "screening_date",
	rec_date_key: str = "measured_at",
) -> float | None:
	if exact_scr and exact_scr.get(scr_col) is not None:
		return float(exact_scr[scr_col])
	if exact_rec and exact_rec.get(rec_col) is not None:
		return float(exact_rec[rec_col])
	s_val = latest_scr.get(scr_col) if latest_scr else None
	r_val = latest_rec.get(rec_col) if latest_rec else None
	if s_val is not None and r_val is not None:
		s_dt = str(latest_scr.get(scr_date_key) or "")[:10]
		r_dt = str(latest_rec.get(rec_date_key) or "")[:10]
		return float(r_val) if r_dt >= s_dt else float(s_val)
	if s_val is not None:
		return float(s_val)
	if r_val is not None:
		return float(r_val)
	return None


def _build_bulk_class_screening_df(class_name: str, target_date_iso: str) -> tuple[pd.DataFrame, set[int]]:
	"""Load ordered class students pre-populated with exact-date or latest screening/measurement/vital values."""
	t_date = (parse_birth_date(target_date_iso) or str(target_date_iso or date.today().isoformat()))[:10]
	with connect_db() as connection:
		stu_rows = connection.execute(
			"""SELECT s.id, s.student_no, s.full_name,
					  h.wears_glasses, h.vision_right, h.vision_left,
					  h.hair_screening, h.hearing_right, h.hearing_left,
					  h.health_behavior, h.psychosocial_status
			   FROM students s
			   JOIN classes c ON c.id = s.class_id
			   LEFT JOIN health_profiles h ON h.student_id = s.id
			   WHERE c.name = ?
			   ORDER BY
				   CASE WHEN TRIM(COALESCE(s.student_no, '')) = '' THEN 1 ELSE 0 END,
				   CASE WHEN TRIM(COALESCE(s.student_no, '')) GLOB '[0-9]*' THEN CAST(TRIM(s.student_no) AS INTEGER) ELSE 999999999 END,
				   s.student_no,
				   s.full_name""",
			(class_name,),
		).fetchall()

		sids = [int(r["id"]) for r in stu_rows]
		exact_scr_map: dict[int, dict[str, Any]] = {}
		latest_scr_map: dict[int, dict[str, Any]] = {}
		exact_meas_map: dict[int, dict[str, Any]] = {}
		latest_meas_map: dict[int, dict[str, Any]] = {}
		exact_vit_map: dict[int, dict[str, Any]] = {}
		latest_vit_map: dict[int, dict[str, Any]] = {}

		if sids:
			ph = ",".join("?" for _ in sids)
			for r in connection.execute(
				f"SELECT * FROM school_screenings WHERE student_id IN ({ph}) ORDER BY screening_date DESC, id DESC",
				sids,
			).fetchall():
				rd = dict(r)
				sid = int(rd["student_id"])
				if sid not in latest_scr_map:
					latest_scr_map[sid] = rd
				if str(rd.get("screening_date") or "")[:10] == t_date and sid not in exact_scr_map:
					exact_scr_map[sid] = rd

			for r in connection.execute(
				f"SELECT * FROM measurements WHERE student_id IN ({ph}) ORDER BY measured_on DESC, id DESC",
				sids,
			).fetchall():
				rd = dict(r)
				sid = int(rd["student_id"])
				if sid not in latest_meas_map:
					latest_meas_map[sid] = rd
				if str(rd.get("measured_on") or "")[:10] == t_date and sid not in exact_meas_map:
					exact_meas_map[sid] = rd

			for r in connection.execute(
				f"SELECT * FROM vital_readings WHERE student_id IN ({ph}) ORDER BY measured_at DESC, id DESC",
				sids,
			).fetchall():
				rd = dict(r)
				sid = int(rd["student_id"])
				if sid not in latest_vit_map:
					latest_vit_map[sid] = rd
				if str(rd.get("measured_at") or "")[:10] == t_date and sid not in exact_vit_map:
					exact_vit_map[sid] = rd

	records: list[dict[str, Any]] = []
	for s in stu_rows:
		sd = dict(s)
		sid = int(sd["id"])
		ex_s = exact_scr_map.get(sid)
		lt_s = latest_scr_map.get(sid)
		ex_m = exact_meas_map.get(sid)
		lt_m = latest_meas_map.get(sid)
		ex_v = exact_vit_map.get(sid)
		lt_v = latest_vit_map.get(sid)

		def _pick_qual(col: str, fallback_hp: bool = True) -> str | None:
			if ex_s and not _is_bulk_cell_blank(ex_s.get(col)):
				return str(ex_s[col]).strip()
			if lt_s and not _is_bulk_cell_blank(lt_s.get(col)):
				return str(lt_s[col]).strip()
			if fallback_hp and not _is_bulk_cell_blank(sd.get(col)):
				return str(sd[col]).strip()
			return None

		records.append({
			"student_id": sid,
			"Okul No": str(sd.get("student_no") or "").strip(),
			"Ad Soyad": str(sd.get("full_name") or "").strip(),
			"Boy (cm)": _pick_recent_metric(ex_s, lt_s, ex_m, lt_m, "height_cm", "height_cm", rec_date_key="measured_on"),
			"Kilo (kg)": _pick_recent_metric(ex_s, lt_s, ex_m, lt_m, "weight_kg", "weight_kg", rec_date_key="measured_on"),
			"Baş Çevresi (cm)": _pick_recent_metric(ex_s, lt_s, ex_m, lt_m, "head_circ_cm", "head_circ_cm", rec_date_key="measured_on"),
			"Ateş (°C)": _pick_recent_metric(ex_s, lt_s, ex_v, lt_v, "temperature_c", "temperature_c"),
			"Nabız (/dk)": _pick_recent_metric(ex_s, lt_s, ex_v, lt_v, "pulse_bpm", "pulse_bpm"),
			"SpO2 (%)": _pick_recent_metric(ex_s, lt_s, ex_v, lt_v, "spo2_pct", "spo2_pct"),
			"Gözlük": _pick_qual("wears_glasses"),
			"Sağ Göz": _pick_qual("vision_right") or "",
			"Sol Göz": _pick_qual("vision_left") or "",
			"Saç / Hijyen": _pick_qual("hair_screening"),
			"Sağ Kulak": _pick_qual("hearing_right"),
			"Sol Kulak": _pick_qual("hearing_left"),
			"Sağlık Davranışı": _pick_qual("health_behavior"),
			"Psikososyal Durum": _pick_qual("psychosocial_status") or "",
			"Tarama Notu": (str(ex_s["notes"]).strip() if (ex_s and not _is_bulk_cell_blank(ex_s.get("notes"))) else ""),
		})

	df = pd.DataFrame(records, columns=BULK_SCREENING_COLUMNS) if records else pd.DataFrame(columns=BULK_SCREENING_COLUMNS)
	for num_col in ("Boy (cm)", "Kilo (kg)", "Baş Çevresi (cm)", "Ateş (°C)", "Nabız (/dk)", "SpO2 (%)"):
		df[num_col] = pd.to_numeric(df[num_col], errors="coerce")
	return df, set(exact_scr_map.keys())


def _apply_bulk_screening_auto_fill(df: pd.DataFrame) -> pd.DataFrame:
	"""Fill only blank vision, hearing, hair hygiene, and glasses cells with Normal / Temiz defaults."""
	out_df = df.copy()
	if out_df.empty:
		return out_df
	for idx in out_df.index:
		for col, default_val in BULK_SCREENING_AUTOFILL_DEFAULTS.items():
			if col in out_df.columns and _is_bulk_cell_blank(out_df.at[idx, col]):
				out_df.at[idx, col] = default_val
	return out_df


def _merge_data_editor_state_into_df(df: pd.DataFrame, editor_state: object) -> pd.DataFrame:
	"""Apply pending data_editor edited_rows onto a snapshot DataFrame before button actions."""
	if not isinstance(editor_state, dict) or df.empty:
		return df
	out_df = df.copy()
	edited_rows = editor_state.get("edited_rows")
	if isinstance(edited_rows, dict):
		for row_idx_key, changes in edited_rows.items():
			try:
				pos = int(row_idx_key)
			except (TypeError, ValueError):
				continue
			if 0 <= pos < len(out_df) and isinstance(changes, dict):
				idx_label = out_df.index[pos]
				for col_name, new_val in changes.items():
					if col_name in out_df.columns:
						out_df.at[idx_label, col_name] = new_val
	return out_df


def save_bulk_class_screening_rows(
	df_rows: pd.DataFrame,
	screening_date_iso: str,
	baseline_df: pd.DataFrame | None = None,
	save_unchanged: bool = False,
	screened_by: str | None = None,
) -> dict[str, int]:
	"""Persist bulk table screening rows into school_screenings, measurements, vitals, and health_profiles."""
	if df_rows is None or df_rows.empty:
		return {"saved_count": 0, "skipped_empty": 0, "skipped_unchanged": 0}

	base_payload_map: dict[int, dict[str, Any]] = {}
	if baseline_df is not None and not baseline_df.empty:
		for _, b_row in baseline_df.iterrows():
			if _is_bulk_cell_blank(b_row.get("student_id")):
				continue
			b_sid = int(float(b_row["student_id"]))
			base_payload_map[b_sid] = _normalize_bulk_row_payload(b_row.to_dict())

	scr_date = parse_birth_date(screening_date_iso) or str(screening_date_iso or date.today().isoformat())[:10]
	saved_count = 0
	skipped_empty = 0
	skipped_unchanged = 0

	for _, row in df_rows.iterrows():
		if _is_bulk_cell_blank(row.get("student_id")):
			continue
		sid = int(float(row["student_id"]))
		payload = _normalize_bulk_row_payload(row.to_dict())
		if all(v is None for v in payload.values()):
			skipped_empty += 1
			continue

		if (not save_unchanged) and sid in base_payload_map and payload == base_payload_map[sid]:
			skipped_unchanged += 1
			continue

		save_school_screening(
			student_id=sid,
			screening_date=scr_date,
			height_cm=payload["height_cm"],
			weight_kg=payload["weight_kg"],
			head_circ_cm=payload["head_circ_cm"],
			temperature_c=payload["temperature_c"],
			pulse_bpm=payload["pulse_bpm"],
			spo2_pct=payload["spo2_pct"],
			wears_glasses=payload["wears_glasses"],
			vision_right=payload["vision_right"],
			vision_left=payload["vision_left"],
			hair_screening=payload["hair_screening"],
			hearing_right=payload["hearing_right"],
			hearing_left=payload["hearing_left"],
			health_behavior=payload["health_behavior"],
			psychosocial_status=payload["psychosocial_status"],
			notes=payload["notes"],
			screened_by=screened_by,
		)
		saved_count += 1

	if saved_count > 0:
		clear_all_data_caches()

	return {
		"saved_count": saved_count,
		"skipped_empty": skipped_empty,
		"skipped_unchanged": skipped_unchanged,
	}


def render_bulk_class_screening_tab(default_class: str | None = None, key_ctx: str = "top") -> None:
	"""Render Excel-like batch screening data_editor workspace for an entire school class."""
	ui.markdown("#### ⚡ Seri Sınıf Taraması (Toplu Tablo Girişi)")
	ui.caption(
		"Sınıfın tamamını tek tabloda klavyeyle hızlıca doldurun. Sayısal alanlarda `1055` → `105.5 cm`, `185` → `18.5 kg`, `366` → `36.6 °C` akıllı dönüşüm kayıt sırasında otomatik uygulanır."
	)

	all_classes = [c for c in get_classes() if c != "Sivil / Diğer"]
	if not all_classes:
		ui.warning("Henüz tanımlı sınıf bulunmuyor.")
		return

	sel_c1, sel_c2 = ui.columns([2.1, 1.1])
	with sel_c1:
		if default_class and default_class in all_classes:
			chosen_cls = default_class
			b_idx = all_classes.index(chosen_cls)
			b_prev = all_classes[b_idx - 1] if b_idx > 0 else None
			b_next = all_classes[b_idx + 1] if b_idx < len(all_classes) - 1 else None
			nav_l, nav_m, nav_r = ui.columns([0.42, 2.8, 0.42])
			with nav_l:
				ui.markdown("<div style='height:22px'></div>", unsafe_allow_html=True)
				if ui.button(
					"◀",
					key=f"btn_bulk_prev_cls_{key_ctx}_{chosen_cls}",
					disabled=(b_prev is None),
					help=f"Önceki Sınıf: {b_prev}" if b_prev else "İlk sınıftasınız",
					use_container_width=True,
				):
					_close_dyn_report_builder_dialog()
					ui.session_state["selected_screening_class"] = b_prev
					ui.rerun()
			with nav_m:
				ui.text_input(
					f"Seçili Sınıf ({b_idx + 1}/{len(all_classes)})",
					value=chosen_cls,
					disabled=True,
					key=f"bulk_scr_cls_locked_{key_ctx}_{chosen_cls}",
				)
			with nav_r:
				ui.markdown("<div style='height:22px'></div>", unsafe_allow_html=True)
				if ui.button(
					"▶",
					key=f"btn_bulk_next_cls_{key_ctx}_{chosen_cls}",
					disabled=(b_next is None),
					help=f"Sonraki Sınıf: {b_next}" if b_next else "Son sınıftasınız",
					use_container_width=True,
				):
					_close_dyn_report_builder_dialog()
					ui.session_state["selected_screening_class"] = b_next
					ui.rerun()
		else:
			sel_key_bulk = f"bulk_scr_cls_sel_{key_ctx}"
			prev_cls = ui.session_state.get(sel_key_bulk)
			cls_idx = all_classes.index(prev_cls) if prev_cls in all_classes else 0
			b_prev = all_classes[cls_idx - 1] if cls_idx > 0 else None
			b_next = all_classes[cls_idx + 1] if cls_idx < len(all_classes) - 1 else None
			nav_l, nav_m, nav_r = ui.columns([0.42, 2.8, 0.42])
			with nav_l:
				ui.markdown("<div style='height:22px'></div>", unsafe_allow_html=True)
				if ui.button(
					"◀",
					key=f"btn_bulk_prev_cls_{key_ctx}",
					disabled=(b_prev is None),
					help=f"Önceki Sınıf: {b_prev}" if b_prev else "İlk sınıftasınız",
					use_container_width=True,
				):
					ui.session_state[sel_key_bulk] = b_prev
					ui.rerun()
			with nav_m:
				chosen_cls = ui.selectbox(
					f"Taranacak Sınıfı Seçin ({cls_idx + 1}/{len(all_classes)})",
					all_classes,
					index=cls_idx,
					key=sel_key_bulk,
				)
			with nav_r:
				ui.markdown("<div style='height:22px'></div>", unsafe_allow_html=True)
				if ui.button(
					"▶",
					key=f"btn_bulk_next_cls_{key_ctx}",
					disabled=(b_next is None),
					help=f"Sonraki Sınıf: {b_next}" if b_next else "Son sınıftasınız",
					use_container_width=True,
				):
					ui.session_state[sel_key_bulk] = b_next
					ui.rerun()
	with sel_c2:
		chosen_date = ui.date_input("Tarama Tarihi", value=date.today(), key=f"bulk_scr_date_{key_ctx}")

	target_date_iso = chosen_date.isoformat()
	ns_key = f"{chosen_cls}||{target_date_iso}"
	last_ns_key = f"_bulk_scr_last_ns_{key_ctx}"
	base_df_key = f"_bulk_scr_base_df_{key_ctx}"
	work_df_key = f"_bulk_scr_work_df_{key_ctx}"
	exact_ids_key = f"_bulk_scr_exact_ids_{key_ctx}"
	seed_key = f"_bulk_scr_editor_seed_{key_ctx}"
	flash_key = f"_bulk_scr_flash_{key_ctx}"

	flash_msg = ui.session_state.pop(flash_key, None)
	if isinstance(flash_msg, tuple) and len(flash_msg) == 2:
		lvl, txt = flash_msg
		if lvl == "success":
			ui.success(txt)
		elif lvl == "warning":
			ui.warning(txt)
		else:
			ui.info(txt)

	if ui.session_state.get(last_ns_key) != ns_key or work_df_key not in ui.session_state or base_df_key not in ui.session_state:
		fresh_df, exact_ids = _build_bulk_class_screening_df(chosen_cls, target_date_iso)
		ui.session_state[base_df_key] = fresh_df.copy()
		ui.session_state[work_df_key] = fresh_df.copy()
		ui.session_state[exact_ids_key] = exact_ids
		ui.session_state[last_ns_key] = ns_key
		ui.session_state[seed_key] = int(ui.session_state.get(seed_key, 0)) + 1

	base_df: pd.DataFrame = ui.session_state[base_df_key]
	work_df: pd.DataFrame = ui.session_state[work_df_key]
	exact_ids: set[int] = ui.session_state.get(exact_ids_key, set())
	editor_seed = int(ui.session_state.get(seed_key, 0))
	editor_key = f"bulk_scr_editor_{key_ctx}_{editor_seed}"

	if work_df.empty:
		ui.warning(f"{chosen_cls} sınıfında kayıtlı öğrenci bulunmuyor.")
		return

	ui.info(
		f"👥 **{chosen_cls}** sınıfında **{len(work_df)}** öğrenci yüklendi · Seçili tarih (**{target_date_iso}**) için mevcut taraması olan: **{len(exact_ids)}** öğrenci. *(Diğer öğrenciler için önceki son tarama/ölçüm verileri başlangıç olarak getirildi.)*"
	)

	act_c1, act_c2 = ui.columns([2.4, 1.2])
	with act_c1:
		if ui.button(
			"✨ Boş Görme/İşitme/Saç Alanlarını 'Normal / Temiz' Olarak Otomatik Doldur",
			key=f"btn_bulk_scr_autofill_{key_ctx}",
			use_container_width=True,
		):
			merged_now = _merge_data_editor_state_into_df(work_df, ui.session_state.get(editor_key))
			filled_df = _apply_bulk_screening_auto_fill(merged_now)
			ui.session_state[work_df_key] = filled_df
			ui.session_state[seed_key] = editor_seed + 1
			ui.session_state[flash_key] = (
				"info",
				"✨ Boş görme, işitme, saç/hijyen ve gözlük hücreleri 'Normal / Temiz' varsayılanlarıyla dolduruldu. Gözden geçirip alttaki Kaydet butonuna basabilirsiniz.",
			)
			ui.rerun()
	with act_c2:
		if ui.button("🔄 Tabloyu Veritabanından Yenile", key=f"btn_bulk_scr_reload_{key_ctx}", use_container_width=True):
			fresh_df, fresh_exact = _build_bulk_class_screening_df(chosen_cls, target_date_iso)
			ui.session_state[base_df_key] = fresh_df.copy()
			ui.session_state[work_df_key] = fresh_df.copy()
			ui.session_state[exact_ids_key] = fresh_exact
			ui.session_state[seed_key] = editor_seed + 1
			ui.rerun()

	glasses_opts = ensure_options_contain(BULK_SCREENING_GLASSES_OPTIONS, [v for v in work_df["Gözlük"].tolist() if not _is_bulk_cell_blank(v)])
	hair_opts = ensure_options_contain(HAIR_SCREENING_OPTIONS, [v for v in work_df["Saç / Hijyen"].tolist() if not _is_bulk_cell_blank(v)])
	hearing_r_opts = ensure_options_contain(HEARING_SCREENING_OPTIONS, [v for v in work_df["Sağ Kulak"].tolist() if not _is_bulk_cell_blank(v)])
	hearing_l_opts = ensure_options_contain(HEARING_SCREENING_OPTIONS, [v for v in work_df["Sol Kulak"].tolist() if not _is_bulk_cell_blank(v)])
	behavior_opts = ensure_options_contain(HEALTH_BEHAVIOR_OPTIONS, [v for v in work_df["Sağlık Davranışı"].tolist() if not _is_bulk_cell_blank(v)])

	edited_df = ui.data_editor(
		work_df,
		hide_index=True,
		use_container_width=True,
		num_rows="fixed",
		height=min(620, max(240, 62 + len(work_df) * 37)),
		key=editor_key,
		column_config={
			"student_id": None,
			"Okul No": ui.column_config.TextColumn("Okul No", disabled=True, width="small"),
			"Ad Soyad": ui.column_config.TextColumn("Ad Soyad", disabled=True, width="medium"),
			"Boy (cm)": ui.column_config.NumberColumn("Boy (cm)", min_value=0.0, max_value=3000.0, step=0.1, format="%.1f", help="Örn: 105.5 veya 1055"),
			"Kilo (kg)": ui.column_config.NumberColumn("Kilo (kg)", min_value=0.0, max_value=3000.0, step=0.1, format="%.1f", help="Örn: 18.5 veya 185"),
			"Baş Çevresi (cm)": ui.column_config.NumberColumn("Baş Çevresi (cm)", min_value=0.0, max_value=800.0, step=0.1, format="%.1f", help="Örn: 48.5 veya 485"),
			"Ateş (°C)": ui.column_config.NumberColumn("Ateş (°C)", min_value=0.0, max_value=500.0, step=0.1, format="%.1f", help="Örn: 36.6 veya 366"),
			"Nabız (/dk)": ui.column_config.NumberColumn("Nabız (/dk)", min_value=0, max_value=300, step=1, format="%d"),
			"SpO2 (%)": ui.column_config.NumberColumn("SpO2 (%)", min_value=0, max_value=100, step=1, format="%d"),
			"Gözlük": ui.column_config.SelectboxColumn("Gözlük", options=glasses_opts, required=False),
			"Sağ Göz": ui.column_config.TextColumn("Sağ Göz", width="small"),
			"Sol Göz": ui.column_config.TextColumn("Sol Göz", width="small"),
			"Saç / Hijyen": ui.column_config.SelectboxColumn("Saç / Hijyen", options=hair_opts, required=False),
			"Sağ Kulak": ui.column_config.SelectboxColumn("Sağ Kulak", options=hearing_r_opts, required=False),
			"Sol Kulak": ui.column_config.SelectboxColumn("Sol Kulak", options=hearing_l_opts, required=False),
			"Sağlık Davranışı": ui.column_config.SelectboxColumn("Sağlık Davranışı", options=behavior_opts, required=False),
			"Psikososyal Durum": ui.column_config.TextColumn("Psikososyal Durum", width="medium"),
			"Tarama Notu": ui.column_config.TextColumn("Tarama Notu", width="medium"),
		},
	)

	save_unchanged_opt = ui.checkbox(
		"Önceki tarihlerden hazır gelen ve değiştirilmeyen dolu satırları da seçili tarih için yeniden tarama olarak kaydet",
		value=False,
		key=f"chk_bulk_scr_save_unchanged_{key_ctx}",
	)

	if ui.button("💾 Tüm Sınıfın Taramasını Tek Seferde Kaydet", type="primary", use_container_width=True, key=f"btn_bulk_scr_save_{key_ctx}"):
		res_bulk = save_bulk_class_screening_rows(
			edited_df,
			target_date_iso,
			baseline_df=base_df,
			save_unchanged=bool(save_unchanged_opt),
		)
		if res_bulk["saved_count"] > 0:
			fresh_df, fresh_exact = _build_bulk_class_screening_df(chosen_cls, target_date_iso)
			ui.session_state[base_df_key] = fresh_df.copy()
			ui.session_state[work_df_key] = fresh_df.copy()
			ui.session_state[exact_ids_key] = fresh_exact
			ui.session_state[seed_key] = editor_seed + 1
			ui.session_state[flash_key] = (
				"success",
				f"✅ **{chosen_cls}** sınıfı ({target_date_iso}) için **{res_bulk['saved_count']}** öğrencinin tarama, ölçüm (VKİ/persantil) ve vital verileri kaydedildi! "
				f"(Değişmeyen atlanan: {res_bulk['skipped_unchanged']}, boş atlanan: {res_bulk['skipped_empty']})",
			)
			ui.rerun()
		else:
			ui.warning(
				f"⚠️ Kaydedilecek yeni veya güncellenmiş veri bulunamadı (Değişmeyen: {res_bulk['skipped_unchanged']}, Boş: {res_bulk['skipped_empty']}). Hücrelerden birini düzenleyin veya Otomatik Doldur butonunu kullanın."
			)


def render_school_screening() -> None:
	visible_fields = get_screening_visible_fields()
	all_classes = [c for c in get_classes() if c != "Sivil / Diğer"]

	selected_class = ui.session_state.get("selected_screening_class")

	# Overall statistics
	with connect_db() as connection:
		all_students_cnt = connection.execute("SELECT COUNT(*) FROM students WHERE class_id IN (SELECT id FROM classes WHERE name != 'Sivil / Diğer')").fetchone()[0]
		all_screened_cnt = connection.execute(
			"""SELECT COUNT(DISTINCT s.id) FROM students s
			   JOIN classes c ON c.id = s.class_id
			   LEFT JOIN health_profiles h ON h.student_id = s.id
			   WHERE c.name != 'Sivil / Diğer' AND (h.last_screened_at IS NOT NULL OR EXISTS (SELECT 1 FROM school_screenings sc WHERE sc.student_id = s.id))"""
		).fetchone()[0]

	pct_overall = round((all_screened_cnt / all_students_cnt * 100), 1) if all_students_cnt > 0 else 0

	# Top action & summary banner
	if is_section_visible("screening_stats"):
		ban_c1, ban_c2, ban_c3, ban_c4 = ui.columns([2.5, 1, 1, 1])
		with ban_c1:
			ui.markdown("### 🏫 Okul Sağlık Taraması Paneli")
			ui.caption("Sınıf kutucuklarına tıklayarak sınıf içi taramaları yürütün; boy, kilo, vital, görme, işitme ve hijyen bulgularını tek ekranda güncelleyin.")
		with ban_c2:
			ui.metric("Toplam Sınıf", len(all_classes))
		with ban_c3:
			ui.metric("Taranan / Toplam", f"{all_screened_cnt} / {all_students_cnt}")
		with ban_c4:
			ui.metric("Tarama Oranı", f"%{pct_overall}")
		ui.markdown("---")
	else:
		ui.markdown("### 🏫 Okul Sağlık Taraması Paneli")

	# VIEW 1: Sınıf Kutucukları Listesi (Grid of Class Boxes)
	if not selected_class or selected_class not in all_classes:
		tab_cls_cards, tab_bulk_top = ui.tabs([
			"🗂️ Sınıf Kartları & Tekil Tarama",
			"⚡ Seri Sınıf Taraması (Toplu Tablo Girişi)",
		])
		with tab_cls_cards:
			vis_names = [SCREENING_FIELDS_INFO[f]["name"] for f in visible_fields if f in SCREENING_FIELDS_INFO]
			scr_top_c1, scr_top_c2, scr_top_c3 = ui.columns([2.4, 1.4, 1.6], vertical_alignment="center")
			with scr_top_c1:
				ui.caption(f"⚙️ **Aktif Tarama Alanları ({len(vis_names)}):** {', '.join(vis_names[:6])}{'…' if len(vis_names) > 6 else ''} · *(Ayarlar > Görünürlük & Rapor)*")
			with scr_top_c2:
				only_incomp_cls = ui.toggle("⏳ Sadece Eksik Sınıflar", value=False, key="scr_only_incomplete_classes")
			with scr_top_c3:
				if ui.button("⚙️ Rapor İçeriği & Sütun Ayarları (Pop-up)", type="primary", use_container_width=True, key="btn_scr_all_open_report_builder"):
					_trigger_open_report_builder("🏫 Okul Taraması", default_classes=None)
			if ui.toggle("📊 Tarih Seçimli Toplu Tarama & Persantil Raporu Panelini Aç", value=False, key="scr_all_show_inline_rep"):
				with ui.container(border=True):
					_render_screening_report_workspace(
						owner_page="🏫 Okul Taraması",
						key_prefix="scr_all_rep",
						fixed_classes=None,
						compact=True,
						show_config_button=False,
					)

			tch_map = get_class_teacher_map()
			cls_to_render = [c_n for c_n in all_classes if (not only_incomp_cls or not get_class_screening_stats(c_n)["is_complete"])]
			if not cls_to_render:
				ui.success("🎉 Tüm sınıfların sağlık taraması %100 tamamlandı!")
			# Render class cards in 3 columns
			grid_cols = ui.columns(3)
			for idx, c_name in enumerate(cls_to_render):
				stats = get_class_screening_stats(c_name)
				tch_name = tch_map.get(c_name, "")
				col = grid_cols[idx % 3]
				with col:
					with ui.container(border=True):
						tch_badge = f"<div style='margin-top:2px;'><span style='background:#f0fdf4; color:#166534; padding:2px 8px; border-radius:12px; font-size:12px; font-weight:600;'>👩‍🏫 {html.escape(tch_name)}</span></div>" if tch_name else ""
						ui.markdown(f"<div style='margin-bottom:6px;'><span style='font-size:17.5px; font-weight:800; color:var(--teal);'>🏫 {html.escape(c_name)}</span>{tch_badge}</div>", unsafe_allow_html=True)
						c_stat1, c_stat2 = ui.columns(2)
						c_stat1.markdown(f"👥 **Mevcut:** {stats['total']}")
						c_stat2.markdown(f"🩺 **Taranan:** {stats['screened']}")

						pct = stats["percent"]
						ui.progress(pct / 100.0)

						if stats["is_complete"]:
							ui.markdown("<span style='background:#dcfce7;color:#15803d;padding:2px 8px;border-radius:6px;font-size:12px;font-weight:600;'>🟢 %100 Tamamlandı</span>", unsafe_allow_html=True)
						elif stats["screened"] > 0:
							ui.markdown(f"<span style='background:#fef3c7;color:#b45309;padding:2px 8px;border-radius:6px;font-size:12px;font-weight:600;'>🟡 %{pct} Devam Ediyor ({stats['pending']} bekliyor)</span>", unsafe_allow_html=True)
						else:
							ui.markdown(f"<span style='background:#f1f5f9;color:#64748b;padding:2px 8px;border-radius:6px;font-size:12px;font-weight:600;'>⚪ Henüz Başlanmadı ({stats['total']} bekliyor)</span>", unsafe_allow_html=True)

						ui.write("")
						if ui.button(f"📋 Sınıfı Aç & Tara ➔", key=f"btn_sel_cls_{idx}_{c_name}", type="primary", use_container_width=True):
							ui.session_state["selected_screening_class"] = c_name
							ui.rerun()

			ui.markdown("---")
			render_screening_import_section()

		with tab_bulk_top:
			render_bulk_class_screening_tab(default_class=None, key_ctx="top")

	# VIEW 2: Seçili Sınıfın Tarama Paneli ve Öğrenci Listesi
	else:
		cur_cls_idx = all_classes.index(selected_class)
		prev_cls_name = all_classes[cur_cls_idx - 1] if cur_cls_idx > 0 else None
		next_cls_name = all_classes[cur_cls_idx + 1] if cur_cls_idx < len(all_classes) - 1 else None

		hdr_c1, hdr_c2, hdr_c3 = ui.columns([1.4, 3.8, 1.9])
		with hdr_c1:
			if ui.button("⬅️ Tüm Sınıflara Dön", key="btn_back_to_all_classes", use_container_width=True):
				_close_dyn_report_builder_dialog()
				ui.session_state["selected_screening_class"] = None
				ui.rerun()
		with hdr_c2:
			c_stats = get_class_screening_stats(selected_class)
			tch_map_sel = get_class_teacher_map()
			sel_tch = tch_map_sel.get(selected_class, "")
			sel_tch_txt = f" · 👩‍🏫 Öğretmen: **{html.escape(sel_tch)}**" if sel_tch else ""
			cls_nav_l, cls_nav_m, cls_nav_r = ui.columns([0.45, 3.4, 0.45])
			with cls_nav_l:
				if ui.button(
					"◀",
					key=f"btn_scr_prev_cls_{selected_class}",
					disabled=(prev_cls_name is None),
					help=f"Önceki Sınıf: {prev_cls_name}" if prev_cls_name else "İlk sınıftasınız",
					use_container_width=True,
				):
					_close_dyn_report_builder_dialog()
					ui.session_state["selected_screening_class"] = prev_cls_name
					ui.rerun()
			with cls_nav_m:
				ui.markdown(
					f"<div style='text-align:center;line-height:1.25;'>"
					f"<span style='font-size:20px;font-weight:800;color:var(--text-heading);'>🏫 {html.escape(selected_class)}</span> "
					f"<span style='font-size:13px;font-weight:700;color:var(--teal);background:var(--mint);padding:2px 8px;border-radius:999px;vertical-align:middle;'>{cur_cls_idx + 1} / {len(all_classes)}</span>"
					f"<div style='font-size:13px;color:var(--text-muted);margin-top:2px;'>Sağlık Taraması Paneli{sel_tch_txt.replace('**', '')}</div>"
					f"</div>",
					unsafe_allow_html=True,
				)
			with cls_nav_r:
				if ui.button(
					"▶",
					key=f"btn_scr_next_cls_{selected_class}",
					disabled=(next_cls_name is None),
					help=f"Sonraki Sınıf: {next_cls_name}" if next_cls_name else "Son sınıftasınız",
					use_container_width=True,
				):
					_close_dyn_report_builder_dialog()
					ui.session_state["selected_screening_class"] = next_cls_name
					ui.rerun()
			ui.caption(f"Sınıf Mevcudu: **{c_stats['total']}** · Taranan: **{c_stats['screened']}** · Bekleyen: **{c_stats['pending']}** · Başarı: **%{c_stats['percent']}**")
		with hdr_c3:
			if ui.button("⚙️ Rapor İçeriği & Sütun Ayarları (Pop-up)", type="primary", use_container_width=True, key=f"btn_scr_cls_open_report_builder_{selected_class}"):
				_trigger_open_report_builder("🏫 Okul Taraması", default_classes=[selected_class])
			ui.download_button(
				"📝 Hızlı Sınıf Tarama Formu (.docx)",
				data=lambda _sc=selected_class: build_class_screening_report_docx(_sc),
				file_name=f"sinif_saglik_taramasi_{selected_class}_{date.today().isoformat()}.docx",
				mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
				type="secondary",
				key=f"dl_class_scr_rep_{selected_class}",
				use_container_width=True,
			)

		ui.progress(c_stats["percent"] / 100.0)
		if ui.toggle(f"📊 {selected_class} Tarih Seçimli Rapor Önizleme & Çıktı Al (.docx / .xlsx / .html)", value=False, key=f"scr_cls_show_inline_rep_{selected_class}"):
			with ui.container(border=True):
				_render_screening_report_workspace(
					owner_page="🏫 Okul Taraması",
					key_prefix=f"scr_cls_rep_{selected_class}",
					fixed_classes=[selected_class],
					compact=True,
					show_config_button=False,
				)

		tab_stu_cards, tab_bulk_cls = ui.tabs([
			"👥 Öğrenci Listesi & Tekil Tarama",
			"⚡ Seri Sınıf Taraması (Toplu Tablo Girişi)",
		])

		with tab_stu_cards:
			# Fetch students for this class
			with connect_db() as connection:
				stu_rows = connection.execute(
					"""SELECT s.id, s.student_no, s.full_name, s.sex, s.birth_date,
							  h.last_screened_at, h.wears_glasses, h.vision_right, h.vision_left,
							  h.hair_screening, h.hearing_right, h.hearing_left, h.health_behavior,
							  h.harmful_habits, h.psychosocial_status
					   FROM students s
					   JOIN classes c ON c.id = s.class_id
					   LEFT JOIN health_profiles h ON h.student_id = s.id
					   WHERE c.name = ?
					   ORDER BY s.student_no, s.full_name""",
					(selected_class,),
				).fetchall()

			if not stu_rows:
				ui.warning(f"{selected_class} sınıfında henüz kayıtlı öğrenci bulunmuyor.")
			else:
				# Filters toolbar
				filt_c1, filt_c2, filt_c3 = ui.columns([2.2, 1.4, 1.2], vertical_alignment="center")
				with filt_c1:
					search_kw = ui.text_input("🔍 Öğrenci Ara (İsim veya Okul No)", placeholder="Aramak için yazın...", key=f"scr_search_{selected_class}")
				with filt_c2:
					status_filt = ui.selectbox("Durum Filtresi", ["Tümü", "⏳ Taranmamış / Bekleyenler", "🟢 Taranmış Olanlar"], key=f"scr_filt_{selected_class}")

				# Filter student list
				filtered_students = []
				for s in stu_rows:
					is_screened = bool(s["last_screened_at"])
					if status_filt == "⏳ Taranmamış / Bekleyenler" and is_screened:
						continue
					if status_filt == "🟢 Taranmış Olanlar" and not is_screened:
						continue
					if search_kw.strip():
						kw = search_kw.strip().lower()
						matches_name = kw in str(s["full_name"]).lower()
						matches_no = kw in str(s["student_no"] or "").lower()
						if not (matches_name or matches_no):
							continue
					filtered_students.append(s)

				with filt_c3:
					def _make_cls_scr_xlsx(_srows=list(filtered_students), _cls=selected_class):
						_out_r = []
						for _sr in _srows:
							_sid = int(_sr["id"])
							_lsc = get_student_latest_screening(_sid)
							_mi = get_person_latest_measurements(_sid)
							_out_r.append({
								"Sınıf": _cls,
								"Okul No": _sr["student_no"] or "",
								"Ad Soyad": _sr["full_name"],
								"Durum": "Taranmış" if (_sr["last_screened_at"] or _lsc.get("screening_date")) else "Bekliyor",
								"Boy (cm)": _lsc.get("height_cm") or _mi["height_cm"] or "",
								"Kilo (kg)": _lsc.get("weight_kg") or _mi["weight_kg"] or "",
								"VKİ": _mi["bmi"] or "",
								"Sağ Göz": _lsc.get("vision_right") or _sr["vision_right"] or "",
								"Sol Göz": _lsc.get("vision_left") or _sr["vision_left"] or "",
								"Saç/Hijyen": _lsc.get("hair_screening") or _sr["hair_screening"] or "",
							})
						_b = io.BytesIO()
						with pd.ExcelWriter(_b, engine="openpyxl") as _w:
							pd.DataFrame(_out_r).to_excel(_w, index=False, sheet_name="Sinif_Taramasi")
						return _b.getvalue()
					ui.write("")
					ui.download_button(
						"📥 Excel İndir",
						data=_make_cls_scr_xlsx,
						file_name=f"Tarama_{selected_class}_{date.today().isoformat()}.xlsx",
						mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
						key=f"btn_dl_scr_cls_xlsx_{selected_class}",
						use_container_width=True,
					)

				ui.caption(f"Listelenen: **{len(filtered_students)}** / {len(stu_rows)} öğrenci · Sağdaki butonla tarama penceresini açabilirsiniz.")

				# Render each student card
				for s in filtered_students:
					s_id = int(s["id"])
					latest_scr = get_student_latest_screening(s_id)
					m_info = get_person_latest_measurements(s_id)
					s_age_m = age_in_months(s["birth_date"], date.today()) if s["birth_date"] else None
					s_age_str = f"{s_age_m // 12}y {s_age_m % 12}a" if s_age_m is not None else "Doğum tarihi yok"
					s_sex_ico = "♀ Kız" if s["sex"] == "K" else ("♂ Erkek" if s["sex"] == "E" else "—")
					sno_txt = f"No: {s['student_no']} · " if s["student_no"] else ""
					is_done = bool(s["last_screened_at"] or latest_scr.get("screening_date"))

					with ui.container(border=True):
						row_l, row_r = ui.columns([3.2, 1.8])
						with row_l:
							st_badge = "<span style='background:#dcfce7;color:#15803d;padding:2px 7px;border-radius:5px;font-size:12px;font-weight:600;'>🟢 Taranmış</span>" if is_done else "<span style='background:#fee2e2;color:#b91c1c;padding:2px 7px;border-radius:5px;font-size:12px;font-weight:600;'>⏳ Bekliyor</span>"
							ui.markdown(f"**👤 {html.escape(mask_kvkk_value(s['full_name'], 'name'))}** &nbsp; {st_badge}", unsafe_allow_html=True)
							ui.caption(f"{sno_txt}{s_sex_ico} · Doğum: {s['birth_date'] or '—'} ({s_age_str}) &nbsp;·&nbsp; Son Tarama: **{latest_scr.get('screening_date') or s['last_screened_at'] or 'Yapılmadı'}**")

							preview_chips = []
							if "height_cm" in visible_fields or "weight_kg" in visible_fields:
								h_v = latest_scr.get("height_cm") or m_info["height_cm"]
								w_v = latest_scr.get("weight_kg") or m_info["weight_kg"]
								bmi_v = m_info["bmi"]
								hw_parts = []
								if "height_cm" in visible_fields and h_v: hw_parts.append(f"{h_v:.1f} cm")
								if "weight_kg" in visible_fields and w_v: hw_parts.append(f"{w_v:.1f} kg")
								if bmi_v: hw_parts.append(f"VKİ: {bmi_v:.1f}")
								if hw_parts:
									preview_chips.append(f"📏 {' / '.join(hw_parts)}")

							if "head_circ_cm" in visible_fields:
								hc_v = latest_scr.get("head_circ_cm") or m_info["head_circ_cm"]
								if hc_v: preview_chips.append(f"👶 Baş Çevresi: {hc_v:.1f} cm")

							if any(f in visible_fields for f in ("temperature_c", "pulse_bpm", "spo2_pct")):
								vit_parts = []
								if "temperature_c" in visible_fields and latest_scr.get("temperature_c"):
									vit_parts.append(f"🌡️ {latest_scr['temperature_c']:.1f}°C")
								if "pulse_bpm" in visible_fields and latest_scr.get("pulse_bpm"):
									vit_parts.append(f"💓 {latest_scr['pulse_bpm']:.0f}/dk")
								if "spo2_pct" in visible_fields and latest_scr.get("spo2_pct"):
									vit_parts.append(f"🫁 %{latest_scr['spo2_pct']:.0f}")
								if vit_parts:
									preview_chips.append(" · ".join(vit_parts))

							if any(f in visible_fields for f in ("wears_glasses", "vision_right", "vision_left")):
								gl_txt = latest_scr.get("wears_glasses") or s["wears_glasses"]
								vr_txt = latest_scr.get("vision_right") or s["vision_right"]
								vl_txt = latest_scr.get("vision_left") or s["vision_left"]
								vis_parts = []
								if "wears_glasses" in visible_fields and gl_txt: vis_parts.append(f"Gözlük: {gl_txt}")
								if "vision_right" in visible_fields and vr_txt: vis_parts.append(f"Sağ: {vr_txt}")
								if "vision_left" in visible_fields and vl_txt: vis_parts.append(f"Sol: {vl_txt}")
								if vis_parts:
									preview_chips.append(f"👓 {' · '.join(vis_parts)}")

							if "hair_screening" in visible_fields:
								hr_txt = latest_scr.get("hair_screening") or s["hair_screening"]
								if hr_txt: preview_chips.append(f"💇 Saç: {hr_txt}")

							if any(f in visible_fields for f in ("hearing_right", "hearing_left")):
								hear_r = latest_scr.get("hearing_right") or s["hearing_right"]
								hear_l = latest_scr.get("hearing_left") or s["hearing_left"]
								if hear_r or hear_l:
									preview_chips.append(f"👂 Kulak: Sağ: {hear_r or '—'} · Sol: {hear_l or '—'}")

							if "health_behavior" in visible_fields:
								beh_txt = latest_scr.get("health_behavior") or s["health_behavior"]
								if beh_txt: preview_chips.append(f"🍎 {beh_txt}")

							if "harmful_habits" in visible_fields:
								harm_txt = latest_scr.get("harmful_habits") or s["harmful_habits"]
								if harm_txt: preview_chips.append(f"⚠️ {harm_txt}")

							if "psychosocial_status" in visible_fields:
								psy_txt = latest_scr.get("psychosocial_status") or s["psychosocial_status"]
								if psy_txt: preview_chips.append(f"🧠 {psy_txt}")

							if preview_chips:
								chip_html = "".join([f"<span style='background:#f1f5f9;color:#334155;border:1px solid #cbd5e1;padding:2px 7px;border-radius:4px;font-size:11px;margin-right:6px;display:inline-block;margin-top:4px;'>{html.escape(c)}</span>" for c in preview_chips])
								ui.markdown(chip_html, unsafe_allow_html=True)
							else:
								ui.caption("Tarama verisi henüz girilmedi.")

						with row_r:
							ui.write("")
							if ui.button("🩺 Taramayı Gir / Düzenle ✏️", key=f"btn_open_scr_dialog_{s_id}", type="primary", use_container_width=True):
								_close_dyn_report_builder_dialog()
								open_screening_dialog(s_id, selected_class)
							if ui.button("📂 Kişi Dosyası", key=f"btn_open_dossier_from_scr_{s_id}", use_container_width=True):
								_close_dyn_report_builder_dialog()
								open_person_dossier_dialog(s_id)

				ui.markdown("---")
				with ui.expander(f"📥 {selected_class} İçin Toplu Tarama Verisi İçe Aktar (Excel / Word / CSV / Resim-OCR)", expanded=False):
					render_screening_import_section(target_class=selected_class)

		with tab_bulk_cls:
			render_bulk_class_screening_tab(default_class=selected_class, key_ctx=f"cls_{selected_class}")

	scr_flash = ui.session_state.pop("_scr_flash_msg", None)
	if scr_flash:
		ui.success(scr_flash)

	pend_next_scr = ui.session_state.pop("_pending_next_screening", None)
	if isinstance(pend_next_scr, tuple) and len(pend_next_scr) == 2:
		open_screening_dialog(int(pend_next_scr[0]), pend_next_scr[1])

	dlg_state_scr = ui.session_state.get("_dyn_rep_dialog_open")
	if isinstance(dlg_state_scr, dict) and dlg_state_scr.get("owner_page") == "🏫 Okul Taraması":
		open_report_config_dialog(
			default_classes=dlg_state_scr.get("default_classes"),
			default_dates=dlg_state_scr.get("default_dates"),
		)


# ==============================================================================
# RAPOR ÇIKTI VE YAZDIRMA AYARLARI (POP-UP MODAL & ÖZELLEŞTİRME)
# ==============================================================================

DEFAULT_REPORT_SETTINGS: dict[str, Any] = {
	# Bölüm Görünürlükleri
	"include_id_box": True,                # 👤 Kimlik & Temel Bilgiler
	"include_alert_box": True,             # ⚠️ Kritik Sağlık & Alerji Uyarı Kutusu
	"include_health_profile": True,        # 📋 Sağlık Profili & Aile Bilgisi
	"include_growth_summary": True,        # 📏 DSÖ Klinik Büyüme & Persantil Değerlendirmesi
	"include_vitals": True,                # 💓 Vital Bulgular (Tansiyon, Ateş, Nabız, SpO2)
	"include_lab_results": True,           # 🧪 Laboratuvar Tahlil Sonuçları
	"include_measurements_history": True,  # ⚖️ Boy, Kilo ve Baş Çevresi Ölçüm Geçmişi
	"include_visits": True,                # 🩺 Revir Başvuru ve Muayene Kayıtları
	"include_care_plans": True,            # 📝 Hemşirelik Bakım Planları (NANDA-I)
	"include_vaccinations": True,          # 💉 Aşı ve Bağışıklama Kayıtları
	"include_disability_profile": True,    # ♿ Engellilik / Özel Gereksinim Profili (Sadece engeli varsa)
	"include_ai_analysis": False,          # 🤖 Gemini AI Değerlendirme & Eksik Veri Bölümü
	"include_signatures": True,            # ✍️ Yetkili ve Veli İmza Bölümü
	"include_footer_disclaimer": True,     # ℹ️ Yasal Bilgilendirme Dipnotu

	# Detay Alan Tercihleri
	"show_guardian_contact": True,         # Veli adı ve telefon bilgisi
	"show_blood_group": True,              # Kan grubu
	"show_visit_complaint": True,          # Vizit şikayet / başvuru nedeni
	"show_visit_action": True,             # Yapılan işlem / müdahale
	"show_visit_observation": True,        # Fizik muayene ve klinik gözlem
	"show_visit_referral": True,           # Sevk / hastane durumu
	"show_meas_zscores": True,             # Persantil Z-skorları (SDS)
	"show_meas_percentiles": True,         # Yüzdelik persantil dilimleri (%p)
	"visits_limit": 0,                     # 0 = Tümü, veya 5, 10, 15, 20, 30
}


def get_report_settings() -> dict[str, Any]:
	cfg = get_app_settings()
	raw = cfg.get("report_custom_settings", "")
	res = dict(DEFAULT_REPORT_SETTINGS)
	if raw and str(raw).strip():
		try:
			import json as _json
			parsed = _json.loads(raw)
			if isinstance(parsed, dict):
				for k, v in parsed.items():
					if k in res:
						res[k] = v
		except Exception:
			pass
	return res


def save_report_settings(new_settings: dict[str, Any]) -> None:
	import json as _json
	cur = get_report_settings()
	cur.update(new_settings)
	save_app_settings({"report_custom_settings": _json.dumps(cur, ensure_ascii=False)})


def render_report_settings_panel(*, key_prefix: str = "rep", in_dialog: bool = False) -> None:
	"""Kişi ve sınıf raporu çıktılarının bölüm ve detay tercihlerini yönetir (diyalog + Merkezi Ayarlar ortak panel)."""
	kp = str(key_prefix or "rep").strip() or "rep"
	ui.markdown("### 🖨️ Rapor Çıktı & Yazdırma Ayarları")
	ui.caption("Kişi ve sınıf raporu çıktılarında (Word `.docx` ve yazdırma) yer alacak bölümleri ve detay tercihlerini özelleştirin.")
	cur_cfg = get_report_settings()

	tab_sections, tab_fields, tab_presets = ui.tabs([
		"📑 Rapor Bölümleri",
		"🔍 Detay Alanları",
		"⚡ Hızlı Şablonlar"
	], orientation="segmented")

	def _after_save(msg: str) -> None:
		ui.success(msg)
		if in_dialog:
			ui.rerun(scope="fragment")
		else:
			ui.rerun()

	with tab_presets:
		ui.markdown("##### ⚡ Hazır Rapor Şablonları")
		ui.caption("Tek tıkla ihtiyacınıza uygun bir rapor şablonu seçebilirsiniz:")
		pr_c1, pr_c2 = ui.columns(2)
		with pr_c1:
			if ui.button("✅ Tam Kapsamlı Resmi Sağlık Raporu", use_container_width=True, help="Tüm bölümler ve geçmiş kayıtlar eksiksiz dahil edilir.", key=f"{kp}_preset_full"):
				save_report_settings(dict(DEFAULT_REPORT_SETTINGS))
				_after_save("Tam kapsamlı resmi rapor şablonu uygulandı!")
			if ui.button("🩺 Yalnızca Revir & Muayene Raporu", use_container_width=True, help="Sadece kimlik, uyarılar ve revir vizit geçmişi dahil edilir.", key=f"{kp}_preset_visits"):
				custom_s = dict(DEFAULT_REPORT_SETTINGS)
				custom_s.update({
					"include_health_profile": False,
					"include_growth_summary": False,
					"include_lab_results": False,
					"include_measurements_history": False,
					"include_care_plans": False,
					"include_vaccinations": False,
				})
				save_report_settings(custom_s)
				_after_save("Yalnızca revir muayene raporu şablonu uygulandı!")
		with pr_c2:
			if ui.button("📏 Yalnızca Büyüme & Persantil Raporu", use_container_width=True, help="DSÖ büyüme eğrileri, boy-kilo geçmişi ve persantil değerlendirmesi.", key=f"{kp}_preset_growth"):
				custom_s = dict(DEFAULT_REPORT_SETTINGS)
				custom_s.update({
					"include_visits": False,
					"include_care_plans": False,
					"include_lab_results": False,
					"include_vaccinations": False,
				})
				save_report_settings(custom_s)
				_after_save("Büyüme ve persantil raporu şablonu uygulandı!")
			if ui.button("📋 Özet Sağlık Künyesi (Vizitsiz Form)", use_container_width=True, help="Alerji, kronik durum, acil notu ve vital özetinden oluşan tek sayfalık form.", key=f"{kp}_preset_summary"):
				custom_s = dict(DEFAULT_REPORT_SETTINGS)
				custom_s.update({
					"include_visits": False,
					"include_care_plans": False,
					"include_measurements_history": False,
					"include_lab_results": False,
				})
				save_report_settings(custom_s)
				_after_save("Özet sağlık künyesi şablonu uygulandı!")

	with tab_sections:
		ui.markdown("##### 📑 Rapora Dahil Edilecek Ana Bölümler")
		ui.caption("Rapor çıktısında yer almasını istemediğiniz bölümlerin işaretini kaldırabilirsiniz:")
		sec_c1, sec_c2 = ui.columns(2)
		with sec_c1:
			chk_id = ui.checkbox("👤 Öğrenci Kimlik ve Temel Bilgileri", value=cur_cfg.get("include_id_box", True), key=f"{kp}_chk_id")
			chk_alert = ui.checkbox("⚠️ Kritik Sağlık & Alerji Uyarı Kutusu", value=cur_cfg.get("include_alert_box", True), key=f"{kp}_chk_alert")
			chk_hp = ui.checkbox("📋 Sağlık Profili & Tarama Bilgileri", value=cur_cfg.get("include_health_profile", True), key=f"{kp}_chk_hp")
			chk_growth = ui.checkbox("📏 DSÖ Klinik Büyüme & Persantil Taraması", value=cur_cfg.get("include_growth_summary", True), key=f"{kp}_chk_growth")
			chk_vitals = ui.checkbox("💓 Vital Bulgular Ölçüm Geçmişi", value=cur_cfg.get("include_vitals", True), key=f"{kp}_chk_vitals")
			chk_labs = ui.checkbox("🧪 Laboratuvar Tahlil Sonuçları", value=cur_cfg.get("include_lab_results", True), key=f"{kp}_chk_labs")
		with sec_c2:
			chk_meas = ui.checkbox("⚖️ Boy, Kilo ve Baş Çevresi Ölçüm Geçmişi", value=cur_cfg.get("include_measurements_history", True), key=f"{kp}_chk_meas")
			chk_visits = ui.checkbox("🩺 Revir Başvuru ve Muayene Kayıtları", value=cur_cfg.get("include_visits", True), key=f"{kp}_chk_visits")
			chk_cp = ui.checkbox("📝 Hemşirelik Bakım Planları (NANDA-I)", value=cur_cfg.get("include_care_plans", True), key=f"{kp}_chk_cp")
			chk_vac = ui.checkbox("💉 Aşı ve Bağışıklama Kayıtları", value=cur_cfg.get("include_vaccinations", True), key=f"{kp}_chk_vac")
			chk_dis = ui.checkbox("♿ Engellilik / Özel Gereksinim Profili (Varsa)", value=cur_cfg.get("include_disability_profile", True), key=f"{kp}_chk_dis")
			chk_ai = ui.checkbox("🤖 AI Klinik Analiz & Eksik Veri Bölümü (Varsayılan)", value=cur_cfg.get("include_ai_analysis", False), key=f"{kp}_chk_ai")
			chk_sig = ui.checkbox("✍️ Yetkili ve Veli İmza / Kaşe Bölümü", value=cur_cfg.get("include_signatures", True), key=f"{kp}_chk_sig")
			chk_foot = ui.checkbox("ℹ️ Yasal Sorumluluk Reddi / Dipnot", value=cur_cfg.get("include_footer_disclaimer", True), key=f"{kp}_chk_foot")

	with tab_fields:
		ui.markdown("##### 🔍 Detay Bilgi ve Filtre Tercihleri")
		fld_c1, fld_c2 = ui.columns(2)
		with fld_c1:
			chk_guard = ui.checkbox("📞 Veli Adı ve Telefon Bilgisini Göster", value=cur_cfg.get("show_guardian_contact", True), key=f"{kp}_chk_guard")
			chk_bg = ui.checkbox("🩸 Kan Grubu Bilgisini Göster", value=cur_cfg.get("show_blood_group", True), key=f"{kp}_chk_bg")
			chk_sym = ui.checkbox("🩺 Vizit Kayıtlarında Şikayet / Belirtileri Göster", value=cur_cfg.get("show_visit_complaint", True), key=f"{kp}_chk_sym")
			chk_act = ui.checkbox("🛠️ Vizit Kayıtlarında Yapılan İşlemi Göster", value=cur_cfg.get("show_visit_action", True), key=f"{kp}_chk_act")
		with fld_c2:
			chk_obs = ui.checkbox("🔍 Vizit Kayıtlarında Fizik Muayene / Gözlemi Göster", value=cur_cfg.get("show_visit_observation", True), key=f"{kp}_chk_obs")
			chk_ref = ui.checkbox("🚑 Sevk ve Yönlendirme Durumunu Göster", value=cur_cfg.get("show_visit_referral", True), key=f"{kp}_chk_ref")
			chk_z = ui.checkbox("📊 Ölçümlerde DSÖ Z-Skorlarını (SDS) Göster", value=cur_cfg.get("show_meas_zscores", True), key=f"{kp}_chk_z")
			chk_p = ui.checkbox("📈 Ölçümlerde Persantil Dilimlerini (%p) Göster", value=cur_cfg.get("show_meas_percentiles", True), key=f"{kp}_chk_p")

		ui.markdown("---")
		ui.markdown("###### 🕒 Vizit Kayıt Limiti")
		limit_opts = [0, 5, 10, 15, 20, 30]
		cur_lim = cur_cfg.get("visits_limit", 0)
		lim_idx = limit_opts.index(cur_lim) if cur_lim in limit_opts else 0
		sel_limit = ui.selectbox(
			"Raporda listelenecek maksimum vizit sayısı",
			limit_opts,
			index=lim_idx,
			format_func=lambda x: "Tüm Geçmiş Vizitler (Limitsiz)" if x == 0 else f"Son {x} Vizit Kaydı",
			key=f"{kp}_sel_visits_limit"
		)

	ui.markdown("---")
	if ui.button("💾 Rapor Çıktı Ayarlarını Kaydet", type="primary", use_container_width=True, key=f"btn_save_report_settings_{kp}"):
		new_saved = {
			"include_id_box": chk_id,
			"include_alert_box": chk_alert,
			"include_health_profile": chk_hp,
			"include_growth_summary": chk_growth,
			"include_vitals": chk_vitals,
			"include_lab_results": chk_labs,
			"include_measurements_history": chk_meas,
			"include_visits": chk_visits,
			"include_care_plans": chk_cp,
			"include_vaccinations": chk_vac,
			"include_disability_profile": chk_dis,
			"include_ai_analysis": chk_ai,
			"include_signatures": chk_sig,
			"include_footer_disclaimer": chk_foot,
			"show_guardian_contact": chk_guard,
			"show_blood_group": chk_bg,
			"show_visit_complaint": chk_sym,
			"show_visit_action": chk_act,
			"show_visit_observation": chk_obs,
			"show_visit_referral": chk_ref,
			"show_meas_zscores": chk_z,
			"show_meas_percentiles": chk_p,
			"visits_limit": sel_limit,
		}
		save_report_settings(new_saved)
		_after_save("Rapor çıktı ayarları başarıyla kaydedildi!")


@ui.dialog("⚙️ Rapor Çıktı ve Yazdırma Ayarları", width="large", mode="drawer")
def open_report_settings_dialog() -> None:
	render_report_settings_panel(key_prefix="rep", in_dialog=True)


