@ui.dialog("👁️ Evrak / Belge Önizleme", width="large")
def open_document_preview_dialog(file_path: Path) -> None:
	if not file_path.exists():
		ui.error("Dosya bulunamadı.")
		return

	ext = file_path.suffix.lower()
	stat = file_path.stat()
	f_size_str = format_file_size(stat.st_size)
	f_date_str = datetime.fromtimestamp(stat.st_mtime).strftime("%d.%m.%Y %H:%M")
	is_editable_doc = ext in (".pdf", ".docx", ".xlsx", ".txt", ".csv")
	is_gai_on, gai_key, gai_model = _get_active_gemini_config()

	h_c1, h_c2 = ui.columns([6.0, 4.0])
	with h_c1:
		ui.markdown(f"#### 📄 {file_path.name}")
		ui.caption(f"📏 Boyut: **{f_size_str}** · 🕒 Tarih: **{f_date_str}** · 🏷️ Tür: **{ext.upper().strip('.')}**")
	with h_c2:
		mime_t = mimetypes.guess_type(file_path)[0] or "application/octet-stream"
		if is_editable_doc:
			hb1, hb2 = ui.columns(2)
			with hb1:
				ed_lbl = "✍️ PDF Form Doldur" if ext == ".pdf" else "🛠️ Belgeyi Düzenle"
				if ui.button(ed_lbl, type="primary", use_container_width=True, key=f"prev_open_studio_{sha256(file_path.name.encode()).hexdigest()[:8]}"):
					open_document_studio_dialog(file_path)
			with hb2:
				ui.download_button("📥 İndir", data=lambda _p=file_path: _p.read_bytes(), file_name=file_path.name, mime=mime_t, type="secondary", use_container_width=True, key=f"prev_dl_btn_{sha256(file_path.name.encode()).hexdigest()[:8]}")
		else:
			ui.download_button("📥 Bilgisayara İndir", data=lambda _p=file_path: _p.read_bytes(), file_name=file_path.name, mime=mime_t, type="primary", use_container_width=True, key=f"prev_dl_btn_{sha256(file_path.name.encode()).hexdigest()[:8]}")

	ui.divider()
	if is_gai_on and ext in (".pdf", ".png", ".jpg", ".jpeg", ".webp", ".txt", ".csv", ".docx", ".xlsx"):
		doc_sum_key = f"gai_doc_sum_{file_path.name}"
		ga_b1, ga_b2 = ui.columns([1.2, 1.0])
		with ga_b1:
			sum_clicked = ui.button("✨ Gemini AI ile Bu Belgeyi Özetle", key=f"btn_gai_doc_sum_{file_path.name}", use_container_width=True)
		with ga_b2:
			if ui.button("👤 Belgeyi Oku & Öğrenciye İşle", type="secondary", key=f"btn_gai_doc_imp_{file_path.name}", use_container_width=True):
				open_smart_document_importer_dialog(initial_file_path=file_path)
		if sum_clicked:
			ext_txt = ""
			if ext == ".pdf":
				try:
					ext_txt = extract_pdf_text(file_path.read_bytes())
				except Exception:
					ext_txt = ""
			elif ext in (".txt", ".csv"):
				try:
					ext_txt = file_path.read_text(encoding="utf-8", errors="replace")
				except Exception:
					ext_txt = ""
			elif ext == ".docx":
				try:
					if _ensure_docx_loaded() and docx is not None:
						_dd = docx.Document(file_path)
						parts_dx = [p.text.strip() for p in _dd.paragraphs if p.text.strip()]
						for _tbl in _dd.tables[:8]:
							for _row in _tbl.rows[:40]:
								r_cells = [c.text.strip() for c in _row.cells if c.text.strip()]
								if r_cells:
									parts_dx.append(" | ".join(r_cells))
						ext_txt = "\n".join(parts_dx)[:12000]
				except Exception:
					ext_txt = ""
			elif ext in (".xlsx", ".xls"):
				try:
					if _ensure_openpyxl_loaded():
						import openpyxl
						_wb = openpyxl.load_workbook(file_path, read_only=True, data_only=True)
						parts_xl: list[str] = []
						for _sname in _wb.sheetnames[:4]:
							parts_xl.append(f"[Sayfa: {_sname}]")
							_ws = _wb[_sname]
							for _r_idx, _r_vals in enumerate(_ws.iter_rows(values_only=True)):
								if _r_idx >= 60:
									break
								row_s = [str(v).strip() for v in _r_vals if v is not None and str(v).strip()]
								if row_s:
									parts_xl.append(" | ".join(row_s))
						_wb.close()
						ext_txt = "\n".join(parts_xl)[:12000]
				except Exception:
					ext_txt = ""
			with ui.spinner("Gemini AI belgeyi okuyor ve okul reviri açısından özetliyor..."):
				ok_d, sum_md, used_m = gai.summarize_document_with_gemini(
					api_key=gai_key,
					model=gai_model,
					file_path=file_path,
					extracted_text=ext_txt,
				)
			ui.session_state[doc_sum_key] = {"ok": ok_d, "text": sum_md, "model": used_m}
		doc_sum_res = ui.session_state.get(doc_sum_key)
		if isinstance(doc_sum_res, dict):
			if doc_sum_res.get("ok"):
				with ui.container(border=True):
					ui.markdown(f"###### 🤖 Gemini AI Belge Özeti <small>({doc_sum_res.get('model')})</small>", unsafe_allow_html=True)
					ui.markdown(doc_sum_res.get("text", ""))
			else:
				ui.error(f"Gemini AI hatası: {doc_sum_res.get('text')}")

	if ext == ".pdf":
		import pymupdf
		try:
			doc = pymupdf.open(file_path)
			num_pages = len(doc)
			ui.caption(f"📑 Toplam **{num_pages}** sayfa bulundu — gerçek **A4 (210×297 mm)** kâğıt önizlemesi:")
			max_preview = min(num_pages, 8)
			sheet_chunks: list[str] = []
			for p_num in range(max_preview):
				page = doc[p_num]
				pix = page.get_pixmap(dpi=120)
				b64_p = base64.b64encode(pix.tobytes("png")).decode("ascii")
				sheet_chunks.append(
					f"<span class='revir-a4-page-badge'>📄 A4 · Sayfa {p_num + 1} / {num_pages}</span>"
					f"<div class='revir-a4-sheet-img'><img src='data:image/png;base64,{b64_p}' alt='Sayfa {p_num + 1}'/></div>"
				)
				del page, pix
			doc.close()
			del doc
			ui.markdown(f"<div class='revir-a4-stage'>{''.join(sheet_chunks)}</div>", unsafe_allow_html=True)
			if num_pages > max_preview:
				ui.info(f"ℹ️ Belgenin devamı ({num_pages - max_preview} sayfa daha var) için sağ üstteki **📥 İndir** veya **✍️ PDF Form Doldur** butonunu kullanabilirsiniz.")
		except Exception as e:
			ui.error(f"PDF önizleme hatası: {e}")

	elif ext in [".png", ".jpg", ".jpeg", ".webp"]:
		try:
			b64_img = base64.b64encode(file_path.read_bytes()).decode("ascii")
			mime_i = mimetypes.guess_type(file_path)[0] or "image/png"
			ui.markdown(
				f"<div class='revir-a4-stage'>"
				f"<span class='revir-a4-page-badge'>📄 A4 Görsel Önizleme</span>"
				f"<div class='revir-a4-sheet-img'><img src='data:{mime_i};base64,{b64_img}' alt='{html.escape(file_path.name)}'/></div>"
				f"</div>",
				unsafe_allow_html=True,
			)
		except Exception:
			ui.image(str(file_path), use_container_width=True)

	elif ext in [".xlsx", ".xls"]:
		try:
			import openpyxl
			wb = openpyxl.load_workbook(file_path, read_only=True, data_only=True)
			sheet_names = list(wb.sheetnames)
			wb.close()
			del wb
			f_h8 = sha256(file_path.name.encode()).hexdigest()[:8]
			xs1, xs2 = ui.columns([2.2, 1.3])
			with xs1:
				sel_sheet = ui.selectbox("📑 Görüntülenecek Sayfa (Sheet)", sheet_names, key=f"prev_sheet_{f_h8}")
			with xs2:
				orient_xl = ui.selectbox("📐 A4 Yönü", ["A4 Yatay (297×210 mm)", "A4 Dikey (210×297 mm)"], index=0, key=f"prev_orient_{f_h8}")
			a4_xl_html = dstudio.render_xlsx_a4_html(file_path, sel_sheet, landscape=("Yatay" in orient_xl))
			ui.components.v1.html(a4_xl_html, height=640, scrolling=True)
		except Exception as e:
			ui.warning(f"Excel önizleme oluşturulamadı: {e}")

	elif ext == ".docx":
		try:
			a4_docx_html = dstudio.render_docx_a4_html(file_path)
			ui.components.v1.html(a4_docx_html, height=660, scrolling=True)
		except Exception as e:
			ui.warning(f"Word A4 önizlemesi okunamadı: {e}")

	elif ext in [".txt", ".csv"]:
		try:
			txt_content = file_path.read_text(encoding="utf-8", errors="replace")[:14000]
			a4_txt_html = dstudio.render_text_a4_html(file_path, txt_content)
			ui.components.v1.html(a4_txt_html, height=620, scrolling=True)
		except Exception as e:
			ui.warning(f"Metin okunamadı: {e}")

	else:
		cov = get_or_create_document_cover(file_path)
		if cov and cov.exists():
			b64_c = base64.b64encode(cov.read_bytes()).decode("ascii")
			ui.markdown(
				f"<div class='revir-a4-stage'>"
				f"<span class='revir-a4-page-badge'>📄 A4 Kapak Önizleme</span>"
				f"<div class='revir-a4-sheet-img'><img src='data:image/png;base64,{b64_c}' alt='Kapak'/></div>"
				f"</div>",
				unsafe_allow_html=True,
			)


@ui.dialog("📤 Yeni Evrak / Belge Yükle", width="large", mode="drawer")
def open_upload_document_dialog() -> None:
	ui.caption("Revir ile ilgili resmi belgeleri (Word, Excel, PowerPoint), PDF yönergeleri, formları veya fotoğrafları sürükleyip bırakabilir ya da dosya seçebilirsiniz:")
	uploaded_files = ui.file_uploader(
		"Evrak Dosyaları Seçin",
		type=["pdf", "docx", "doc", "xlsx", "xls", "pptx", "ppt", "jpg", "jpeg", "png", "webp", "txt", "csv"],
		accept_multiple_files=True,
		key="depot_modal_file_uploader"
	)
	ui.markdown("")
	col_close, col_save = ui.columns([1, 1.2])
	with col_close:
		if ui.button("İptal / Kapat", use_container_width=True, key="btn_cancel_depot_modal"):
			ui.rerun()
	with col_save:
		if ui.button("💾 Dosyaları Depoya Kaydet", type="primary", disabled=not uploaded_files, use_container_width=True, key="btn_save_depot_modal"):
			saved_cnt = 0
			for uf in uploaded_files:
				safe_filename = re.sub(r'[\\/*?:"<>|]', "_", uf.name)
				target_path = EVRAKLAR_DIR / safe_filename
				target_path.write_bytes(uf.read())
				get_or_create_document_cover(target_path, force=True)
				saved_cnt += 1
			ui.success(f"✅ {saved_cnt} evrak başarıyla depoya yüklendi ve 1. sayfa kapak fotoğrafları hazırlandı!")
			ui.rerun()


def render_documents_depot() -> None:
	EVRAKLAR_DIR.mkdir(parents=True, exist_ok=True)
	(EVRAKLAR_DIR / ".thumbnails").mkdir(parents=True, exist_ok=True)
	_dep_ai_on, _, _ = _get_active_gemini_config()

	# Clean top header with upload, offline new-doc creator, and optional Gemini Smart Reader
	if _dep_ai_on:
		head_c, btn_c1, btn_c2, btn_c3 = ui.columns([3.0, 1.1, 1.15, 1.25])
	else:
		head_c, btn_c1, btn_c2 = ui.columns([3.7, 1.15, 1.2])
		btn_c3 = None

	with head_c:
		ui.markdown("## 📁 Revir Evrak & Dosya Deposu")
		ui.caption("Word (.docx), Excel (.xlsx) dosyalarını doğrudan düzenleyin, PDF formlardaki yazılabilir alanları tarayıp doldurun, resmi evrakları güvenle depolayın ve indirin.")
	with btn_c1:
		with ui.popover("➕ Yeni Belge", use_container_width=True, help="Depoda sıfırdan Word veya Excel belgesi oluştur"):
			ui.markdown("##### 📄 Yeni Ofis Belgesi Oluştur")
			new_doc_kind = ui.selectbox("Belge Türü", ["Word Belgesi (.docx)", "Excel Tablosu (.xlsx)"], key="depot_new_doc_kind")
			new_doc_title = ui.text_input("Belge Adı / Başlığı", placeholder="Örn: Revir Olay Tutanağı", key="depot_new_doc_title")
			if ui.button("✨ Oluştur & Düzenleyicide Aç", type="primary", use_container_width=True, key="depot_btn_create_new_doc"):
				kind_code = "xlsx" if "Excel" in new_doc_kind else "docx"
				created_p = dstudio.create_new_office_document_in_depot(EVRAKLAR_DIR, kind_code, new_doc_title.strip() or "Yeni_Revir_Belgesi", get_app_settings())
				get_or_create_document_cover(created_p, force=True)
				open_document_studio_dialog(created_p)
	with btn_c2:
		if is_section_visible("docs_upload"):
			if ui.button("📤 Evrak Yükle", type="primary", use_container_width=True, key="btn_trigger_upload_doc"):
				open_upload_document_dialog()
	if btn_c3 is not None:
		with btn_c3:
			if ui.button("🤖 Oku & Öğrenciye İşle", type="secondary", use_container_width=True, key="btn_depot_smart_imp", help="Yüklenen veya depodaki sağlık raporunu Gemini ile okuyup ilgili öğrencinin dosyasına işler"):
				open_smart_document_importer_dialog()

	ui.markdown("---")
	if not is_section_visible("docs_list"):
		ui.info("🗃️ Depodaki Belgeler Listesi Sayfa Ayarları'ndan gizlendi.")
	else:
		ui.markdown("#### 🗃️ Depodaki Belgeler ve Pencere Yöneticisi")

	toolbar_c1, toolbar_c2, toolbar_c3, toolbar_c4 = ui.columns([1.5, 1.8, 1.4, 2.0])
	with toolbar_c1:
		view_layout = ui.selectbox(
			"📐 Kart Boyutu",
			["Büyük Kartlar (3'lü Izgara)", "Orta Kartlar (4'lü Izgara)", "Küçük Kartlar (6'lı Izgara)", "Detaylı Liste"],
			index=1,
			key="depot_layout_choice"
		)
	with toolbar_c2:
		sort_mode = ui.selectbox(
			"🔃 Sıralama Biçimi",
			[
				"En Yeni Yüklenenler",
				"En Eski Yüklenenler",
				"İsme Göre (A-Z)",
				"İsme Göre (Z-A)",
				"Boyuta Göre (Büyükten Küçüğe)",
				"Boyuta Göre (Küçükten Büyüğe)",
				"Dosya Türüne Göre"
			],
			index=0,
			key="depot_sort_choice"
		)
	with toolbar_c3:
		type_filter = ui.selectbox(
			"🏷️ Tür Filtresi",
			["Tümü", "PDF Belgeleri", "Word Dosyaları", "Excel Dosyaları", "Sunumlar (PPTX)", "Resimler / Görseller", "Diğer"],
			index=0,
			key="depot_type_choice"
		)
	with toolbar_c4:
		search_query = ui.text_input(
			"🔍 Evrak Ara...",
			placeholder="Dosya adında ara...",
			key="depot_search_box"
		)

	depot_cat_tag = ui.radio(
		"Klinik Evrak Kategorisi",
		["🌐 Tümü", "📋 Tutanak / İzin / Form", "🩺 Tarama / Rapor", "💊 İlaç / Soğuk Zincir", "🍽️ Yemekhane / Menü"],
		horizontal=True,
		key="depot_clinical_tag_filter",
		label_visibility="collapsed",
	)

	all_files = [f for f in EVRAKLAR_DIR.iterdir() if f.is_file() and not f.name.startswith(".")]
	files_data = []
	for f in all_files:
		ext = f.suffix.lower()
		stat = f.stat()
		files_data.append({
			"path": f,
			"name": f.name,
			"ext": ext,
			"size": stat.st_size,
			"mtime": stat.st_mtime,
			"mtime_dt": datetime.fromtimestamp(stat.st_mtime)
		})

	if depot_cat_tag != "🌐 Tümü":
		def _match_depot_tag(nm: str, tag_lbl: str) -> bool:
			fn = _tr_fold(nm)
			if "Tutanak" in tag_lbl:
				return any(w in fn for w in ("tutanak", "izin", "onam", "form", "veli", "kaza", "sevk"))
			if "Tarama" in tag_lbl:
				return any(w in fn for w in ("tarama", "rapor", "persantil", "saglik", "meb", "tahlil"))
			if "İlaç" in tag_lbl:
				return any(w in fn for w in ("ilac", "doz", "soguk", "isi", "recete", "envanter", "stok"))
			if "Yemekhane" in tag_lbl:
				return any(w in fn for w in ("yemek", "menu", "fatura", "gider", "kasa", "diyet"))
			return True
		files_data = [x for x in files_data if _match_depot_tag(x["name"], depot_cat_tag)]

	if search_query.strip():
		q_lower = search_query.strip().lower()
		files_data = [x for x in files_data if q_lower in x["name"].lower()]

	if type_filter == "PDF Belgeleri":
		files_data = [x for x in files_data if x["ext"] == ".pdf"]
	elif type_filter == "Word Dosyaları":
		files_data = [x for x in files_data if x["ext"] in [".docx", ".doc"]]
	elif type_filter == "Excel Dosyaları":
		files_data = [x for x in files_data if x["ext"] in [".xlsx", ".xls"]]
	elif type_filter == "Sunumlar (PPTX)":
		files_data = [x for x in files_data if x["ext"] in [".pptx", ".ppt"]]
	elif type_filter == "Resimler / Görseller":
		files_data = [x for x in files_data if x["ext"] in [".jpg", ".jpeg", ".png", ".webp"]]
	elif type_filter == "Diğer":
		files_data = [x for x in files_data if x["ext"] not in [".pdf", ".docx", ".doc", ".xlsx", ".xls", ".pptx", ".ppt", ".jpg", ".jpeg", ".png", ".webp"]]

	if sort_mode == "En Yeni Yüklenenler":
		files_data.sort(key=lambda x: x["mtime"], reverse=True)
	elif sort_mode == "En Eski Yüklenenler":
		files_data.sort(key=lambda x: x["mtime"])
	elif sort_mode == "İsme Göre (A-Z)":
		files_data.sort(key=lambda x: x["name"].lower())
	elif sort_mode == "İsme Göre (Z-A)":
		files_data.sort(key=lambda x: x["name"].lower(), reverse=True)
	elif sort_mode == "Boyuta Göre (Büyükten Küçüğe)":
		files_data.sort(key=lambda x: x["size"], reverse=True)
	elif sort_mode == "Boyuta Göre (Küçükten Büyüğe)":
		files_data.sort(key=lambda x: x["size"])
	elif sort_mode == "Dosya Türüne Göre":
		files_data.sort(key=lambda x: (x["ext"], x["name"].lower()))

	total_cnt = len(files_data)
	total_size_bytes = sum(x["size"] for x in files_data)
	ui.caption(f"📁 **Toplam:** {total_cnt} evrak listeleniyor · **Boyut:** {format_file_size(total_size_bytes)} · **Konum:** `revir_evraklari/`")

	if not files_data:
		if search_query.strip() or type_filter != "Tümü":
			ui.info("Arama veya filtre kriterlerine uygun dosya bulunamadı.")
		else:
			ui.info("Evrak deposunda henüz yüklenmiş bir dosya bulunmuyor. Sağ üstteki '📤 Yeni Evrak Yükle' butonundan belge yükleyebilirsiniz.")
	else:
		PAGE_SIZE = 12
		total_pages = max(1, (total_cnt + PAGE_SIZE - 1) // PAGE_SIZE)
		if "depot_page_num" not in ui.session_state:
			ui.session_state["depot_page_num"] = 1
		if ui.session_state["depot_page_num"] > total_pages:
			ui.session_state["depot_page_num"] = total_pages
		if ui.session_state["depot_page_num"] < 1:
			ui.session_state["depot_page_num"] = 1

		curr_page = ui.session_state["depot_page_num"]
		start_idx = (curr_page - 1) * PAGE_SIZE
		end_idx = min(start_idx + PAGE_SIZE, total_cnt)
		page_items = files_data[start_idx:end_idx]

		if total_pages > 1:
			p_col1, p_col2, p_col3 = ui.columns([1.5, 3.5, 1.5])
			with p_col1:
				if ui.button("◀ Önceki Sayfa", disabled=(curr_page <= 1), key="depot_pg_prev_top", use_container_width=True):
					ui.session_state["depot_page_num"] = curr_page - 1
					ui.rerun()
			with p_col2:
				ui.markdown(
					f"<div style='text-align:center; padding-top:6px; font-weight:600; color:#475569; font-size:13.5px;'>"
					f"📄 Sayfa {curr_page} / {total_pages} &nbsp;·&nbsp; {start_idx + 1} - {end_idx} / {total_cnt} evrak gösteriliyor"
					f"</div>",
					unsafe_allow_html=True
				)
			with p_col3:
				if ui.button("Sonraki Sayfa ▶", disabled=(curr_page >= total_pages), key="depot_pg_next_top", use_container_width=True):
					ui.session_state["depot_page_num"] = curr_page + 1
					ui.rerun()

		# DETAYLI LİSTE GÖRÜNÜMÜ (Windows Dosya Gezgini / Finder Tarzı Yatay Satırlar)
		if view_layout == "Detaylı Liste":
			for item in page_items:
				item_hash = sha256(item['name'].encode()).hexdigest()[:12]
				with ui.container(border=True):
					col_icon, col_info, col_actions = ui.columns([0.8, 5.8, 3.4])
					with col_icon:
						cover_path = get_or_create_document_cover(item["path"])
						if cover_path and cover_path.exists():
							ui.image(str(cover_path), use_container_width=True)
						else:
							ui.markdown("<div style='font-size:28px; text-align:center; padding-top:4px;'>📄</div>", unsafe_allow_html=True)
					with col_info:
						ui.markdown(f"**{item['name']}**")
						ext_label = item['ext'].upper().strip('.')
						ui.caption(f"🏷️ `{ext_label}` · 📏 {format_file_size(item['size'])} · 🕒 {item['mtime_dt'].strftime('%d.%m.%Y %H:%M')}")
					with col_actions:
						can_edit_doc = item["ext"] in (".pdf", ".docx", ".xlsx", ".txt", ".csv")
						if can_edit_doc:
							la0, la1, la2, la3, la4 = ui.columns([1, 1, 1, 1, 1])
							with la0:
								ed_tip = "PDF Form Tara & Yazı Yaz" if item["ext"] == ".pdf" else "Ofis Stüdyosunda Düzenle"
								if ui.button("🛠️", key=f"btn_edit_list_{item_hash}", help=ed_tip, type="primary", use_container_width=True):
									open_document_studio_dialog(item["path"])
						else:
							la1, la2, la3, la4 = ui.columns([1, 1, 1, 1])
						with la1:
							if ui.button("👁️", key=f"btn_prev_list_{item_hash}", help="Evrakı Aç / Önizle", use_container_width=True):
								open_document_preview_dialog(item["path"])
						with la2:
							mime_t = mimetypes.guess_type(item["path"])[0] or "application/octet-stream"
							ui.download_button("📥", data=lambda _p=item["path"]: _p.read_bytes(), file_name=item["name"], mime=mime_t, key=f"dl_list_{item_hash}", help="İndir", use_container_width=True)
						with la3:
							with ui.popover("✏️", use_container_width=True, help="Ad Değiştir"):
								ui.markdown("##### ✏️ Yeniden Adlandır")
								new_stem = ui.text_input("Yeni Dosya Adı", value=item["path"].stem, key=f"ren_list_{item_hash}")
								if ui.button("Kaydet", type="primary", key=f"btn_save_ren_list_{item_hash}", use_container_width=True):
									if new_stem.strip():
										safe_stem = re.sub(r'[\\/*?:"<>|]', "_", new_stem.strip())
										new_target = EVRAKLAR_DIR / f"{safe_stem}{item['ext']}"
										if new_target != item["path"]:
											if new_target.exists():
												ui.error("Bu isimde bir dosya zaten var!")
											else:
												old_cov = get_document_cover_path(item["path"])
												if old_cov.exists():
													old_cov.unlink(missing_ok=True)
												item["path"].rename(new_target)
												get_or_create_document_cover(new_target, force=True)
												ui.success("Dosya adı güncellendi.")
												ui.rerun()
						with la4:
							with ui.popover("🗑️", use_container_width=True, help="Sil"):
								ui.markdown("##### ⚠️ Dosyayı Sil")
								ui.warning(f"**{item['name']}** dosyası silinecek. Emin misiniz?")
								if ui.button("Evet, Sil", type="secondary", key=f"btn_del_list_{item_hash}", use_container_width=True):
									try:
										cov_p = get_document_cover_path(item["path"])
										if cov_p.exists():
											cov_p.unlink(missing_ok=True)
										item["path"].unlink()
										ui.success("Dosya silindi.")
										ui.rerun()
									except Exception as e:
										ui.error(f"Silme hatası: {e}")

		# KART IZGARA GÖRÜNÜMÜ (3'lü, 4'lü, 6'lı)
		else:
			if view_layout == "Büyük Kartlar (3'lü Izgara)":
				grid_cols_cnt = 3
			elif view_layout == "Orta Kartlar (4'lü Izgara)":
				grid_cols_cnt = 4
			else:
				grid_cols_cnt = 6

			rows = [page_items[i:i + grid_cols_cnt] for i in range(0, len(page_items), grid_cols_cnt)]
			for row in rows:
				cols = ui.columns(grid_cols_cnt)
				for idx, item in enumerate(row):
					with cols[idx]:
						item_hash = sha256(item['name'].encode()).hexdigest()[:12]
						with ui.container(border=True):
							# Render First Page Cover Photo!
							cover_path = get_or_create_document_cover(item["path"])
							if cover_path and cover_path.exists():
								try:
									ui.image(str(cover_path), use_container_width=True)
								except Exception:
									ui.markdown("📄 Evrak Önizlemesi")
							else:
								# Clean fallback card
								ui.markdown(
									f"""<div style='background:#f1f5f9; border:1px solid #cbd5e1; border-radius:8px; padding:22px 10px; text-align:center;'>
										<div style='font-size:32px;'>📄</div>
										<div style='font-weight:700; color:#475569; font-size:12px; margin-top:4px;'>{item['ext'].upper().strip('.')} BELGESİ</div>
									</div>""",
									unsafe_allow_html=True
								)

							short_name = item["name"] if len(item["name"]) <= 30 else item["name"][:27] + "..."
							ui.markdown(f"<div style='font-weight:700; font-size:13.5px; margin-top:8px; word-break:break-all;' title='{html.escape(item['name'])}'>{html.escape(short_name)}</div>", unsafe_allow_html=True)
							ui.caption(f"📏 {format_file_size(item['size'])} · 🕒 {item['mtime_dt'].strftime('%d.%m.%Y %H:%M')}")

							can_edit_card = item["ext"] in (".pdf", ".docx", ".xlsx", ".txt", ".csv")
							if can_edit_card:
								ed_card_lbl = "✍️ PDF Tara & Doldur" if item["ext"] == ".pdf" else "🛠️ Belgeyi Düzenle"
								if ui.button(ed_card_lbl, key=f"btn_studio_card_{item_hash}", type="primary", use_container_width=True):
									open_document_studio_dialog(item["path"])

							act_col0, act_col1, act_col2, act_col3 = ui.columns([1, 1, 1, 1])
							with act_col0:
								if ui.button("👁️", key=f"btn_prev_{item_hash}", help="Evrakı Önizle / Oku", use_container_width=True):
									open_document_preview_dialog(item["path"])
							with act_col1:
								mime_t = mimetypes.guess_type(item["path"])[0] or "application/octet-stream"
								ui.download_button(
									"📥",
									data=lambda _p=item["path"]: _p.read_bytes(),
									file_name=item["name"],
									mime=mime_t,
									key=f"dl_btn_{item_hash}",
									help="İndir",
									use_container_width=True
								)
							with act_col2:
								with ui.popover("✏️", use_container_width=True, help="Dosyayı Yeniden Adlandır"):
									ui.markdown("##### ✏️ Yeniden Adlandır")
									new_stem = ui.text_input("Yeni Dosya Adı", value=item["path"].stem, key=f"rename_inp_{item_hash}")
									if ui.button("Kaydet", type="primary", key=f"btn_save_rename_{item_hash}", use_container_width=True):
										if new_stem.strip():
											safe_stem = re.sub(r'[\\/*?:"<>|]', "_", new_stem.strip())
											new_target = EVRAKLAR_DIR / f"{safe_stem}{item['ext']}"
											if new_target != item["path"]:
												if new_target.exists():
													ui.error("Bu isimde bir dosya zaten var!")
												else:
													# Remove old cover
													old_cov = get_document_cover_path(item["path"])
													if old_cov.exists():
														old_cov.unlink(missing_ok=True)
													item["path"].rename(new_target)
													get_or_create_document_cover(new_target, force=True)
													ui.success("Dosya adı güncellendi.")
													ui.rerun()
							with act_col3:
								with ui.popover("🗑️", use_container_width=True, help="Dosyayı Sil"):
									ui.markdown("##### ⚠️ Dosyayı Sil")
									ui.warning(f"**{item['name']}** dosyası kalıcı olarak silinecek. Emin misiniz?")
									if ui.button("Evet, Sil", type="secondary", key=f"btn_confirm_del_{item_hash}", use_container_width=True):
										try:
											cov_p = get_document_cover_path(item["path"])
											if cov_p.exists():
												cov_p.unlink(missing_ok=True)
											item["path"].unlink()
											ui.success("Dosya silindi.")
											ui.rerun()
										except Exception as e:
											ui.error(f"Silme hatası: {e}")

		if total_pages > 1:
			ui.markdown("")
			bp_col1, bp_col2, bp_col3 = ui.columns([1.5, 3.5, 1.5])
			with bp_col1:
				if ui.button("◀ Önceki Sayfa", disabled=(curr_page <= 1), key="depot_pg_prev_btm", use_container_width=True):
					ui.session_state["depot_page_num"] = curr_page - 1
					ui.rerun()
			with bp_col2:
				ui.markdown(
					f"<div style='text-align:center; padding-top:6px; font-weight:600; color:#475569; font-size:13.5px;'>"
					f"📄 Sayfa {curr_page} / {total_pages}"
					f"</div>",
					unsafe_allow_html=True
				)
			with bp_col3:
				if ui.button("Sonraki Sayfa ▶", disabled=(curr_page >= total_pages), key="depot_pg_next_btm", use_container_width=True):
					ui.session_state["depot_page_num"] = curr_page + 1
					ui.rerun()

		gc.collect()


def get_git_info() -> dict[str, Any]:
	info = {
		"is_git": False,
		"branch": "",
		"commit": "",
		"commit_date": "",
		"commit_msg": "",
		"remote_url": "",
		"has_remote": False,
	}
	git_dir = APP_DIR / ".git"
	if not git_dir.exists():
		return info
	info["is_git"] = True
	import subprocess
	try:
		r = subprocess.run(["git", "branch", "--show-current"], cwd=APP_DIR, capture_output=True, text=True, timeout=3)
		info["branch"] = r.stdout.strip() or "main"

		r2 = subprocess.run(["git", "log", "-1", "--format=%h|%cd|%s", "--date=short"], cwd=APP_DIR, capture_output=True, text=True, timeout=3)
		if r2.stdout.strip():
			parts = r2.stdout.strip().split("|", 2)
			if len(parts) >= 3:
				info["commit"], info["commit_date"], info["commit_msg"] = parts

		r3 = subprocess.run(["git", "remote", "get-url", "origin"], cwd=APP_DIR, capture_output=True, text=True, timeout=3)
		if r3.returncode == 0 and r3.stdout.strip():
			info["remote_url"] = r3.stdout.strip()
			info["has_remote"] = True
	except Exception:
		pass
	return info


OFFICIAL_REPO_URL = "https://github.com/blue-doggy/revir_defteri.git"
GITHUB_RELEASES_API_URL = "https://api.github.com/repos/blue-doggy/revir_defteri/releases?per_page=15"


def _ensure_tls_trust() -> None:
	"""Paketli (PyInstaller) Windows/macOS ortamlarda HTTPS doğrulaması için sistem kök sertifikalarını enjekte eder."""
	try:
		import truststore
		truststore.inject_into_ssl()
	except Exception:
		pass


def _parse_version_tuple(raw_ver: Any) -> tuple[int, ...]:
	"""Sürüm veya dosya adı içinden SemVer sayı demeti (ör. 'v1.16.16' -> (1, 16, 16)) çıkarır."""
	txt = str(raw_ver or "").strip()
	if not txt:
		return ()
	m = re.search(r"(?:^|[^a-zA-Z0-9])v(\d+(?:\.\d+)+)", txt, flags=re.IGNORECASE)
	if not m:
		m = re.search(r"(\d+(?:\.\d+)+)", txt)
	if not m:
		return ()
	try:
		return tuple(int(part) for part in m.group(1).split("."))
	except Exception:
		return ()


def _extract_version_str(raw_ver: Any, fallback: str = "") -> str:
	tup = _parse_version_tuple(raw_ver)
	if tup:
		return ".".join(str(x) for x in tup)
	clean = str(fallback or "").strip().lstrip("vV")
	return clean


def _compare_versions(ver_a: Any, ver_b: Any) -> int:
	"""İki sürümü SemVer kurallarına göre karşılaştırır (-1: a < b, 0: a == b, 1: a > b)."""
	ta = list(_parse_version_tuple(ver_a))
	tb = list(_parse_version_tuple(ver_b))
	if not ta and not tb:
		return 0
	n = max(len(ta), len(tb))
	ta.extend([0] * (n - len(ta)))
	tb.extend([0] * (n - len(tb)))
	if ta < tb:
		return -1
	if ta > tb:
		return 1
	return 0


def _detect_target_installer_platform(platform_override: str | None = None) -> tuple[str, str, str]:
	"""Geçerli işletim sistemine göre aranacak GitHub kurulum paketi türünü döndürür: (anahtar, etiket, uzantı)."""
	plat = str(platform_override or sys.platform or "").strip().lower()
	if plat.startswith("win"):
		return "windows", "Windows (.exe Kurulum)", ".exe"
	if plat == "darwin":
		return "macos", "macOS (.dmg Disk İmajı)", ".dmg"
	return "other", "Masaüstü Kurulum Paketi", ""


def _select_release_asset_for_platform(assets: list[dict[str, Any]], ext: str) -> dict[str, Any] | None:
	"""GitHub Release içindeki asset listesinden işletim sistemine en uygun kurulum dosyasını seçer."""
	if not isinstance(assets, list):
		return None
	candidates: list[tuple[int, dict[str, Any]]] = []
	for item in assets:
		if not isinstance(item, dict):
			continue
		name = str(item.get("name") or "").strip()
		dl_url = str(item.get("browser_download_url") or "").strip()
		if not name or not dl_url:
			continue
		low = name.lower()
		if ext and not low.endswith(ext):
			continue
		if not ext and not (low.endswith(".exe") or low.endswith(".dmg")):
			continue
		score = 10
		if ext == ".exe":
			if "kurulum" in low or "setup" in low:
				score += 20
			if "revirdefteri" in low:
				score += 10
		elif ext == ".dmg":
			if "arm64" in low:
				score += 15
			if "revirdefteri" in low:
				score += 10
		candidates.append((score, item))
	if not candidates:
		return None
	candidates.sort(key=lambda pair: pair[0], reverse=True)
	chosen = candidates[0][1]
	size_bytes = int(chosen.get("size") or 0)
	return {
		"name": str(chosen.get("name") or ""),
		"version": _extract_version_str(chosen.get("name") or ""),
		"size_bytes": size_bytes,
		"size_str": format_file_size(size_bytes) if size_bytes >= 0 else "Bilinmiyor",
		"download_url": str(chosen.get("browser_download_url") or ""),
		"content_type": str(chosen.get("content_type") or "application/octet-stream"),
		"updated_at": str(chosen.get("updated_at") or ""),
	}


def _format_release_datetime_tr(iso_ts: Any) -> str:
	txt = str(iso_ts or "").strip()
	if not txt:
		return "—"
	try:
		dt_obj = datetime.fromisoformat(txt.replace("Z", "+00:00"))
		return dt_obj.astimezone().strftime("%d.%m.%Y %H:%M")
	except Exception:
		return txt[:16].replace("T", " ")


def check_for_github_release_updates(
	platform_override: str | None = None,
	current_version: str | None = None,
	timeout: float = 12.0,
) -> dict[str, Any]:
	"""GitHub Releases üzerinde işletim sistemine uygun (.exe / .dmg) paket sürümünü, boyutunu ve indirme bilgisini denetler."""
	import urllib.error
	import urllib.request

	cur_ver = _extract_version_str(current_version or APP_VERSION, fallback=str(current_version or APP_VERSION))
	plat_key, plat_label, target_ext = _detect_target_installer_platform(platform_override)
	res: dict[str, Any] = {
		"success": False,
		"has_updates": False,
		"source": "github_release",
		"current_version": cur_ver,
		"latest_version": cur_ver,
		"tag_name": f"v{cur_ver}",
		"release_name": "",
		"release_url": "https://github.com/blue-doggy/revir_defteri/releases",
		"published_at": "",
		"release_notes": "",
		"platform_key": plat_key,
		"platform_label": plat_label,
		"asset": None,
		"all_assets": [],
		"pending_build_note": "",
		"ahead": 0,
		"behind": 0,
		"commits": [],
		"message": "",
	}

	_ensure_tls_trust()
	req = urllib.request.Request(
		GITHUB_RELEASES_API_URL,
		headers={
			"User-Agent": f"RevirDefteri/{cur_ver}",
			"Accept": "application/vnd.github+json",
		},
	)
	try:
		with urllib.request.urlopen(req, timeout=timeout) as resp:
			raw_bytes = resp.read()
		releases = json.loads(raw_bytes.decode("utf-8"))
		if not isinstance(releases, list):
			releases = [releases] if isinstance(releases, dict) else []
	except urllib.error.HTTPError as he:
		if he.code == 403:
			res["message"] = "GitHub API istek sınırına geçici olarak ulaşıldı. Lütfen birkaç dakika sonra tekrar deneyin."
		else:
			res["message"] = f"GitHub sürüm sunucusuna bağlanılamadı (HTTP {he.code})."
		return res
	except urllib.error.URLError:
		res["message"] = "GitHub sürüm sunucusuna bağlanılamadı. Lütfen internet bağlantınızı kontrol edin."
		return res
	except TimeoutError:
		res["message"] = "Zaman aşımı: GitHub sürüm sunucusundan yanıt alınamadı."
		return res
	except Exception as exc:
		res["message"] = f"Güncelleme denetleme hatası: {exc}"
		return res

	non_draft = [r for r in releases if isinstance(r, dict) and not r.get("draft")]
	if not non_draft:
		res["success"] = True
		res["message"] = "GitHub üzerinde henüz yayınlanmış bir sürüm bulunamadı."
		return res

	highest_any_ver = ""
	best_match: tuple[tuple[int, ...], int, dict[str, Any], dict[str, Any]] | None = None

	for rel in non_draft:
		tag_str = str(rel.get("tag_name") or "").strip()
		rel_ver = _extract_version_str(tag_str)
		if rel_ver and _compare_versions(rel_ver, highest_any_ver) > 0:
			highest_any_ver = rel_ver

		chosen_asset = _select_release_asset_for_platform(rel.get("assets") or [], target_ext)
		if not chosen_asset:
			continue
		asset_ver = chosen_asset.get("version") or rel_ver
		if not asset_ver:
			continue
		chosen_asset["version"] = asset_ver
		ver_tup = _parse_version_tuple(asset_ver)
		is_stable_rank = 0 if rel.get("prerelease") else 1
		if best_match is None or (ver_tup, is_stable_rank) > (best_match[0], best_match[1]):
			best_match = (ver_tup, is_stable_rank, rel, chosen_asset)

	if best_match is None:
		res["success"] = True
		ext_lbl = target_ext or "kurulum"
		res["message"] = f"GitHub yayınlarında {plat_label} ({ext_lbl}) kurulum dosyası henüz bulunamadı."
		if highest_any_ver and _compare_versions(highest_any_ver, cur_ver) > 0:
			res["pending_build_note"] = (
				f"GitHub'da v{highest_any_ver} sürümü oluşturulmuş ancak {plat_label} paketi henüz yüklenmemiş görünüyor."
			)
		return res

	_, _, best_rel, best_asset = best_match
	best_ver = str(best_asset["version"])
	notes_raw = str(best_rel.get("body") or "").strip()
	note_lines = [re.sub(r"^\s*(?:[-•]|\*\s+)\s*", "", ln).strip() for ln in notes_raw.splitlines() if ln.strip()][:10]
	all_assets_clean = []
	for a in (best_rel.get("assets") or []):
		if isinstance(a, dict) and a.get("name") and a.get("browser_download_url"):
			sz_b = int(a.get("size") or 0)
			all_assets_clean.append({
				"name": str(a.get("name")),
				"size_bytes": sz_b,
				"size_str": format_file_size(sz_b),
				"download_url": str(a.get("browser_download_url")),
			})

	has_upd = _compare_versions(best_ver, cur_ver) > 0
	res.update({
		"success": True,
		"has_updates": has_upd,
		"latest_version": best_ver,
		"tag_name": str(best_rel.get("tag_name") or f"v{best_ver}"),
		"release_name": str(best_rel.get("name") or f"Okul Revir Defteri v{best_ver}"),
		"release_url": str(best_rel.get("html_url") or res["release_url"]),
		"published_at": _format_release_datetime_tr(best_rel.get("published_at")),
		"release_notes": notes_raw,
		"asset": best_asset,
		"all_assets": all_assets_clean,
		"behind": 1 if has_upd else 0,
		"commits": note_lines,
	})
	if highest_any_ver and _compare_versions(highest_any_ver, best_ver) > 0:
		res["pending_build_note"] = (
			f"Bilgi: GitHub'da v{highest_any_ver} etiketi mevcut ancak {plat_label} kurulum paketi henüz derleniyor/yüklenmemiş olabilir."
		)
	if has_upd:
		res["message"] = (
			f"Yeni {plat_label} güncellemesi mevcut: v{best_ver} "
			f"({best_asset['name']} · {best_asset['size_str']})"
		)
	else:
		res["message"] = (
			f"Sisteminiz güncel! Kurulu sürüm (v{cur_ver}), GitHub'da yayınlanan en son "
			f"{plat_label} paketi (v{best_ver}) ile eşleşiyor."
		)
	return res


def download_github_release_asset(
	download_url: str,
	file_name: str,
	expected_size: int = 0,
	target_dir: Path | None = None,
	timeout: float = 120.0,
) -> tuple[bool, Path | None, str]:
	"""GitHub Release kurulum dosyasını (.exe / .dmg) akışlı olarak İndirilenler klasörüne indirir."""
	import urllib.request

	url_clean = str(download_url or "").strip()
	if not url_clean.startswith("https://"):
		return False, None, "Geçersiz indirme bağlantısı (yalnızca HTTPS desteklenir)."
	safe_name = Path(str(file_name or "").strip()).name
	if not safe_name or safe_name in (".", ".."):
		return False, None, "Geçersiz kurulum dosya adı."

	dest_dir = Path(target_dir) if target_dir is not None else (Path.home() / "Downloads")
	try:
		dest_dir.mkdir(parents=True, exist_ok=True)
	except Exception:
		dest_dir = APP_DIR / "guncellemeler"
		dest_dir.mkdir(parents=True, exist_ok=True)

	dest_path = dest_dir / safe_name
	exp_sz = int(expected_size or 0)
	if dest_path.exists() and exp_sz > 0 and dest_path.stat().st_size == exp_sz:
		return True, dest_path, f"Kurulum paketi zaten hazır: {dest_path} ({format_file_size(exp_sz)})"

	part_path = dest_dir / f".{safe_name}.part"
	_ensure_tls_trust()
	req = urllib.request.Request(
		url_clean,
		headers={"User-Agent": f"RevirDefteri/{APP_VERSION}", "Accept": "application/octet-stream"},
	)
	total_written = 0
	try:
		with urllib.request.urlopen(req, timeout=timeout) as resp:
			with open(part_path, "wb") as fh:
				while True:
					chunk = resp.read(131072)
					if not chunk:
						break
					fh.write(chunk)
					total_written += len(chunk)
		if total_written <= 0 or (exp_sz > 0 and total_written < int(exp_sz * 0.98)):
			try:
				part_path.unlink(missing_ok=True)
			except Exception:
				pass
			return False, None, f"İndirme eksik tamamlandı ({format_file_size(total_written)})."
		os.replace(part_path, dest_path)
		return True, dest_path, f"Kurulum dosyası indirildi: {dest_path} ({format_file_size(total_written)})"
	except Exception as exc:
		try:
			part_path.unlink(missing_ok=True)
		except Exception:
			pass
		return False, None, f"Kurulum dosyası indirilemedi: {exc}"


def open_downloaded_installer(
	installer_path: str | Path,
	*,
	platform_override: str | None = None,
	reveal_only: bool = False,
) -> tuple[bool, str]:
	"""İndirilen .exe kurulum sihirbazını veya .dmg disk imajını açar (ya da klasörde gösterir)."""
	import subprocess

	p = Path(installer_path)
	if not p.exists():
		return False, f"Kurulum dosyası bulunamadı: {p}"

	plat = str(platform_override or sys.platform or "").strip().lower()
	try:
		if plat.startswith("win"):
			if reveal_only:
				subprocess.Popen(["explorer", f"/select,{p}"], close_fds=True)
				return True, "İndirilen kurulum dosyası Windows Gezgini'nde gösterildi."
			if hasattr(os, "startfile"):
				os.startfile(str(p))
			else:
				subprocess.Popen([str(p)], close_fds=True)
			return True, "Windows kurulum sihirbazı (.exe) başlatıldı! Kurulum sırasında açık uygulama otomatik olarak güncellenecektir."

		if plat == "darwin":
			if reveal_only:
				subprocess.Popen(["open", "-R", str(p)], close_fds=True)
				return True, "İndirilen .dmg dosyası Finder'da gösterildi."
			subprocess.Popen(["open", str(p)], close_fds=True)
			return True, "macOS kurulum paketi (.dmg) açıldı! Açılan pencerede RevirDefteri.app simgesini Applications klasörüne sürükleyin ve ilk açılışta gerekirse 'Ilk_Acilis_Izni_Ver.command' dosyasını çalıştırın."

		cmd = ["xdg-open", str(p.parent if reveal_only else p)]
		subprocess.Popen(cmd, close_fds=True)
		return True, "Dosya açıldı."
	except Exception as exc:
		return False, f"Dosya açılamadı: {exc}"


def ensure_official_git_remote() -> bool:
	import subprocess
	try:
		r = subprocess.run(["git", "remote", "get-url", "origin"], cwd=APP_DIR, capture_output=True, text=True, timeout=3)
		if r.returncode != 0:
			subprocess.run(["git", "remote", "add", "origin", OFFICIAL_REPO_URL], cwd=APP_DIR, capture_output=True, timeout=3)
		elif "blue-doggy/revir_defteri" not in r.stdout.strip():
			subprocess.run(["git", "remote", "set-url", "origin", OFFICIAL_REPO_URL], cwd=APP_DIR, capture_output=True, timeout=3)
		return True
	except Exception:
		return False


def check_for_git_updates(platform_override: str | None = None) -> dict[str, Any]:
	"""GitHub Release üzerinden işletim sistemine uygun (.exe / .dmg) paket güncellemesini denetler."""
	return check_for_github_release_updates(platform_override=platform_override)


def perform_system_update() -> tuple[bool, str]:
	if getattr(sys, "frozen", False) or not (APP_DIR / ".git").exists():
		return False, f"Bağımsız masaüstü (.exe) sürümünde git üzerinden güncelleme yerine yeni kurulum paketi (RevirDefteri_Kurulum_v{APP_VERSION}.exe) çalıştırılmalıdır."
	import subprocess
	import shutil

	ensure_official_git_remote()

	backup_dir = APP_DIR / "otomatik_guncelleme_yedekleri"
	backup_dir.mkdir(parents=True, exist_ok=True)
	ts = datetime.now().strftime("%Y%m%d_%H%M%S")
	zip_path = backup_dir / f"guncelleme_oncesi_yedek_{ts}.zip"
	try:
		import zipfile
		curr_db = get_current_db_path()
		curr_pdir = get_current_person_data_dir()
		with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
			if curr_db.exists():
				zf.write(curr_db, arcname="revir_defteri.db")
			if curr_pdir.exists():
				for pf in curr_pdir.glob("*.json"):
					zf.write(pf, arcname=f"kisi_verileri/{pf.name}")
	except Exception:
		pass

	try:
		pull_res = subprocess.run(["git", "pull", "--ff-only", "origin", "main"], cwd=APP_DIR, capture_output=True, text=True, timeout=30)
		if pull_res.returncode != 0:
			pull_res = subprocess.run(["git", "pull", "origin", "main"], cwd=APP_DIR, capture_output=True, text=True, timeout=30)
			if pull_res.returncode != 0:
				return False, f"Güncelleme indirilemedi: {pull_res.stderr.strip() or pull_res.stdout.strip()}"

		req_file = APP_DIR / "requirements.txt"
		if req_file.exists():
			subprocess.run([sys.executable, "-m", "pip", "install", "-r", "requirements.txt", "--quiet"], cwd=APP_DIR, capture_output=True, timeout=40)

		clear_all_data_caches()
		return True, "Güncelleme başarıyla tamamlandı!"
	except Exception as e:
		return False, f"Güncelleme işlemi başarısız oldu: {e}"


def create_or_refresh_desktop_launcher() -> Path:
	desktop_dir = Path.home() / "OneDrive" / "Masaüstü"
	if not desktop_dir.exists():
		desktop_dir = Path.home() / "Desktop"
	desktop_dir.mkdir(parents=True, exist_ok=True)

	is_frozen = getattr(sys, "frozen", False)
	if is_frozen:
		target_path = Path(sys.executable).resolve()
		target_args = ""
		work_dir = target_path.parent
	else:
		pythonw_exe = Path(sys.executable).parent / "pythonw.exe"
		if not pythonw_exe.exists():
			pythonw_exe = Path(sys.executable)
		desktop_py = APP_DIR / "desktop_launcher.py"
		launch_script = desktop_py if desktop_py.exists() else (APP_DIR / "baslat.pyw")
		target_path = pythonw_exe
		target_args = f'`"{launch_script}`"'
		work_dir = APP_DIR

	# Create or refresh desktop .lnk shortcut with custom icon and NO console window
	lnk_path = desktop_dir / "Revir Defteri.lnk"
	try:
		import subprocess
		ps_cmd = f"""
$WshShell = New-Object -ComObject WScript.Shell
$Shortcut = $WshShell.CreateShortcut('{lnk_path}')
$Shortcut.TargetPath = '{target_path}'
$Shortcut.Arguments = '{target_args}'
$Shortcut.WorkingDirectory = '{work_dir}'
$Shortcut.IconLocation = '{APP_ICON_ICO}, 0'
$Shortcut.Description = 'Revir Defteri - Okul Saglik Takip Sistemi'
$Shortcut.WindowStyle = 1
$Shortcut.Save()
(Get-Item '{lnk_path}').LastWriteTime = Get-Date
ie4uinit.exe -show
"""
		subprocess.run(["powershell", "-NoProfile", "-Command", ps_cmd], capture_output=True, timeout=8)
	except Exception:
		pass
	return lnk_path



