# ÜST BAĞLAM ÇUBUĞU, GRUPLANMIŞ YAN MENÜ VE GLOBAL KOMUT PALETİ (Cmd/Ctrl+K)
# ==============================================================================

def _handle_topbar_action(act_key: str, act_val: Any) -> None:
	if act_key == "toggle_kvkk":
		ui.session_state["kvkk_privacy_mode"] = not bool(ui.session_state.get("kvkk_privacy_mode", False))
		ui.rerun(scope="fragment")
	elif act_key == "toggle_ai":
		cfg = get_app_settings()
		cur_en = str(cfg.get("gemini_enabled", "1")).strip() != "0"
		has_key = bool(gai.get_api_key(cfg, APP_DIR))
		if not has_key:
			save_app_settings({"gemini_enabled": "1"})
			ui.session_state["cfg_gemini_enabled_toggle"] = True
			ui.session_state["_ai_key_needed_warn"] = True
			clear_all_data_caches()
			ui.close_dialog(all_dialogs=True)
			ui.session_state["settings_vertical_nav"] = "🤖 Yapay Zekâ & KVKK"
			ui.session_state["target_page"] = "⚙️ Ayarlar"
			ui.rerun()
		else:
			nxt_en = not cur_en
			save_app_settings({"gemini_enabled": "1" if nxt_en else "0"})
			ui.session_state["cfg_gemini_enabled_toggle"] = nxt_en
			clear_all_data_caches()
			_sync_floating_chat_ui()
			ui.rerun(scope="fragment")
	elif act_key == "cycle_dark":
		cfg = get_app_settings()
		cur_dm = cfg.get("dark_mode_adaptation", DARK_MODE_OPTIONS[0])
		is_dk = is_dark_mode_active(cfg)
		nxt_dm = DARK_MODE_OPTIONS[1] if is_dk else DARK_MODE_OPTIONS[2]
		if cur_dm == DARK_MODE_OPTIONS[2]:
			nxt_dm = DARK_MODE_OPTIONS[1]
		elif cur_dm == DARK_MODE_OPTIONS[1]:
			nxt_dm = DARK_MODE_OPTIONS[2]
		save_app_settings({"dark_mode_adaptation": nxt_dm})
		clear_all_data_caches()
		ui.rerun(scope="fragment")
	elif act_key == "goto_page" and act_val in PAGES:
		ui.close_dialog(all_dialogs=True)
		ui.session_state["target_page"] = str(act_val)
		ui.rerun()
	elif act_key == "goto_settings_group":
		ui.close_dialog(all_dialogs=True)
		ui.session_state["settings_vertical_nav"] = str(act_val or SETTINGS_GROUPS_META[0]["key"])
		ui.session_state["target_page"] = "⚙️ Ayarlar"
		ui.rerun()
	elif act_key == "open_active_dossier":
		pid = ui.session_state.get("active_person_id")
		if pid:
			open_person_dossier_dialog(int(pid))


def _tr_fold(text: Any) -> str:
	s = str(text or "").replace("İ", "i").replace("I", "ı").lower().replace("\u0307", "")
	return s.translate(str.maketrans("çğıöşü", "cgiosu"))


def _handle_cmd_search(query: str) -> list[dict[str, Any]]:
	q_raw = (query or "").strip()
	q = _tr_fold(q_raw)
	q_sql = q_raw.replace("İ", "i").replace("I", "ı").lower().replace("\u0307", "")
	results: list[dict[str, Any]] = []

	# 1. Hızlı İşlemler
	_cmd_ai_on, _cmd_ai_key, _cmd_ai_model = _get_active_gemini_config()
	quick_cmds = [
		{"group": "⚡ Hızlı İşlemler", "kind": "page", "value": "🩺 Revir Kaydı", "icon": "🩺", "title": "Yeni Revir Kaydı Aç", "subtitle": "Öğrenci veya yetişkin revir başvurusu kaydet (Alt+V)", "tag": "Sayfa"},
		{"group": "⚡ Hızlı İşlemler", "kind": "page", "value": "💉 İnsülin & Diyabet Yönetimi", "icon": "💉", "title": "İnsülin Dozu Hesapla & Yemek Menüsü", "subtitle": "Bolus hesaplayıcı ve aylık okul yemek menüsü yönetimi", "tag": "Diyabet"},
		{"group": "⚡ Hızlı İşlemler", "kind": "page", "value": "🍽️ Yemekhane Yönetimi", "icon": "🍽️", "title": "Yemekhane Yönetimi (Menü, Gider & Kasa)", "subtitle": "Yemekler bankası, iş günü menü planı, A4 çıktı, fatura/gider ve kasa takibi", "tag": "Yemekhane"},
		{"group": "⚡ Hızlı İşlemler", "kind": "new_student", "value": "Öğrenci", "icon": "➕", "title": "Yeni Öğrenci Profili Ekle", "subtitle": "Sağlık profili ve ilk ölçüm formu", "tag": "Çekmece"},
		{"group": "⚡ Hızlı İşlemler", "kind": "new_student", "value": "Sivil / diğer kişi", "icon": "👫", "title": "Yeni Yetişkin / Personel Ekle", "subtitle": "Öğretmen, personel veya veli kaydı oluştur", "tag": "Çekmece"},
		{"group": "⚡ Hızlı İşlemler", "kind": "class_mgr", "value": "", "icon": "🏫", "title": "Okul Sınıfları & Şube Yönetimi", "subtitle": "Sınıf ekle, çıkar veya öğrenci ata", "tag": "Pencere"},
		{"group": "⚡ Hızlı İşlemler", "kind": "page", "value": "📁 Evraklar", "icon": "🛠️", "title": "Evrak Deposu — Word / Excel Düzenle & PDF Doldur", "subtitle": "Evrak deposundaki belgeleri düzenle, PDF form alanlarını tara ve doldur", "tag": "Stüdyo"},
		{"group": "⚡ Hızlı İşlemler", "kind": "toggle_kvkk", "value": "", "icon": "🛡️", "title": "KVKK Ekran Gizliliğini Aç / Kapat", "subtitle": "İsim, telefon ve tıbbi verileri anında maskele", "tag": "Gizlilik"},
	]
	if _cmd_ai_on:
		quick_cmds.extend([
			{"group": "⚡ Hızlı İşlemler", "kind": "smart_doc_import", "value": "", "icon": "🤖", "title": "Belge Oku & Öğrenciye Otomatik İşle (Gemini)", "subtitle": "Sağlık raporu, tahlil, reçete veya ÇÖZGER belgesini okuyup öğrenci dosyasına işle", "tag": "AI"},
			{"group": "⚡ Hızlı İşlemler", "kind": "open_chat", "value": "", "icon": "🤖", "title": "Gemini Klinik Asistanı Aç", "subtitle": "Soru sor, sınıf/etkinlik oluştur, Word/Excel ürettir veya tahlil/evrak yükle (⌘J)", "tag": "AI"},
		])
	for cmd in quick_cmds:
		if not q or q in _tr_fold(cmd["title"]) or q in _tr_fold(cmd["subtitle"]) or q in _tr_fold(cmd["tag"]):
			results.append(cmd)

	# 2. Öğrenci ve Yetişkin Araması (Canlı SQLite — Diyabet & Engel rozetli)
	try:
		with connect_db() as conn:
			idm.ensure_diabetes_tables(conn)
			if q:
				like_q = f"%{q_sql}%"
				like_ascii = f"%{q}%"
				rows = conn.execute(
					"""SELECT s.id, s.full_name, s.student_no, s.person_type, COALESCE(s.has_disability, 0) AS has_dis,
							  COALESCE(c.name, 'Sınıfsız') AS cls,
							  hp.allergies, hp.chronic_conditions,
							  COALESCE(dp.is_diabetic, 0) AS is_diab
					   FROM students s
					   LEFT JOIN classes c ON c.id = s.class_id
					   LEFT JOIN health_profiles hp ON hp.student_id = s.id
					   LEFT JOIN diabetes_profiles dp ON dp.student_id = s.id
					   WHERE lower(s.full_name) LIKE ? OR lower(COALESCE(s.student_no, '')) LIKE ? OR lower(COALESCE(c.name, '')) LIKE ?
					      OR (CASE WHEN COALESCE(dp.is_diabetic, 0) = 1 THEN 'diyabet insulin' ELSE '' END) LIKE ?
					      OR (CASE WHEN COALESCE(s.has_disability, 0) = 1 THEN 'engelli ozel gereksinim' ELSE '' END) LIKE ?
					   ORDER BY COALESCE(dp.is_diabetic, 0) DESC, s.full_name ASC LIMIT 10""",
					(like_q, like_q, like_q, like_ascii, like_ascii),
				).fetchall()
			else:
				rows = conn.execute(
					"""SELECT s.id, s.full_name, s.student_no, s.person_type, COALESCE(s.has_disability, 0) AS has_dis,
							  COALESCE(c.name, 'Sınıfsız') AS cls,
							  hp.allergies, hp.chronic_conditions,
							  COALESCE(dp.is_diabetic, 0) AS is_diab
					   FROM students s
					   LEFT JOIN classes c ON c.id = s.class_id
					   LEFT JOIN health_profiles hp ON hp.student_id = s.id
					   LEFT JOIN diabetes_profiles dp ON dp.student_id = s.id
					   ORDER BY COALESCE(dp.is_diabetic, 0) DESC, s.id DESC LIMIT 6"""
				).fetchall()
		for r in rows:
			disp_nm = mask_kvkk_value(r["full_name"], "name")
			alerts = []
			if int(r["is_diab"] or 0) == 1:
				alerts.append("💙 Diyabet")
			if int(r["has_dis"] or 0) == 1:
				alerts.append("♿ Özel Gereksinim")
			if r["allergies"]:
				alerts.append(f"🔴 {mask_kvkk_value(r['allergies'], 'medical')}")
			if r["chronic_conditions"]:
				alerts.append(f"🟠 {mask_kvkk_value(r['chronic_conditions'], 'medical')}")
			sno_s = f"No: {r['student_no']} · " if r["student_no"] else ""
			sub_s = f"{r['cls']} · {sno_s}" + (" · ".join(alerts) if alerts else "Kişi Dosyasını Aç")
			results.append({
				"group": "👤 Öğrenciler & Kişiler",
				"kind": "person",
				"value": int(r["id"]),
				"icon": "💙" if int(r["is_diab"] or 0) == 1 else ("👫" if str(r["person_type"] or "") != "Öğrenci" else "👤"),
				"title": disp_nm,
				"subtitle": sub_s,
				"tag": "Kişi Dosyası",
			})
	except Exception:
		pass

	# 3. Sayfalar
	for p in PAGES:
		if not q or q in _tr_fold(p):
			ico, lbl = p.split(" ", 1) if " " in p else ("•", p)
			results.append({
				"group": "🧭 Sayfalar",
				"kind": "page",
				"value": p,
				"icon": ico,
				"title": lbl,
				"subtitle": f"{p} modülüne git",
				"tag": "Modül",
			})

	# 4. Ayar Kategorileri
	for sg in SETTINGS_GROUPS_META:
		if not q or q in _tr_fold(sg["key"]) or q in _tr_fold(sg["desc"]) or q in _tr_fold(sg["keywords"]):
			ico, lbl = sg["key"].split(" ", 1) if " " in sg["key"] else ("⚙️", sg["key"])
			results.append({
				"group": "⚙️ Ayarlar",
				"kind": "settings",
				"value": sg["key"],
				"icon": ico,
				"title": lbl,
				"subtitle": sg["desc"],
				"tag": "Ayar",
			})

	# 5. Yemekhane Yemekleri ve Tedarikçileri Araması
	if q:
		try:
			with connect_db() as conn:
				caf.ensure_cafeteria_tables(conn)
				d_rows = conn.execute("SELECT id, name, category, total_kcal FROM cafeteria_dishes ORDER BY name ASC LIMIT 40").fetchall()
				for dr in d_rows:
					if q in _tr_fold(dr["name"]) or q in _tr_fold(dr["category"]):
						results.append({
							"group": "🍽️ Yemekhane",
							"kind": "page",
							"value": "🍽️ Yemekhane Yönetimi",
							"icon": "🍲",
							"title": str(dr["name"]),
							"subtitle": f"{dr['category']} · {float(dr['total_kcal'] or 0):g} kcal",
							"tag": "Yemek",
						})
				p_rows = conn.execute("SELECT DISTINCT supplier_name FROM cafeteria_purchases WHERE TRIM(COALESCE(supplier_name,''))!='' LIMIT 25").fetchall()
				for pr in p_rows:
					if q in _tr_fold(pr["supplier_name"]):
						results.append({
							"group": "🍽️ Yemekhane",
							"kind": "page",
							"value": "🍽️ Yemekhane Yönetimi",
							"icon": "🚚",
							"title": str(pr["supplier_name"]),
							"subtitle": "Yemekhane tedarikçi / fatura kaydı",
							"tag": "Tedarikçi",
						})
		except Exception:
			pass

	return results[:24]


def _handle_cmd_exec(item: dict[str, Any]) -> None:
	kind = str(item.get("kind") or "")
	val = item.get("value")
	if kind == "person" and val:
		pid = int(val)
		set_active_person(pid)
		open_person_dossier_dialog(pid)
	elif kind == "page" and val in PAGES:
		ui.close_dialog(all_dialogs=True)
		ui.session_state["target_page"] = str(val)
		ui.rerun()
	elif kind == "settings":
		ui.close_dialog(all_dialogs=True)
		ui.session_state["settings_vertical_nav"] = str(val or SETTINGS_GROUPS_META[0]["key"])
		ui.session_state["target_page"] = "⚙️ Ayarlar"
		ui.rerun()
	elif kind == "new_student":
		open_new_profile_dialog(str(val or "Öğrenci"))
	elif kind == "class_mgr":
		open_class_manager_dialog()
	elif kind == "smart_doc_import":
		open_smart_document_importer_dialog()
	elif kind == "toggle_kvkk":
		ui.session_state["kvkk_privacy_mode"] = not bool(ui.session_state.get("kvkk_privacy_mode", False))
		ui.rerun(scope="fragment")


def _build_topbar_html(cur_page: str, active_person: dict | sqlite3.Row | None, is_dark: bool, ai_on: bool, ai_model: str, has_ai_key: bool | None = None) -> str:
	active_ay = get_active_academic_year()
	is_arch = active_ay["end_date"] < date.today().isoformat()
	ay_cls = "revir-tb-pill archive" if is_arch else "revir-tb-pill"
	ay_ico = "🏛️ ARŞİV:" if is_arch else "📅"
	ay_txt = f"{ay_ico} {active_ay['name']}"

	page_clean = cur_page.split(" ", 1)[-1] if " " in cur_page else cur_page
	person_crumb = ""
	if active_person:
		p_nm = mask_kvkk_value(active_person["full_name"], "name")
		person_crumb = (
			f"<small>›</small> "
			f"<button type='button' class='revir-tb-pill' style='padding:2px 8px;font-size:12px;' "
			f"title='Aktif kişinin dosyasını aç' onclick=\"window.__revirTopbarAction('open_active_dossier', '')\">"
			f"👤 {html.escape(p_nm)} ({html.escape(str(active_person['class_name'] or ''))})</button>"
		)

	kvkk_on = is_kvkk_privacy_active()
	kvkk_cls = "revir-tb-pill kvkk-on" if kvkk_on else "revir-tb-pill"
	kvkk_lbl = "🛡️ KVKK Açık" if kvkk_on else "🛡️ KVKK"
	dk_ico = "☀️" if is_dark else "🌙"
	dk_tip = "Aydınlık Moda Geç" if is_dark else "Karanlık Moda Geç"
	cfg_tb = get_app_settings()
	has_key_flag = bool(gai.get_api_key(cfg_tb, APP_DIR)) if has_ai_key is None else bool(has_ai_key)
	ai_cls = "revir-tb-pill kvkk-on" if ai_on else "revir-tb-pill"
	if ai_on:
		ai_lbl = f"🤖 AI · {str(ai_model).replace('gemini-', '')}"
	else:
		ai_lbl = "⚪ AI Kapalı"
	if ai_on:
		ai_tip = "AI Modu Açık — Kapatmak için tıklayın"
	elif has_key_flag:
		ai_tip = "AI Modu Kapalı — Açmak için tıklayın"
	else:
		ai_tip = "AI Modu Kapalı (API Anahtarı Yok) — Ayarlamak için tıklayın"

	is_cal_pg = "takvim" in str(cur_page or "").lower()
	box_lay_on = str(cfg_tb.get("box_layout_enabled", "1")).strip() != "0"
	if is_cal_pg:
		layout_btn_html = (
			'<button id="revir-tb-layout-btn" type="button" class="revir-tb-pill" disabled '
			'style="opacity:0.45;cursor:not-allowed;" '
			'title="Takvim sayfası kutucuk düzenlemesinden hariçtir" '
			'onclick="window.__revirToggleLayoutEdit()">🧩 Düzen</button>'
		)
	elif not box_lay_on:
		layout_btn_html = (
			'<button id="revir-tb-layout-btn" type="button" class="revir-tb-pill" disabled '
			'style="opacity:0.55;" '
			'title="Kutucuk düzeni Ayarlar → Görünüm & Düzen bölümünden kapalı" '
			'onclick="window.__revirToggleLayoutEdit()">🧩 Düzen</button>'
		)
	else:
		layout_btn_html = (
			'<button id="revir-tb-layout-btn" type="button" class="revir-tb-pill" '
			'title="Sayfa içindeki kutucukların yerini ve boyutunu değiştir (Takvim hariç)" '
			'onclick="window.__revirToggleLayoutEdit()">🧩 Düzen</button>'
		)

	return (
		f'<div class="revir-tb-left">'
		f'<button type="button" class="revir-tb-icon-btn" title="Yan Menüyü Daralt / Genişlet (Alt+B)" onclick="window.__revirToggleSidebar()">☰</button>'
		f'<div class="revir-tb-crumb">{html.escape(page_clean)} {person_crumb}</div>'
		f'<button type="button" class="{ay_cls}" title="Eğitim Yılını Değiştir" onclick="window.__revirTopbarAction(\'goto_settings_group\', \'🏫 Kurum & Şube\')">{html.escape(ay_txt)}</button>'
		f'</div>'
		f'<div class="revir-tb-center">'
		f'<button type="button" class="revir-tb-search-btn" onclick="window.__revirOpenCmdPalette()">'
		f'<span>🔍 Öğrenci, sayfa veya ayar ara...</span><span class="revir-kbd">⌘K</span></button>'
		f'</div>'
		f'<div class="revir-tb-right">'
		f'{layout_btn_html}'
		f'<button type="button" class="{kvkk_cls}" title="KVKK Ekran Maskelemesini Aç / Kapat" onclick="window.__revirTopbarAction(\'toggle_kvkk\', \'\')">{kvkk_lbl}</button>'
		f'<button type="button" class="revir-tb-icon-btn" title="{dk_tip}" onclick="window.__revirTopbarAction(\'cycle_dark\', \'\')">{dk_ico}</button>'
		f'<button type="button" class="{ai_cls}" title="{html.escape(ai_tip, quote=True)}" onclick="window.__revirTopbarAction(\'toggle_ai\', \'\')">{html.escape(ai_lbl)}</button>'
		f'</div>'
	)


